window.VOCABULARY_INDEX = [{"id":"cs","name":"컴퓨터과학 기초","blurb":"면접에서도, 설계에서도 계속 나온다","terms":[{"id":"cs--async-await","term":"Async/Await","reading":"비동기 문법","category":"컴퓨터과학 기초","summary":"Async/Await는 **비동기 코드를 위에서 아래로 읽히게 쓰는 문법**이다.","aliases":["async/await","비동기 문법","async-await","async","await"],"related":[{"term":"Concurrency","note":"— async/await 가 문법으로 구현하는 개념"},{"term":"Parallelism","note":"— 여러 코어로 진짜 동시에 돌리는 쪽. async/await 로는 안 된다"},{"term":"Thread","note":"— 다른 방식의 동시 실행 수단"},{"term":"Multi-thread","note":"— CPU 작업을 나눌 때 쓰는 쪽"}]},{"id":"cs--big-o","term":"Big O 표기법","reading":"Big O Notation","category":"컴퓨터과학 기초","summary":"Big O는 **데이터가 늘어날 때 시간이 얼마나 늘어나는지 적는 표기**다.","aliases":["big o 표기법","big o notation"],"related":[{"term":"Algorithm","note":"— Big O로 비교하는 대상"},{"term":"Hash","note":"— 평균 O(1) 조회를 만드는 대표적인 방법"},{"term":"Index","note":"— 전체 훑기를 O(log n)으로 바꾸는 장치"},{"term":"자료구조","note":"— 무엇을 고르느냐가 곧 Big O를 정한다"}]},{"id":"cs--binary","term":"Binary","reading":"이진법","category":"컴퓨터과학 기초","summary":"Binary는 **0과 1 두 기호만으로 값을 적는 방식**이다.","aliases":["binary","이진법"],"related":[{"term":"CPU","note":"— 0과 1의 연산을 실제로 수행하는 부품"},{"term":"Memory","note":"— 바이트 단위로 주소를 매겨 비트를 담아두는 곳"},{"term":"RAM","note":"— 그 메모리를 이루는 실제 부품"},{"term":"Hash","note":"— 아무 데이터나 정해진 길이의 비트열로 바꾸는 계산"}]},{"id":"cs--binary-search","term":"Binary Search","reading":"이진 탐색","category":"컴퓨터과학 기초","summary":"Binary Search 는 정렬된 목록의 가운데를 보고 **반을 버리는** 찾기다.","aliases":["binary search","이진 탐색"],"related":[{"term":"Sorting","note":"— 이진 탐색의 전제를 만들어 주는 일. 정렬 없이는 쓸 수 없다"},{"term":"Big O 표기법","note":"— 목록이 두 배로 늘어도 한 번만 더 보는 것이 O(log n) 이다"},{"term":"Hash","note":"— 값 하나를 정확히 집는 일이라면 이쪽이 빠르다. 대신 구간으로는 못 묻는다"},{"term":"Array","note":"— 번호로 아무 자리나 바로 짚을 수 있어야 절반씩 버릴 수 있다"}]},{"id":"cs--blocking-vs-non-blocking","term":"Blocking vs Non-blocking","reading":"블로킹과 논블로킹","category":"컴퓨터과학 기초","summary":"블로킹과 논블로킹은 부른 일이 끝날 때까지 **멈춰 서 있는지**로 갈린다.","aliases":["blocking vs non-blocking","블로킹과 논블로킹","blocking","non-blocking"],"related":[{"term":"Concurrency","note":"— 논블로킹으로 비운 기다림을 다른 작업으로 채우는 상위 개념"},{"term":"Async-Await","note":"— 논블로킹 호출을 위에서 아래로 읽히게 쓰는 문법. 이 개념 위에 얹혀 있다"},{"term":"Thread","note":"— 블로킹 호출을 그대로 두고 갈래를 늘려 처리량을 버는 다른 길"},{"term":"Socket","note":"— 블로킹·논블로킹·타임아웃 셋 중 하나를 실제로 골라 설정하는 통로"}]},{"id":"cs--cpu","term":"CPU","reading":"Central Processing Unit","category":"컴퓨터과학 기초","summary":"CPU는 **명령어를 하나씩 꺼내 실행하는 부품**이다.","aliases":["cpu","central processing unit"],"related":[{"term":"Memory","note":"— CPU가 값을 꺼내 오는 바깥 저장소"},{"term":"Cache","note":"— CPU 옆에 붙어 메모리까지 나가는 횟수를 줄인다"},{"term":"Process","note":"— CPU가 실제로 실행하는 프로그램의 단위"},{"term":"Thread","note":"— 코어 하나가 붙들 수 있는 실행 흐름"},{"term":"Parallelism","note":"— 코어 여러 개를 실제로 같이 쓰는 방식"}]},{"id":"cs--cache","term":"Cache","reading":"캐시","category":"컴퓨터과학 기초","summary":"Cache는 **한 번 구한 결과를 가까운 곳에 두고 다시 쓰는 것**이다.","aliases":["cache","캐시"],"related":[{"term":"Redis","note":"— 여러 서버가 함께 쓰는 캐시의 대표적인 구현"},{"term":"CDN","note":"— 캐시를 사용자 가까이 옮긴 것"},{"term":"TTL","note":"— 캐시를 얼마나 들고 있을지 정하는 값"},{"term":"Memory","note":"— 캐시가 놓이는 자리"}]},{"id":"cs--character-encoding","term":"Character Encoding","reading":"문자 인코딩","category":"컴퓨터과학 기초","summary":"문자 인코딩은 **글자를 바이트로 바꿔 적는 약속**이다.","aliases":["character encoding","문자 인코딩"],"related":[{"term":"Binary","note":"— 그 바이트가 결국 0과 1 로 남는 아래층"},{"term":"Memory","note":"— 바뀐 바이트가 실제로 놓이는 자리"},{"term":"HTML","note":"— 글자로 된 문서라 약속이 어긋나면 그대로 깨진다"},{"term":"JSON","note":"— 글자로 자료를 주고받는 형식이라 같은 문제를 그대로 안는다"}]},{"id":"cs--concurrency","term":"Concurrency","reading":"동시성","category":"컴퓨터과학 기초","summary":"Concurrency는 **여러 작업을 번갈아 진행시키는 방식**이다.","aliases":["concurrency","동시성"],"related":[{"term":"Parallelism","note":"— 여러 코어로 실제로 같은 시각에 돌리는 쪽"},{"term":"Async-Await","note":"— 동시성을 코드로 쓰게 해주는 문법"},{"term":"Thread","note":"— 동시성을 구현하는 또 다른 수단"},{"term":"Process","note":"— 서로 메모리를 나누지 않는 독립 실행 단위"},{"term":"Multi-thread","note":"— 스레드를 여러 개 두고 나누는 방식"}]},{"id":"cs--context-switch","term":"Context Switch","reading":"문맥 교환","category":"컴퓨터과학 기초","summary":"Context Switch는 **CPU가 일감을 바꿀 때 상태를 갈아 끼우는 일**이다.","aliases":["context switch","문맥 교환"],"related":[{"term":"Thread","note":"— 갈아 끼우는 대상. 문맥이 이 단위로 저장된다"},{"term":"CPU","note":"— 한 번에 하나만 도는 자리. 그래서 갈아 끼워야 한다"},{"term":"Process","note":"— 프로세스끼리 바꿀 때는 주소 공간을 가리키는 장부까지 함께 바뀐다"},{"term":"Multi-thread","note":"— 갈래를 늘리면 교환 횟수도 함께 늘어난다"},{"term":"Concurrency","note":"— 하나의 CPU가 여럿을 함께 하는 것처럼 보이게 만드는 결과"}]},{"id":"cs--deadlock","term":"Deadlock","reading":"교착 상태","category":"컴퓨터과학 기초","summary":"Deadlock 은 서로가 쥔 것을 기다리다 **둘 다 멈춰 선** 상태다.","aliases":["deadlock","교착 상태"],"related":[{"term":"Transaction","note":"— 교착이 가장 자주 관찰되는 단위. 취소되는 것도 이 단위다"},{"term":"Mutex vs Semaphore","note":"— 교착을 만드는 잠금 도구 그 자체"},{"term":"Race Condition","note":"— 잠금으로 이것을 막으려다 반대쪽 함정으로 빠진 결과가 교착이다"},{"term":"Thread","note":"— 애플리케이션 안에서 서로를 기다리며 서는 주체"},{"term":"Concurrency","note":"— 여럿이 같은 것을 동시에 노리는, 교착의 전제"}]},{"id":"cs--file-system","term":"File System","reading":"파일 시스템","category":"컴퓨터과학 기초","summary":"File System은 **저장 장치의 칸들을 파일과 폴더로 보이게 하는 규칙**이다.","aliases":["file system","파일 시스템"],"related":[{"term":"Kernel","note":"— 파일 시스템 구현과 VFS 가 실제로 도는 자리"},{"term":"System Call","note":"— `open`·`read`·`write` 로 파일 시스템에 부탁하는 창구"},{"term":"OS","note":"— 파일 시스템을 들고 프로그램에는 이름과 폴더만 보여주는 쪽"},{"term":"Cache","note":"— 경로 조각을 RAM 에 두어 디스크를 덜 뒤지게 하는 장치"}]},{"id":"cs--floating-point","term":"Floating Point","reading":"부동소수점","category":"컴퓨터과학 기초","summary":"부동소수점은 **소수를 2진 근삿값으로 담는 수 형식**이다.","aliases":["floating point","부동소수점"],"related":[{"term":"Binary","note":"— 10진 소수를 정확히 담을 수 없는 이유가 있는 아래층"},{"term":"Variable","note":"— 값을 어떤 형식으로 담을지 고르는 자리"},{"term":"CPU","note":"— 이 형식의 계산을 실제로 수행하는 쪽"},{"term":"Memory","note":"— 64비트가 실제로 놓이는 자리"}]},{"id":"cs--garbage-collection","term":"Garbage Collection","reading":"가비지 컬렉션","category":"컴퓨터과학 기초","summary":"Garbage Collection은 **쓰지 않게 된 메모리를 알아서 거둬 가는 일**이다.","aliases":["garbage collection","가비지 컬렉션"],"related":[{"term":"Memory","note":"— 거둬 가는 대상이 놓여 있는 자리"},{"term":"Object","note":"— 수집기가 세고 거두는 단위"},{"term":"Variable","note":"— 객체를 붙잡고 있는 이름. 이 참조가 남아 있으면 안 거둔다"},{"term":"Heap","note":"— 실행 도중에 얻어 쓰는 메모리 영역을 부르는 같은 이름. 수집기가 훑는 곳이 그쪽이다"},{"term":"Cache","note":"— 참조를 오래 붙잡아 두어 누수를 만드는 대표적인 자리"}]},{"id":"cs--graph","term":"Graph","reading":"그래프","category":"컴퓨터과학 기초","summary":"Graph 는 마디와 **이음선**으로 무엇이 무엇과 이어졌는지 적는 자료구조다.","aliases":["graph","그래프"],"related":[{"term":"자료구조","note":"— 마디와 이음선이라는 짜임 하나가 곧 이 자료구조다"},{"term":"Tree","note":"— 되돌아오는 길이 없는 그래프. 그래서 훑기가 훨씬 단순하다"},{"term":"Sorting","note":"— 위상 정렬은 값의 크기가 아니라 선후로 줄을 세우는 정렬이다"},{"term":"Algorithm","note":"— 순환 찾기·위상 정렬처럼 그래프 위에서 도는 절차들"}]},{"id":"cs--hash","term":"Hash","reading":"해시","category":"컴퓨터과학 기초","summary":"Hash는 **아무 길이의 값을 정해진 길이의 숫자로 바꾸는 계산**이다.","aliases":["hash","해시"],"related":[{"term":"Dictionary","note":"— 해시 테이블로 만들어진 자료구조"},{"term":"Big O 표기법","note":"— 해시가 왜 빠른지를 적는 방법"},{"term":"암호화","note":"— 되돌릴 수 있다는 점이 해시와 다르다"},{"term":"Index","note":"— DB에서 조회를 빠르게 하는 다른 장치"}]},{"id":"cs--hash-table","term":"Hash Table","reading":"해시 테이블","category":"컴퓨터과학 기초","summary":"Hash Table 은 **열쇠를 계산해 값의 칸을 정하는 자료구조**다.","aliases":["hash table","해시 테이블"],"related":[{"term":"Hash","note":"— 어느 칸에 앉을지 계산하는 함수. 이 그릇의 부품이다"},{"term":"Dictionary","note":"— 언어가 이 자료구조에 이름을 붙여 내놓은 것"},{"term":"Array","note":"— 칸을 한 줄로 잡아 두는 바탕. 번호로만 찾는 한계가 출발점이다"},{"term":"Tree","note":"— 순서와 범위를 함께 다뤄야 할 때 대신 고르는 모양"},{"term":"Big O 표기법","note":"— 평균 O(1) 과 무너진 뒤를 견주어 적는 표기"}]},{"id":"cs--heap","term":"Heap","reading":"힙","category":"컴퓨터과학 기초","summary":"Heap 은 **꼭대기에 항상 최댓값이나 최솟값이 오는 트리**다.","aliases":["heap","힙"],"related":[{"term":"Stack","note":"— 함수가 쓰고 반납하는 메모리 영역. 힙과 짝을 이룬다"},{"term":"Queue","note":"— 들어온 순서로 꺼내는 쪽. 힙은 우선순위로 꺼낸다"},{"term":"자료구조","note":"— 힙이 속한 갈래"},{"term":"Memory","note":"— 힙이 놓이는 자리"},{"term":"Big O 표기법","note":"— 넣고 꺼내는 비용을 재는 잣대"}]},{"id":"cs--interrupt","term":"Interrupt","reading":"인터럽트","category":"컴퓨터과학 기초","summary":"인터럽트는 **일이 생겼을 때 장치가 CPU 를 불러 세우는 신호**다.","aliases":["interrupt","인터럽트"],"related":[{"term":"CPU","note":"— 신호를 받고 하던 일을 멈추는 쪽"},{"term":"Context Switch","note":"— 멈춘 자리를 저장하고 되돌아오는 그 동작"},{"term":"Process","note":"— 인터럽트 덕에 CPU 를 번갈아 쓸 수 있게 되는 단위"},{"term":"Async-Await","note":"— 기다리지 않고 불려 가는 같은 발상을 코드에서 쓴 것"}]},{"id":"cs--kernel","term":"Kernel","reading":"커널","category":"컴퓨터과학 기초","summary":"Kernel은 **하드웨어에 직접 닿는 운영체제의 가장 안쪽 층**이다.","aliases":["kernel","커널"],"related":[{"term":"OS","note":"— 커널을 감싸 사람이 쓸 수 있게 묶어 놓은 전체"},{"term":"System Call","note":"— 사용자 모드에서 커널로 넘어가는 경계 그 자체"},{"term":"Process","note":"— 커널이 CPU 를 짧게 갈라 나눠주는 단위"},{"term":"Memory","note":"— 커널이 가상 주소로 갈라 관리하는 자원"},{"term":"Linux","note":"— 커널 이름이 그대로 운영체제 이름이 된 대표적 예"}]},{"id":"cs--linked-list","term":"Linked List","reading":"연결 리스트","category":"컴퓨터과학 기초","summary":"Linked List 는 **값마다 다음 값의 자리를 들고 있는 자료구조**다.","aliases":["linked list","연결 리스트"],"related":[{"term":"Array","note":"— 자리를 계산해 곧장 가는 반대쪽 모양"},{"term":"자료구조","note":"— 이 모양이 어느 자리에 맞는지 고르는 기준을 다루는 상위 단어"},{"term":"Queue","note":"— 앞뒤로 드나드는 대기열을 이 모양으로 만든다"},{"term":"Hash Table","note":"— 한 칸에 몰린 값들을 이 모양으로 이어 붙인다"},{"term":"Big O 표기법","note":"— 꺼내기와 끼우기의 값을 견주어 적는 표기"}]},{"id":"cs--linux","term":"Linux","reading":"리눅스","category":"컴퓨터과학 기초","summary":"Linux는 **누구나 뜯어보고 고칠 수 있는 운영체제**다.","aliases":["linux","리눅스"],"related":[{"term":"OS","note":"— 리눅스가 속한 갈래"},{"term":"Terminal","note":"— 리눅스에 명령을 넣는 창"},{"term":"CLI","note":"— 리눅스를 다루는 주된 방식"},{"term":"Windows","note":"— 개인 컴퓨터 쪽에서 자리를 잡은 다른 운영체제"},{"term":"Container","note":"— 안쪽이 대개 리눅스로 채워지는 실행 단위"}]},{"id":"cs--memory","term":"Memory","reading":"메모리","category":"컴퓨터과학 기초","summary":"메모리는 **지금 쓰는 데이터를 잠시 올려두는 자리**다.","aliases":["memory","메모리"],"related":[{"term":"CPU","note":"— 메모리에서 값을 꺼내 계산하는 쪽"},{"term":"Cache","note":"— 메모리 계층의 위쪽. 자주 쓰는 값을 붙들어 둔다"},{"term":"RAM","note":"— 실행 중인 프로그램이 올라가 있는 층"},{"term":"Process","note":"— 메모리를 나눠 받아 돌아가는 단위"}]},{"id":"cs--multi-thread","term":"Multi-thread","reading":"멀티 스레드","category":"컴퓨터과학 기초","summary":"Multi-thread는 **한 프로그램 안에서 일을 여러 갈래로 나눠 돌리는 방식**이다.","aliases":["multi-thread","멀티 스레드"],"related":[{"term":"Thread","note":"— 갈래 하나를 가리키는 말. 여럿을 함께 돌리는 것이 여기다"},{"term":"Process","note":"— 메모리를 따로 쓰는 단위. 스레드는 그 안에서 메모리를 공유한다"},{"term":"Concurrency","note":"— 여러 일을 번갈아 진행하는 개념"},{"term":"Parallelism","note":"— 코어를 여러 개 써서 실제로 동시에 돌리는 것"},{"term":"Queue","note":"— 갈래들이 작업을 주고받을 때 쓰는 안전한 통로"}]},{"id":"cs--mutex-vs-semaphore","term":"Mutex vs Semaphore","reading":"뮤텍스와 세마포어","category":"컴퓨터과학 기초","summary":"뮤텍스는 한 명만 들이고, 세마포어는 **정한 수만큼** 들인다.","aliases":["mutex vs semaphore","뮤텍스와 세마포어","mutex","semaphore"],"related":[{"term":"Deadlock","note":"— 잠금을 여러 개 쓰다 순서가 어긋날 때 빠지는 함정"},{"term":"Race Condition","note":"— 이 둘로 막으려는 바로 그 문제"},{"term":"Thread","note":"— 잠금 앞에 줄을 서는 주체"},{"term":"Concurrency","note":"— 자리 수를 정해야 하는 상황을 만드는 전제"},{"term":"Connection Pool","note":"— 세마포어로 상한을 지키는 대표적인 자원"}]},{"id":"cs--os","term":"OS","reading":"Operating System, 운영체제","category":"컴퓨터과학 기초","summary":"OS는 **프로그램과 하드웨어 사이에서 자원을 나눠주는 소프트웨어**다.","aliases":["os","operating system, 운영체제"],"related":[{"term":"Process","note":"— 운영체제가 CPU를 나눠주는 단위"},{"term":"Memory","note":"— 운영체제가 프로그램마다 갈라주는 자원"},{"term":"Linux","note":"— 서버에서 널리 쓰이는 운영체제"},{"term":"Windows","note":"— 데스크톱에서 널리 쓰이는 운영체제"}]},{"id":"cs--parallelism","term":"Parallelism","reading":"병렬성","category":"컴퓨터과학 기초","summary":"Parallelism은 **여러 코어가 같은 시간에 각자 일하는 것**이다.","aliases":["parallelism","병렬성"],"related":[{"term":"Concurrency","note":"— 번갈아 하는 쪽. 기다림이 긴 일에 쓴다"},{"term":"Process","note":"— 병렬 처리에서 코어마다 하나씩 얹는 실행 단위"},{"term":"Multi-thread","note":"— 메모리를 나눠 쓰는 방식. 파이썬에서는 GIL에 막힌다"},{"term":"CPU","note":"— 코어 개수가 병렬로 어디까지 갈 수 있는지를 정한다"}]},{"id":"cs--process","term":"Process","reading":"프로세스","category":"컴퓨터과학 기초","summary":"Process는 **실행 중인 프로그램**이다.","aliases":["process","프로세스"],"related":[{"term":"Thread","note":"— 프로세스 안에서 갈라지는 실행 흐름"},{"term":"Memory","note":"— 프로세스가 올라가 자리를 잡는 곳"},{"term":"CPU","note":"— 프로세스가 차례를 받아 도는 하드웨어"},{"term":"Stack","note":"— 함수 호출과 지역 변수가 쌓이는 영역"},{"term":"Concurrency","note":"— 여러 실행 단위를 번갈아 돌리는 방식"}]},{"id":"cs--queue","term":"Queue","reading":"큐","category":"컴퓨터과학 기초","summary":"Queue는 **먼저 넣은 것을 먼저 꺼내는 자료구조**다.","aliases":["queue","큐"],"related":[{"term":"Stack","note":"— 마지막에 넣은 것을 먼저 꺼내는 반대 구조"},{"term":"Message Queue","note":"— 같은 개념을 서버 사이에 둔 것"},{"term":"자료구조","note":"— 큐가 속한 갈래"},{"term":"Algorithm","note":"— 큐를 쓰는 대표적인 탐색 방법이 여기 있다"}]},{"id":"cs--ram","term":"RAM","reading":"Random Access Memory","category":"컴퓨터과학 기초","summary":"RAM은 **실행 중인 것만 올려두는 작업 공간**이다.","aliases":["ram","random access memory"],"related":[{"term":"Memory","note":"— RAM 을 포함한 기억 장치 전체를 가리키는 말"},{"term":"Cache","note":"— RAM 보다 위에 있는 더 빠르고 작은 층"},{"term":"CPU","note":"— RAM 에서 값을 꺼내 계산하는 쪽"},{"term":"Process","note":"— 실행되면서 RAM 을 차지하는 단위"},{"term":"Heap","note":"— 프로그램이 실행 중에 RAM 을 받아 쓰는 영역"}]},{"id":"cs--race-condition","term":"Race Condition","reading":"경쟁 상태","category":"컴퓨터과학 기초","summary":"Race Condition 은 **누가 먼저 닿는지**에 따라 결과가 달라지는 버그다.","aliases":["race condition","경쟁 상태"],"related":[{"term":"Mutex vs Semaphore","note":"— 순서를 정해주는 도구. 경쟁 상태를 막는 정공법이다"},{"term":"Deadlock","note":"— 경쟁 상태를 잠금으로 막으려다 반대쪽으로 빠지는 함정"},{"term":"Concurrency","note":"— 여럿이 번갈아 진행하는, 경쟁 상태의 전제"},{"term":"Thread","note":"— 서로 끼어드는 주체"},{"term":"Transaction","note":"— 데이터베이스가 여러 갱신을 한 덩어리로 묶어 같은 문제를 막는 단위"}]},{"id":"cs--sorting","term":"Sorting","reading":"정렬","category":"컴퓨터과학 기초","summary":"Sorting 은 값을 정해진 순서대로 **줄 세우는** 일이다.","aliases":["sorting","정렬"],"related":[{"term":"Binary Search","note":"— 정렬을 전제로만 쓸 수 있는 찾기. 정렬이 사 주는 대표적인 값이다"},{"term":"Big O 표기법","note":"— 정렬 한 번의 값이 O(n log n) 으로 적히는 그 표기다"},{"term":"Hash","note":"— 값 하나를 정확히 집는 일은 줄 세우지 않고 이쪽으로 한다"},{"term":"Heap","note":"— 전부 줄 세우지 않고 상위 몇 개만 손에 들 때 쓰는 짜임"},{"term":"Graph","note":"— 위상 정렬은 값의 크기가 아니라 선후로 줄을 세우는 정렬이다"}]},{"id":"cs--stack","term":"Stack","reading":"스택","category":"컴퓨터과학 기초","summary":"Stack은 **마지막에 넣은 것을 먼저 꺼내는 자료구조**다.","aliases":["stack","스택"],"related":[{"term":"Queue","note":"— 먼저 넣은 것을 먼저 꺼내는 반대 구조"},{"term":"Heap","note":"— 스택과 나뉘어 쓰이는 다른 메모리 영역"},{"term":"Recursion","note":"— 스택 깊이를 가장 빨리 쓰는 방식"},{"term":"Memory","note":"— 스택 영역이 놓이는 자리"}]},{"id":"cs--system-call","term":"System Call","reading":"시스템 콜","category":"컴퓨터과학 기초","summary":"System Call은 **프로그램이 커널에 일을 시키는 유일한 창구**다.","aliases":["system call","시스템 콜"],"related":[{"term":"Kernel","note":"— 이 창구 너머에서 실제로 일을 하는 쪽"},{"term":"OS","note":"— 시스템 콜은 그 운영체제가 프로그램에 내놓은 창구 목록이다"},{"term":"Process","note":"— 시스템 콜을 부르는 주체이자, 커널이 대신 관리해 주는 단위"},{"term":"Memory","note":"— 메모리를 더 달라는 것도 이 창구로 부탁한다"},{"term":"Container","note":"— 허용할 시스템 콜만 골라 남겨 두는 대표적 자리"}]},{"id":"cs--thread","term":"Thread","reading":"스레드","category":"컴퓨터과학 기초","summary":"Thread는 **한 프로그램 안에서 따로 도는 실행 흐름**이다.","aliases":["thread","스레드"],"related":[{"term":"Process","note":"— 스레드를 담고 있는 독립된 실행 단위"},{"term":"Concurrency","note":"— 여러 일을 번갈아 진행하는 개념"},{"term":"Parallelism","note":"— 실제로 동시에 도는 것. 코어가 여럿이어야 한다"},{"term":"Multi-thread","note":"— 스레드를 여러 개 쓰는 방식"}]},{"id":"cs--tree","term":"Tree","reading":"트리","category":"컴퓨터과학 기초","summary":"Tree 는 **한 뿌리에서 아래로 갈라져 내려가는 구조**다.","aliases":["tree","트리"],"related":[{"term":"자료구조","note":"— 이 모양이 어느 자리에 맞는지 고르는 기준을 다루는 상위 단어"},{"term":"Heap","note":"— 부모와 자식 사이 크기 규칙만 지키는 트리"},{"term":"B-Tree","note":"— 한 마디를 여러 갈래로 넓혀 디스크에 맞춘 트리"},{"term":"Hash Table","note":"— 순서와 범위가 필요 없을 때 대신 고르는 모양"},{"term":"Big O 표기법","note":"— O(log n) 이 무슨 뜻인지 적는 표기"}]},{"id":"cs--virtual-memory","term":"Virtual Memory","reading":"가상 메모리","category":"컴퓨터과학 기초","summary":"Virtual Memory는 **프로그램마다 메모리를 혼자 통째로 쓰는 것처럼 보여주는 장치**다.","aliases":["virtual memory","가상 메모리"],"related":[{"term":"RAM","note":"— 가상 주소가 실제로 놓이는 자리. 여기 올라와 있는 몫이 작업 집합이다"},{"term":"Memory","note":"— 빠른 층부터 느린 층까지 겹쳐 쓰는 구조. 가상 메모리가 그 층을 감춰 준다"},{"term":"Process","note":"— 주소 범위와 장부를 하나씩 따로 받는 단위"},{"term":"OS","note":"— 장부를 관리하고 페이지를 올렸다 내리는 주체"},{"term":"Context Switch","note":"— 프로세스를 바꿀 때 이 장부까지 함께 갈아 끼운다"}]},{"id":"cs--windows","term":"Windows","reading":"윈도우","category":"컴퓨터과학 기초","summary":"Windows는 **마이크로소프트가 만든 데스크톱 운영체제**다.","aliases":["windows","윈도우"],"related":[{"term":"OS","note":"— Windows가 속한 갈래"},{"term":"Linux","note":"— 서버 쪽에서 더 많이 쓰이는 다른 운영체제"},{"term":"CLI","note":"— CMD와 PowerShell이 여기에 해당한다"},{"term":"Process","note":"— 작업 관리자에 목록으로 보이는 것"}]},{"id":"cs--term-36813d92","term":"알고리즘","reading":"Algorithm","category":"컴퓨터과학 기초","summary":"알고리즘은 **문제를 푸는 절차를 단계로 적어둔 것**이다.","aliases":["알고리즘","algorithm"],"related":[{"term":"Big O 표기법","note":"— 시간이 늘어나는 모양을 적는 표기"},{"term":"자료구조","note":"— 데이터를 어떻게 담아두느냐가 쓸 수 있는 절차를 정한다"},{"term":"Recursion","note":"— 문제를 같은 모양의 작은 문제로 쪼갤 때 쓰는 방식"},{"term":"Hash","note":"— 이미 본 값을 기록해두고 한 번에 찾을 때 쓰인다"},{"term":"CPU","note":"— 절차를 실제로 실행하는 곳. 비교 횟수가 곧 여기서 도는 시간이다"}]},{"id":"cs--term-ffa8fb5a","term":"자료구조","reading":"Data Structure","category":"컴퓨터과학 기초","summary":"자료구조는 **데이터를 어떤 모양으로 담아둘지 정해 놓은 방식**이다.","aliases":["자료구조","data structure"],"related":[{"term":"Array","note":"— 한 줄로 늘어놓는 가장 기본 모양"},{"term":"Hash","note":"— 열쇠를 계산해 자리를 정하는 방식"},{"term":"Stack","note":"— 마지막에 넣은 것을 먼저 꺼내는 줄"},{"term":"Queue","note":"— 처음 넣은 것을 먼저 꺼내는 줄"},{"term":"Big O 표기법","note":"— 어느 쪽이 빠른지 견주어 적는 표기"}]}]},{"id":"lang","name":"프로그래밍","blurb":"코드를 이루는 말들","terms":[{"id":"lang--array-list","term":"Array / List","reading":"배열 / 리스트","category":"프로그래밍","summary":"Array는 **여러 값을 번호 순서대로 담아두는 그릇**이다.","aliases":["array / list","배열 / 리스트","array","list","배열","리스트"],"related":[{"term":"Dictionary","note":"— 번호 대신 이름으로 값을 꺼내는 자료구조"},{"term":"Loop","note":"— 배열을 처음부터 끝까지 도는 데 쓴다"},{"term":"Variable","note":"— 배열도 결국 변수 하나에 담긴다"},{"term":"Big O 표기법","note":"— 번호로 꺼내기와 가운데 끼우기의 비용 차이를 재는 잣대"}]},{"id":"lang--build","term":"Build","reading":"빌드","category":"프로그래밍","summary":"Build는 **소스 코드를 실행할 수 있는 형태로 만드는 과정**이다.","aliases":["build","빌드"],"related":[{"term":"Compile","note":"— 소스를 실행 가능한 형태로 바꾸는 단계. 빌드의 일부다"},{"term":"CI_CD","note":"— 코드가 올라올 때마다 빌드와 배포를 자동으로 돌리는 구조"},{"term":"Docker","note":"— 빌드 환경까지 이미지에 담아 결과를 같게 만드는 도구"},{"term":"Package","note":"— 빌드가 받아 오는 외부 의존성의 단위"},{"term":"Environment Variable","note":"— 빌드 시점에 값이 달라지는 설정을 넣는 자리"}]},{"id":"lang--csv","term":"CSV","reading":"Comma-Separated Values","category":"프로그래밍","summary":"CSV는 **쉼표로 값을 나눈 표 데이터 텍스트 파일**이다.","aliases":["csv","comma-separated values"],"related":[{"term":"JSON","note":"— 중첩된 구조를 담을 수 있는 형식. CSV는 표 하나만 담는다"},{"term":"XML","note":"— 태그로 구조를 표현하는 또 다른 교환 형식"},{"term":"SQL","note":"— 조회 결과를 CSV로 내보내는 일이 잦다"},{"term":"구조화 데이터","note":"— CSV가 속한 갈래. 미리 정해진 틀에 값을 채우는 데이터"}]},{"id":"lang--class","term":"Class","reading":"클래스","category":"프로그래밍","summary":"Class는 **데이터와 기능을 한 덩어리로 묶은 설계도**다.","aliases":["class","클래스"],"related":[{"term":"Object","note":"— 클래스로 찍어낸 실체. 값은 여기에 들어 있다"},{"term":"Function","note":"— 같은 것이 클래스 안으로 들어가면 메서드가 된다"},{"term":"Variable","note":"— 같은 것이 클래스 안으로 들어가면 속성이 된다"},{"term":"Component","note":"— 화면 조각을 같은 방식으로 묶어 재사용하는 단위"}]},{"id":"lang--compile","term":"Compile","reading":"컴파일","category":"프로그래밍","summary":"컴파일은 **사람이 쓴 코드를 기계어로 미리 번역하는 일**이다.","aliases":["compile","컴파일"],"related":[{"term":"Build","note":"— 컴파일과 링킹, 포장까지 묶은 더 넓은 과정"},{"term":"Compile vs Interpret","note":"— 미리 번역해두는 쪽과 그때그때 해석하는 쪽의 차이"},{"term":"Binary","note":"— 컴파일 결과로 나오는 0과 1의 형태"},{"term":"CPU","note":"— 컴파일된 기계어를 실제로 읽는 쪽"}]},{"id":"lang--compile-vs-interpret","term":"Compile vs Interpret","reading":"컴파일 vs 인터프리트","category":"프로그래밍","summary":"컴파일과 인터프리트는 **코드를 기계가 실행하게 만드는 두 방식**이다.","aliases":["compile vs interpret","컴파일 vs 인터프리트","interpret","인터프리트"],"related":[{"term":"Compile","note":"— 이 글의 한쪽. 실행 전에 한 번에 옮기는 방식"},{"term":"Build","note":"— 컴파일을 포함해 돌릴 수 있는 결과물을 만들어내는 전체 작업"},{"term":"CPU","note":"— 옮겨진 기계어를 실제로 실행하는 쪽"},{"term":"Binary","note":"— 컴파일 결과로 남는 파일의 형태"}]},{"id":"lang--component","term":"Component","reading":"컴포넌트","category":"프로그래밍","summary":"Component는 **화면의 한 조각을 떼어내 재사용하는 단위**다.","aliases":["component","컴포넌트"],"related":[{"term":"Frontend","note":"— 컴포넌트를 조립해 화면을 만드는 쪽"},{"term":"CSR","note":"— 브라우저가 컴포넌트를 조립해 화면을 그리는 방식"},{"term":"SPA","note":"— 화면 전체를 컴포넌트 트리로 두고 부분만 갈아 끼우는 구조"},{"term":"Function","note":"— 값을 돌려주는 함수와 달리 컴포넌트는 화면 조각을 돌려준다"},{"term":"Framework vs Library","note":"— 컴포넌트를 어떤 규칙으로 조립할지는 프레임워크가 정한다"}]},{"id":"lang--dictionary-map","term":"Dictionary / Map","reading":"딕셔너리 / 맵","category":"프로그래밍","summary":"Dictionary는 **이름표를 붙여 값을 넣어두는 자료구조**다.","aliases":["dictionary / map","딕셔너리 / 맵","dictionary","map"],"related":[{"term":"Hash","note":"— 키를 칸 번호로 바꾸는 계산. 딕셔너리가 빠른 이유다"},{"term":"Array","note":"— 순서 번호로 찾는 쪽. 딕셔너리와 대비된다"},{"term":"Object","note":"— 여기에 기능까지 함께 묶은 것"},{"term":"JSON","note":"— 딕셔너리 모양을 그대로 글자로 적는 형식"},{"term":"자료구조","note":"— 딕셔너리가 속한 큰 갈래"}]},{"id":"lang--framework-vs-library","term":"Framework vs Library","reading":"프레임워크와 라이브러리","category":"프로그래밍","summary":"둘의 차이는 **누가 누구를 부르느냐** 하나로 갈린다.","aliases":["framework vs library","프레임워크와 라이브러리","framework","library"],"related":[{"term":"Package","note":"— 라이브러리를 묶어 배포하고 설치하는 단위"},{"term":"SDK","note":"— 특정 서비스를 쓰라고 묶어 주는 도구 모음. 대개 라이브러리 쪽이다"},{"term":"Component","note":"— 프레임워크가 정해진 시점에 불러 쓰는 단위의 대표적인 예"},{"term":"Build","note":"— 프레임워크가 정한 구조대로 코드를 묶어 내보내는 단계"}]},{"id":"lang--function","term":"Function","reading":"함수","category":"프로그래밍","summary":"Function은 **이름을 붙여 다시 부를 수 있게 묶어둔 코드**다.","aliases":["function","함수"],"related":[{"term":"Variable","note":"— 함수가 받는 값과 돌려주는 값이 담기는 자리"},{"term":"Class","note":"— 함수가 클래스 안으로 들어가면 메서드가 된다"},{"term":"Recursion","note":"— 함수가 자기 자신을 부르는 방식"},{"term":"Loop","note":"— 반복하는 부분을 함수로 감싸 이름을 붙이는 일이 흔하다"}]},{"id":"lang--json","term":"JSON","reading":"JavaScript Object Notation","category":"프로그래밍","summary":"JSON 은 **프로그램끼리 데이터를 주고받으려고 적어두는 텍스트 형식**이다.","aliases":["json","javascript object notation"],"related":[{"term":"API","note":"— JSON 이 가장 많이 오가는 자리"},{"term":"YAML","note":"— 사람이 쓰기 편한 쪽으로 기운 형식"},{"term":"XML","note":"— JSON 이전에 같은 자리를 맡던 형식"},{"term":"CSV","note":"— 표 모양 데이터를 주고받는 더 단순한 형식"}]},{"id":"lang--loop","term":"Loop","reading":"반복문","category":"프로그래밍","summary":"Loop 는 **같은 코드를 조건이 끝날 때까지 다시 실행하는 구조**다.","aliases":["loop","반복문"],"related":[{"term":"Array","note":"— 반복문이 가장 많이 도는 대상"},{"term":"Recursion","note":"— 같은 일을 함수 호출로 되풀이하는 다른 방법"},{"term":"Big O 표기법","note":"— 반복이 겹칠수록 커지는 비용을 재는 잣대"},{"term":"Function","note":"— 되풀이할 일을 이름 붙여 떼어내는 쪽"}]},{"id":"lang--object","term":"Object","reading":"객체","category":"프로그래밍","summary":"Object는 **데이터와 그 데이터를 다루는 기능을 한 덩어리로 묶은 것**이다.","aliases":["object","객체"],"related":[{"term":"Class","note":"— 객체를 만들어내는 설계도"},{"term":"Variable","note":"— 객체가 있는 자리를 가리키는 이름"},{"term":"Function","note":"— 객체 안에 들어가면 메서드가 된다"},{"term":"Dictionary","note":"— 값만 묶는 쪽. 객체는 여기에 기능까지 넣는다"},{"term":"Memory","note":"— 객체가 실제로 자리를 잡는 곳"}]},{"id":"lang--package-module","term":"Package / Module","reading":"패키지 / 모듈","category":"프로그래밍","summary":"Module은 코드 파일 하나고, **Package는 그 파일들을 묶은 폴더**다.","aliases":["package / module","패키지 / 모듈","package","module","패키지","모듈"],"related":[{"term":"Function","note":"— 모듈 안에 담기는 것"},{"term":"Class","note":"— 모듈 안에 담기는 또 하나"},{"term":"Framework vs Library","note":"— 남이 만든 패키지를 쓰는 두 방식"},{"term":"Build","note":"— 흩어진 모듈을 하나로 묶어 내보내는 단계"}]},{"id":"lang--recursion","term":"Recursion","reading":"재귀","category":"프로그래밍","summary":"Recursion은 **함수가 자기 자신을 부르는 방식**이다.","aliases":["recursion","재귀"],"related":[{"term":"Function","note":"— 재귀가 딛고 서는 단위"},{"term":"Stack","note":"— 아직 답을 못 받은 호출이 쌓이는 곳"},{"term":"Loop","note":"— 같은 일을 하는 다른 방법. 비용 계산이 반대다"},{"term":"Algorithm","note":"— 분할 정복처럼 재귀를 전제로 짜인 것들이 있다"},{"term":"자료구조","note":"— 트리처럼 자기 안에 자기를 품은 구조와 잘 맞는다"}]},{"id":"lang--variable","term":"Variable","reading":"변수","category":"프로그래밍","summary":"Variable은 **값에 이름을 붙여두는 자리**다.","aliases":["variable","변수"],"related":[{"term":"Memory","note":"— 변수가 실제로 자리를 잡는 곳"},{"term":"Function","note":"— 지역 변수의 범위를 정하는 단위"},{"term":"Class","note":"— 변수를 속성으로 묶어 두는 틀"},{"term":"Object","note":"— 이름이 값이 아니라 가리키는 표시를 담는 대표적인 예"},{"term":"Loop","note":"— 변수에 값을 누적하며 도는 구조"}]},{"id":"lang--xml","term":"XML","reading":"eXtensible Markup Language","category":"프로그래밍","summary":"XML은 **여는 태그와 닫는 태그로 데이터의 구조를 적는 형식**이다.","aliases":["xml","extensible markup language"],"related":[{"term":"JSON","note":"— 같은 일을 더 짧게 적는 형식. 웹 API 에서 주로 쓰인다"},{"term":"YAML","note":"— 사람이 쓰기 쉬운 쪽으로 만든 설정 형식"},{"term":"CSV","note":"— 값만 나열하는 형식. 계층을 담지 못한다"},{"term":"API","note":"— XML 이 요청과 응답의 본문으로 쓰이는 자리"}]},{"id":"lang--yaml","term":"YAML","reading":"YAML Ain't Markup Language","category":"프로그래밍","summary":"YAML은 **들여쓰기로 구조를 나타내는 설정 파일 형식**이다.","aliases":["yaml","yaml ain't markup language"],"related":[{"term":"JSON","note":"— 같은 데이터를 괄호로 표현하는 형식. 프로그램끼리 주고받을 때 쓴다"},{"term":"Docker","note":"— 컨테이너 구성을 YAML 파일로 적는다"},{"term":"Kubernetes","note":"— 원하는 상태를 YAML로 적어 넘긴다"},{"term":"Environment Variable","note":"— 비밀번호처럼 파일에 적으면 안 되는 값을 대신 넣는 자리"}]},{"id":"lang--term-ac6828de","term":"정규표현식","reading":"Regex / Regular Expression","category":"프로그래밍","summary":"정규표현식은 **글자의 모양을 규칙으로 적어 찾아내는 문법**이다.","aliases":["정규표현식","regex / regular expression","regex","regular expression"],"related":[{"term":"PII","note":"— 주민번호나 전화번호 모양을 정규식으로 찾아 가린다"},{"term":"Guardrail","note":"— 정규식으로 만든 검사 규칙을 모아둔 장치"},{"term":"SQL Injection","note":"— 정규식 검증만 믿으면 막지 못하는 공격"},{"term":"Compile","note":"— 패턴도 쓰기 전에 한 번 내부 형태로 바꾼다"}]}]},{"id":"net","name":"네트워크","blurb":"요청이 오가는 길","terms":[{"id":"net--arp","term":"ARP","reading":"Address Resolution Protocol","category":"네트워크","summary":"ARP는 **IP 주소로 그 장비의 MAC 주소를 알아내는 규칙**이다.","aliases":["arp","address resolution protocol"],"related":[{"term":"MAC Address","note":"— ARP 가 알아내려는 바로 그 번호"},{"term":"IP Address","note":"— 이미 알고 있는 쪽. 이것을 들고 묻는다"},{"term":"Router vs Switch","note":"— 망 밖으로 나갈 때 ARP 가 대신 물어보는 상대"},{"term":"Subnet","note":"— 같은 망인지 밖인지를 가르는 기준"},{"term":"OSI 7계층","note":"— 3계층 주소와 2계층 주소가 만나는 자리"}]},{"id":"net--bandwidth","term":"Bandwidth","reading":"대역폭","category":"네트워크","summary":"Bandwidth 는 **일정 시간에 회선을 지날 수 있는 정보량**이다.","aliases":["bandwidth","대역폭"],"related":[{"term":"Latency","note":"— 같은 \"느리다\"를 굵기가 아니라 길이 쪽에서 재는 짝 개념"},{"term":"CDN","note":"— 굵기 대신 거리를 줄여 왕복 시간을 깎는 장치"},{"term":"Caching","note":"— 회선을 지나갈 양 자체를 없애서 굵기를 덜 쓰게 하는 방법"},{"term":"Core Web Vitals","note":"— 굵기도 길이도 아닌, 사용자가 본 결과로 속도를 재는 지표"}]},{"id":"net--cdn","term":"CDN","reading":"Content Delivery Network","category":"네트워크","summary":"CDN은 **파일을 사용자 가까운 곳에 미리 복사해두는 서버망**이다.","aliases":["cdn","content delivery network"],"related":[{"term":"DNS","note":"— 어느 거점으로 보낼지 고르는 데 쓰인다"},{"term":"Cache","note":"— CDN이 하는 일의 본질. 위치만 사용자 쪽으로 옮긴 것"},{"term":"TTL","note":"— 거점이 복사본을 얼마나 오래 들고 있을지 정하는 값"},{"term":"Load Balancer","note":"— 같은 곳에서 서버를 나누는 것. CDN은 지역을 나눈다"}]},{"id":"net--cidr","term":"CIDR","reading":"Classless Inter-Domain Routing","category":"네트워크","summary":"CIDR 는 IP 주소 묶음을 **앞 몇 비트가 같은지**로 자르는 방식이다.","aliases":["cidr","classless inter-domain routing"],"related":[{"term":"IP Address","note":"— CIDR 가 묶어서 다루는 바로 그 값"},{"term":"Subnet","note":"— 큰 CIDR 묶음을 더 작은 CIDR 로 쪼갠 것"},{"term":"VPC","note":"— 만들 때 CIDR 을 먼저 정해야 하는 클라우드 네트워크"},{"term":"Public IP vs Private IP","note":"— 사설 대역도 `10.0.0.0/8` 처럼 CIDR 로 적는다"},{"term":"방화벽 규칙","note":"— 허용 대상을 주소 하나가 아니라 CIDR 묶음으로 적는 자리"}]},{"id":"net--dhcp","term":"DHCP","reading":"Dynamic Host Configuration Protocol","category":"네트워크","summary":"DHCP 는 네트워크에 들어온 기기에 IP 주소를 **빌려주는** 규약이다.","aliases":["dhcp","dynamic host configuration protocol"],"related":[{"term":"IP Address","note":"— DHCP 가 기한을 걸어 빌려주는 바로 그 값"},{"term":"Subnet","note":"— 어느 대역에서 주소를 꺼내 줄지 정하는 범위"},{"term":"DNS","note":"— 주소와 함께 내려주는 이름 해석 서버"},{"term":"Gateway","note":"— 함께 내려주는 \"밖으로 나가는 문\" 의 주소"}]},{"id":"net--dns","term":"DNS","reading":"Domain Name System","category":"네트워크","summary":"DNS는 **도메인 이름을 IP 주소로 바꿔주는 시스템**이다.","aliases":["dns","domain name system"],"related":[{"term":"TCP","note":"— DNS 조회가 끝난 뒤 실제 연결을 맺는 계층"},{"term":"HTTP","note":"— 받은 IP 로 주고받는 내용"},{"term":"CDN","note":"— DNS 응답을 지역별로 다르게 주는 대표적 활용"},{"term":"Load Balancer","note":"— 하나의 이름 뒤에 여러 서버를 두는 다른 방법"}]},{"id":"net--domain","term":"Domain","reading":"도메인","category":"네트워크","summary":"Domain은 **숫자 IP 주소에 붙인 사람이 읽는 이름**이다.","aliases":["domain","도메인"],"related":[{"term":"DNS","note":"— 도메인을 IP 주소로 바꿔주는 시스템"},{"term":"IP Address","note":"— 도메인이 실제로 가리키는 숫자 주소"},{"term":"URL","note":"— 프로토콜과 경로까지 붙인 전체 주소. 도메인은 그중 한 부분이다"},{"term":"TTL","note":"— 바꾼 DNS 레코드가 언제부터 모두에게 보일지 정하는 값"},{"term":"SSL_TLS","note":"— 그 도메인이 진짜임을 증명하는 인증서가 붙는 자리"}]},{"id":"net--firewall","term":"Firewall","reading":"방화벽","category":"네트워크","summary":"Firewall은 **정해둔 규칙에 따라 통신을 통과시키거나 막는 장치**다.","aliases":["firewall","방화벽"],"related":[{"term":"방화벽 규칙","note":"— 무엇을 허용하고 무엇을 막을지 적어둔 목록"},{"term":"인바운드 아웃바운드","note":"— 들어오는 통신과 나가는 통신의 구분"},{"term":"Port","note":"— 방화벽이 열고 닫는 단위"},{"term":"Reverse Proxy","note":"— 서버 앞에서 요청을 받아 넘기는 쪽. 방화벽과 함께 쓴다"},{"term":"VPN","note":"— 방화벽 안쪽으로 들어오는 암호화된 통로"}]},{"id":"net--gateway","term":"Gateway","reading":"게이트웨이","category":"네트워크","summary":"Gateway는 **서로 다른 네트워크가 만나는 지점에 서는 중개자**다.","aliases":["gateway","게이트웨이"],"related":[{"term":"API Gateway","note":"— 서비스 앞에 두는 게이트웨이. 지금 가장 흔한 형태"},{"term":"Reverse Proxy","note":"— 뒤의 서버를 가리고 대신 받는 자리. 게이트웨이와 겹친다"},{"term":"Load Balancer","note":"— 같은 서비스의 여러 대로 요청을 나누는 쪽"},{"term":"Rate Limiting","note":"— 게이트웨이가 거는 대표적인 제한"},{"term":"NAT","note":"— 나가는 경계에서 주소를 바꾸는 일. 네트워크 게이트웨이가 맡는다"}]},{"id":"net--http","term":"HTTP","reading":"HyperText Transfer Protocol","category":"네트워크","summary":"HTTP는 **웹에서 요청과 응답을 주고받는 규칙**이다.","aliases":["http","hypertext transfer protocol"],"related":[{"term":"HTTPS","note":"— HTTP를 TLS로 감싸 내용을 가린 것"},{"term":"TCP","note":"— HTTP 요청이 실제로 타고 가는 연결"},{"term":"DNS","note":"— 요청을 어디로 보낼지 IP를 먼저 찾아주는 단계"},{"term":"REST","note":"— HTTP 메서드를 규칙으로 삼아 API를 설계하는 방식"}]},{"id":"net--http-2","term":"HTTP/2","reading":"","category":"네트워크","summary":"HTTP/2 는 **한 연결에 여러 요청을 겹쳐 보내는 HTTP**다.","aliases":["http/2","http 2"],"related":[{"term":"HTTP","note":"— HTTP/2 가 모양만 바꿔 실어 보내는 그 규칙"},{"term":"HTTP/3","note":"— HTTP/2 가 못 푼 TCP 층 줄서기를 QUIC 로 푼 다음 판"},{"term":"TCP","note":"— HTTP/2 가 올라타는 바탕. 여기서 오는 한계가 그대로 남는다"},{"term":"Packet","note":"— 하나 잃으면 그 연결의 스트림이 다 멈춘다고 할 때의 그 조각"}]},{"id":"net--http-3","term":"HTTP/3","reading":"","category":"네트워크","summary":"HTTP/3 은 **TCP 를 버리고 QUIC 위로 옮긴 HTTP**다.","aliases":["http/3","http 3"],"related":[{"term":"HTTP/2","note":"— 설계를 물려주고 못 푼 문제까지 넘긴 앞 판"},{"term":"UDP","note":"— QUIC 이 올라탄 바탕. 순서도 재전송도 없는 쪽"},{"term":"TCP","note":"— HTTP/3 이 비운 자리. 여기서 오던 줄서기가 문제였다"},{"term":"QUIC","note":"— HTTP/3 이 올라탄 전송 프로토콜. TLS 1.3 을 품고 스트림을 따로 나른다"},{"term":"Packet","note":"— 하나 잃었을 때 무엇까지 멈추느냐가 이 단어의 요점"}]},{"id":"net--https","term":"HTTPS","reading":"HTTP Secure","category":"네트워크","summary":"HTTPS는 **HTTP를 TLS로 감싸서 내용을 가린 것**이다.","aliases":["https","http secure"],"related":[{"term":"HTTP","note":"— HTTPS가 감싸고 있는 원래 프로토콜"},{"term":"SSL_TLS","note":"— 실제로 암호화를 담당하는 계층"},{"term":"인증서","note":"— 이 서버가 그 도메인의 주인임을 증명하는 문서"},{"term":"CA","note":"— 인증서를 발급하고 보증하는 기관"}]},{"id":"net--icmp","term":"ICMP","reading":"Internet Control Message Protocol","category":"네트워크","summary":"ICMP는 **데이터를 나르지 않고 문제가 생겼다고 알리는 프로토콜**이다.","aliases":["icmp","internet control message protocol"],"related":[{"term":"IP Address","note":"— ICMP 신고가 얹혀 가고, 되돌아갈 곳을 정하는 주소 체계"},{"term":"TCP","note":"— 실패를 알리는 데서 끝나는 ICMP 와 달리 재전송까지 직접 하는 규약"},{"term":"TTL","note":"— 같은 이름이지만 IP 에서는 시간이 아니라 지날 수 있는 라우터 수를 센다"},{"term":"Firewall","note":"— ICMP 를 막아 ping 이 실패하게 만드는 가장 흔한 원인"},{"term":"Latency","note":"— ping 이 찍어주는 왕복 시간이 재고 있는 값"}]},{"id":"net--ip-address","term":"IP Address","reading":"IP 주소","category":"네트워크","summary":"IP 주소는 **네트워크에서 어디로 보낼지 가리키는 번호**다.","aliases":["ip address","ip 주소"],"related":[{"term":"DNS","note":"— 사람이 외운 이름을 이 번호로 바꿔주는 쪽"},{"term":"NAT","note":"— 사설 주소를 공인 주소로 바꿔 내보내는 일"},{"term":"Public IP vs Private IP","note":"— 바깥에서 쓰는 주소와 안에서만 쓰는 주소의 구분"},{"term":"Subnet","note":"— 주소의 어디까지가 망을 가리키는지 정하는 것"},{"term":"Port","note":"— 같은 주소 안에서 어느 프로그램으로 갈지 가리는 번호"}]},{"id":"net--intranet","term":"Intranet","reading":"인트라넷","category":"네트워크","summary":"Intranet은 **조직 안에서만 닿는 사설 네트워크**다.","aliases":["intranet","인트라넷"],"related":[{"term":"VPN","note":"— 밖에서 인트라넷 안으로 들어오는 통로"},{"term":"Firewall","note":"— 안과 밖의 경계에서 오가는 것을 거르는 장치"},{"term":"DMZ","note":"— 밖에도 열어야 하는 서버를 두는 완충 구역"},{"term":"Public IP vs Private IP","note":"— 인트라넷이 어느 쪽 주소를 쓰는지 가르는 구분"}]},{"id":"net--load-balancer","term":"Load Balancer","reading":"부하 분산기","category":"네트워크","summary":"Load Balancer는 **들어오는 요청을 여러 서버에 나눠 보내는 장치**다.","aliases":["load balancer","부하 분산기"],"related":[{"term":"Reverse Proxy","note":"— 앞에 서서 요청을 대신 받는다는 점이 같다. 분산이 목적이면 분산기다"},{"term":"DNS","note":"— 이름 하나 뒤에 여러 IP를 두는 다른 방법"},{"term":"Auto Scaling","note":"— 새로 띄운 서버를 분산 대상에 넣어주는 쪽"},{"term":"Session","note":"— 서버를 여러 대로 늘리면 어디에 둘지 다시 정해야 하는 것"}]},{"id":"net--localhost","term":"Localhost","reading":"로컬호스트","category":"네트워크","summary":"Localhost는 **자기 컴퓨터 자신을 가리키는 이름**이다.","aliases":["localhost","로컬호스트"],"related":[{"term":"IP Address","note":"— localhost가 가리키는 127.0.0.1이 그중 하나다"},{"term":"Port","note":"— 같은 localhost 안에서 서비스를 구별하는 번호"},{"term":"DNS","note":"— 이름을 주소로 바꾸는 일반적인 방법. localhost는 hosts 파일이 대신한다"},{"term":"Port Forwarding","note":"— 밖에서 안쪽 포트로 들여보내는 방법"},{"term":"Public IP vs Private IP","note":"— 밖에서 닿는 주소와 안에서만 쓰는 주소의 구분"}]},{"id":"net--long-polling","term":"Long Polling","reading":"롱 폴링","category":"네트워크","summary":"Long Polling 은 **서버가 답할 것이 생길 때까지 요청을 붙잡아 두는** 방식이다.","aliases":["long polling","롱 폴링"],"related":[{"term":"HTTP","note":"— 요청이 없으면 답할 수 없다는 규칙. 롱 폴링이 비켜 가려는 대상이다"},{"term":"SSE","note":"— 응답을 끝내지 않고 계속 내려보내는 쪽. 롱 폴링의 다음 세대다"},{"term":"WebSocket","note":"— 갈아타서 양쪽이 오가게 만든 쪽. 역시 다음 세대다"},{"term":"TCP","note":"— 요청을 붙잡아 둔다는 것이 실제로 붙잡고 있는 연결"},{"term":"Reverse Proxy","note":"— 붙잡아 둔 요청 때문에 앞단 연결이 굶는 자리"}]},{"id":"net--mac-address","term":"MAC Address","reading":"MAC 주소","category":"네트워크","summary":"MAC 주소는 **네트워크 카드마다 하나씩 붙는 48비트 번호**다.","aliases":["mac address","mac 주소"],"related":[{"term":"ARP","note":"— IP 만 알 때 이 번호를 알아내는 규칙"},{"term":"IP Address","note":"— 자리에 붙는 번호. 이 번호와 짝을 이룬다"},{"term":"Router vs Switch","note":"— 이 번호로 넘기는 장비와 IP 로 길을 고르는 장비"},{"term":"OSI 7계층","note":"— 이 번호가 쓰이는 2계층의 자리"}]},{"id":"net--mcp","term":"MCP","reading":"Model Context Protocol","category":"네트워크","summary":"MCP는 **AI 가 바깥 도구를 부르는 방법을 통일한 규약**이다.","aliases":["mcp","model context protocol"],"related":[{"term":"JSON","note":"— MCP 메시지가 담기는 형식"},{"term":"SSE","note":"— 원격 서버에 붙을 때 쓰는 전송 방식"},{"term":"AI Agent","note":"— 도구를 골라 부르는 쪽. MCP 는 그 부르는 방법을 통일한 것"},{"term":"API Gateway","note":"— 여러 뒷단을 창구 하나로 모은다는 점이 닮았다"}]},{"id":"net--multi-tenancy","term":"Multi-tenancy","reading":"멀티 테넌시","category":"네트워크","summary":"Multi-tenancy는 **한 시스템을 여러 고객이 나눠 쓰는 구조**다.","aliases":["multi-tenancy","멀티 테넌시"],"related":[{"term":"Tenant","note":"— 이 구조에서 갈라지는 단위 하나"},{"term":"IaaS_PaaS_SaaS","note":"— 멀티 테넌시가 주로 쓰이는 서비스 형태"},{"term":"DB","note":"— 데이터를 어느 층에서 가를지 정하는 자리"},{"term":"Rate Limiting","note":"— 한 고객이 자원을 독차지하지 못하게 막는 장치"},{"term":"Sharding","note":"— 데이터를 나눠 담는다는 점은 같지만 목적은 성능이다"}]},{"id":"net--nat","term":"NAT","reading":"Network Address Translation","category":"네트워크","summary":"NAT는 **사설 IP를 공인 IP로 바꿔주는 기술**이다.","aliases":["nat","network address translation"],"related":[{"term":"IP Address","note":"— NAT가 바꾸는 대상. 공인과 사설로 나뉜다"},{"term":"Public IP vs Private IP","note":"— NAT가 그 사이를 오가게 만드는 두 종류"},{"term":"Port Forwarding","note":"— 밖에서 안으로 들어올 길을 미리 뚫어두는 DNAT"},{"term":"Firewall","note":"— NAT가 곁다리로 하던 가림을 규칙으로 하는 장치"}]},{"id":"net--nginx","term":"Nginx","reading":"엔진엑스","category":"네트워크","summary":"Nginx 는 **요청을 먼저 받아 파일을 주거나 뒤 서버로 넘기는 프로그램**이다.","aliases":["nginx","엔진엑스"],"related":[{"term":"Reverse Proxy","note":"— Nginx 가 앞에서 맡는 역할의 이름"},{"term":"Load Balancer","note":"— 뒤에 붙은 서버들에 요청을 나누는 기능"},{"term":"HTTPS","note":"— 인증서를 여기서 처리하고 뒤로는 평문으로 넘긴다"},{"term":"Rate Limiting","note":"— 앞단에서 호출 횟수를 제한하는 설정"},{"term":"Cache","note":"— 뒤에서 받은 응답을 앞에 잠시 두는 기능"}]},{"id":"net--osi-7","term":"OSI 7계층","reading":"OSI 7-Layer Model","category":"네트워크","summary":"OSI 7계층은 **네트워크 통신을 일곱 단계로 나눈 참조 모델**이다.","aliases":["osi 7계층","osi 7-layer model"],"related":[{"term":"TCP","note":"— 4계층에서 빠짐없는 전달을 맡는 쪽"},{"term":"UDP","note":"— 같은 4계층에서 확인 없이 보내는 쪽"},{"term":"IP Address","note":"— 3계층이 길을 정할 때 보는 주소"},{"term":"HTTP","note":"— 7계층에서 오가는 대표적인 규약"},{"term":"SSL_TLS","note":"— 6계층에 해당하는 암호화가 붙는 자리"}]},{"id":"net--packet","term":"Packet","reading":"패킷","category":"네트워크","summary":"패킷은 **보낼 데이터를 잘라 주소를 붙인 한 조각**이다.","aliases":["packet","패킷"],"related":[{"term":"IP Address","note":"— 조각의 머리표에 적히는 보낸 곳·받을 곳 주소"},{"term":"TCP","note":"— 뒤바뀌고 사라지는 조각을 순서대로 세워 주는 위층"},{"term":"UDP","note":"— 그 보정을 포기하고 조각을 그대로 넘기는 위층"},{"term":"OSI 7계층","note":"— 이 조각이 층마다 어떤 이름으로 불리는지 정리한 지도"},{"term":"TTL","note":"— 조각이 살아 있을 시간을 미리 정해두는 것도 같은 발상이다"}]},{"id":"net--port","term":"Port","reading":"포트","category":"네트워크","summary":"Port는 **한 컴퓨터 안에서 어느 프로그램으로 갈지 가리키는 번호**다.","aliases":["port","포트"],"related":[{"term":"IP Address","note":"— 어느 컴퓨터인지까지 데려다주는 주소"},{"term":"Socket","note":"— IP 와 포트를 묶어 프로그램이 잡는 통신 창구"},{"term":"TCP","note":"— 포트 번호를 실어 나르는 대표적인 규약"},{"term":"Firewall","note":"— 어느 포트를 열고 막을지 정하는 자리"},{"term":"Port Forwarding","note":"— 바깥 포트를 안쪽 다른 포트로 돌려주는 설정"}]},{"id":"net--port-forwarding","term":"Port Forwarding","reading":"포트 포워딩","category":"네트워크","summary":"Port Forwarding은 **바깥 포트로 온 요청을 안쪽 기기로 넘기는 규칙**이다.","aliases":["port forwarding","포트 포워딩"],"related":[{"term":"NAT","note":"— 사설 주소와 공인 주소를 바꿔주는 기술. 포워딩이 올라타는 바탕이다"},{"term":"Public IP vs Private IP","note":"— 밖에서 닿는 주소와 안에서만 쓰는 주소의 구분"},{"term":"Port","note":"— 포워딩이 갈라 쓰는 번호"},{"term":"Reverse Proxy","note":"— 같은 일을 서버 쪽에서 경로와 도메인 단위로 하는 방법"},{"term":"방화벽 규칙","note":"— 포워딩과 별개로 허용 규칙을 따로 넣어야 하는 자리"}]},{"id":"net--proxy","term":"Proxy","reading":"Forward Proxy","category":"네트워크","summary":"Proxy는 **클라이언트를 대신해 밖으로 요청을 보내는 서버**다.","aliases":["proxy","forward proxy"],"related":[{"term":"Reverse Proxy","note":"— 같은 중개인데 서버 앞에 서서 서버를 가린다"},{"term":"VPN","note":"— 연결 자체를 암호화한다는 점이 프록시와 다르다"},{"term":"Cache","note":"— 프록시가 응답을 저장해뒀다 다시 쓰는 방식"},{"term":"Firewall","note":"— 규칙으로 막는 쪽. 프록시는 대신 나가주는 쪽이다"},{"term":"Gateway","note":"— 네트워크 진입점. 프록시가 그 자리에 놓이기도 한다"}]},{"id":"net--public-ip-vs-private-ip","term":"Public IP vs Private IP","reading":"공인 IP vs 사설 IP","category":"네트워크","summary":"공인 IP는 **인터넷 전체에서 유일한 주소**이고 사설 IP는 그 안쪽에서만 통하는 주소다.","aliases":["public ip vs private ip","공인 ip vs 사설 ip","public ip","private ip","공인 ip","사설 ip"],"related":[{"term":"NAT","note":"— 사설 IP와 공인 IP 사이를 바꿔주는 장치"},{"term":"IP Address","note":"— 공인과 사설로 나뉘기 전의 주소 개념"},{"term":"Port Forwarding","note":"— 밖에서 내부 사설 IP로 들어오는 통로를 여는 방법"},{"term":"VPN","note":"— 내부망에 들어와 사설 IP를 그대로 쓰게 해주는 다른 방법"},{"term":"Subnet","note":"— 사설 대역을 다시 잘게 나눠 쓰는 단위"}]},{"id":"net--quic","term":"QUIC","reading":"","category":"네트워크","summary":"QUIC 는 UDP 위에서 **신뢰성과 암호화를 직접 챙기는** 전송 규약이다.","aliases":["quic"],"related":[{"term":"UDP","note":"— QUIC 이 밑바탕 통로로 쓰는 전송"},{"term":"TCP","note":"— QUIC 이 그 자리를 대신하려는 기존 전송"},{"term":"SSL_TLS","note":"— QUIC 이 자기 악수 안으로 끌어들인 암호 규약"},{"term":"HTTP","note":"— QUIC 위에서 도는 HTTP/3 의 앞 세대"}]},{"id":"net--reverse-proxy","term":"Reverse Proxy","reading":"리버스 프록시","category":"네트워크","summary":"Reverse Proxy는 **서버 앞에 서서 요청을 대신 받는 중개 서버**다.","aliases":["reverse proxy","리버스 프록시"],"related":[{"term":"Proxy","note":"— 클라이언트 앞에 서는 반대쪽. 감추는 대상이 다르다"},{"term":"Load Balancer","note":"— 요청을 나눠 주는 일만 따로 맡는 장치"},{"term":"Nginx","note":"— 리버스 프록시로 가장 많이 쓰이는 소프트웨어"},{"term":"SSL_TLS","note":"— 앞단에서 끊어내는 그 암호화"},{"term":"CDN","note":"— 같은 원리를 지역마다 흩어 놓은 것"}]},{"id":"net--router-vs-switch","term":"Router vs Switch","reading":"라우터와 스위치","category":"네트워크","summary":"스위치는 MAC 으로 같은 망 안에 넘기고, 라우터는 **IP 로 망을 건너보낸다**.","aliases":["router vs switch","라우터와 스위치","router","switch"],"related":[{"term":"MAC Address","note":"— 스위치가 보고 넘기는 주소"},{"term":"IP Address","note":"— 라우터가 보고 길을 고르는 주소"},{"term":"ARP","note":"— 라우터로 내보낼 때 그 라우터의 MAC 을 알아내는 규칙"},{"term":"Gateway","note":"— 망의 경계에 서는 자리를 넓게 부르는 말. 공유기의 라우터 노릇이 여기다"},{"term":"Subnet","note":"— 어디까지가 한 망인지 정하는 값"}]},{"id":"net--sse","term":"SSE","reading":"Server-Sent Events","category":"네트워크","summary":"SSE는 **서버가 클라이언트로 계속 밀어 보내는 단방향 연결**이다.","aliases":["sse","server-sent events"],"related":[{"term":"WebSocket","note":"— 양쪽이 주고받아야 할 때 쓰는 쪽"},{"term":"HTTP","note":"— SSE가 그대로 올라타는 바탕 프로토콜"},{"term":"Webhook","note":"— 서버끼리 밀어 보내는 방식. 브라우저 쪽이 아니다"},{"term":"Socket","note":"— 연결을 잡아둔다는 것이 실제로 무엇을 잡는지 설명하는 개념"}]},{"id":"net--socket","term":"Socket","reading":"소켓","category":"네트워크","summary":"Socket은 **프로그램이 네트워크에 데이터를 넣고 빼는 창구**다.","aliases":["socket","소켓"],"related":[{"term":"TCP","note":"— 소켓을 만들 때 고를 수 있는 규칙 하나"},{"term":"UDP","note":"— 연결을 안 맺는 쪽. 같은 자리에서 고른다"},{"term":"Port","note":"— 한 컴퓨터 안에서 어느 프로그램인지 가리키는 번호"},{"term":"IP Address","note":"— 어느 컴퓨터인지 가리키는 주소"},{"term":"WebSocket","note":"— 웹에서 양쪽이 계속 주고받게 만든 것"}]},{"id":"net--tcp","term":"TCP","reading":"Transmission Control Protocol","category":"네트워크","summary":"TCP는 **데이터를 빠짐없이 순서대로 배달하는 규칙**이다.","aliases":["tcp","transmission control protocol"],"related":[{"term":"UDP","note":"— 확인 없이 그냥 보내는 쪽. 빠른 대신 안 챙긴다"},{"term":"HTTP","note":"— TCP 위에서 오가는 대표적인 응용"},{"term":"IP Address","note":"— TCP가 연결을 맺을 상대를 가리키는 주소"},{"term":"Socket","note":"— 프로그램이 TCP 연결을 잡는 창구"}]},{"id":"net--tunnel","term":"Tunnel","reading":"터널링","category":"네트워크","summary":"Tunnel은 **다른 통신을 통째로 감싸서 실어 나르는 통로**다.","aliases":["tunnel","터널링"],"related":[{"term":"SSH","note":"— 터널을 만드는 데 가장 흔히 쓰는 통로"},{"term":"Port Forwarding","note":"— 어느 포트를 어디로 이을지 정하는 부분"},{"term":"VPN","note":"— 터널 위에 사설망 전체를 얹은 것"},{"term":"Firewall","note":"— 터널이 지나가야 하는 관문"}]},{"id":"net--udp","term":"UDP","reading":"User Datagram Protocol","category":"네트워크","summary":"UDP는 **확인하지 않고 그냥 보내는 전송 규칙**이다.","aliases":["udp","user datagram protocol"],"related":[{"term":"TCP","note":"— 빠짐과 순서를 챙기는 쪽. 그 대가로 기다림이 생긴다"},{"term":"DNS","note":"— UDP로 묻고 답하는 대표적인 프로토콜"},{"term":"Port","note":"— UDP가 어느 프로그램에 넘길지 가리는 번호"},{"term":"IP Address","note":"— UDP 조각이 실려 가는 아래층의 주소"},{"term":"OSI 7계층","note":"— UDP가 서 있는 자리는 전송 계층이다"}]},{"id":"net--url","term":"URL","reading":"Uniform Resource Locator","category":"네트워크","summary":"URL은 **인터넷에서 무엇을 어디서 어떻게 가져올지 적은 주소**다.","aliases":["url","uniform resource locator"],"related":[{"term":"DNS","note":"— URL 의 호스트 이름을 IP 주소로 바꾼다"},{"term":"Domain","note":"— URL 에서 어느 서버인지 가리키는 부분"},{"term":"Port","note":"— URL 에 적히거나 프로토콜에 따라 기본값이 붙는 번호"},{"term":"HTTP","note":"— URL 로 요청하고 응답받을 때 쓰는 규약"},{"term":"REST","note":"— URL 의 경로를 자원 이름으로 쓰는 설계 방식"}]},{"id":"net--vpn","term":"VPN","reading":"Virtual Private Network","category":"네트워크","summary":"VPN은 **공용 인터넷 위에 암호화된 전용 통로를 내는 기술**이다.","aliases":["vpn","virtual private network"],"related":[{"term":"Tunnel","note":"— VPN이 통신을 감싸 보낼 때 쓰는 방식"},{"term":"암호화","note":"— 터널 안을 못 읽게 만드는 부분"},{"term":"Proxy","note":"— 중개는 하지만 암호화를 보장하지 않는 쪽"},{"term":"IPSec VPN","note":"— VPN을 세우는 대표적인 규약 묶음"}]},{"id":"net--websocket","term":"WebSocket","reading":"웹소켓","category":"네트워크","summary":"WebSocket은 **한 번 연결하면 양쪽이 계속 주고받는 통로**다.","aliases":["websocket","웹소켓"],"related":[{"term":"HTTP","note":"— 연결을 시작할 때 쓰는 것. 도중에 갈아탄다"},{"term":"SSE","note":"— 서버에서 내려보내기만 하는 더 간단한 쪽"},{"term":"TCP","note":"— WebSocket 프레임이 실려 가는 아래층"},{"term":"Socket","note":"— 이름은 닮았지만 이쪽은 운영체제가 주는 통신 창구"},{"term":"Reverse Proxy","note":"— 앞단이 갈아타기를 통과시켜 줘야 연결이 열린다"}]},{"id":"net--curl","term":"curl","reading":"Client URL","category":"네트워크","summary":"curl은 **터미널에서 URL 로 요청을 보내고 응답을 받는 명령어**다.","aliases":["curl","client url"],"related":[{"term":"HTTP","note":"— curl 이 만들어 보내는 요청의 규칙"},{"term":"Terminal","note":"— curl 을 치는 자리"},{"term":"CLI","note":"— 글자로 명령을 주는 방식. curl 이 그 예다"},{"term":"Token 인증","note":"— `-H \"Authorization: Bearer ...\"` 로 붙이는 것"},{"term":"SSL_TLS","note":"— `-k` 가 검사를 꺼버리는 대상"}]},{"id":"net--mtls","term":"mTLS","reading":"Mutual TLS","category":"네트워크","summary":"mTLS 는 **양쪽이 서로 인증서를 내보이는 TLS**다.","aliases":["mtls","mutual tls"],"related":[{"term":"SSL_TLS","note":"— 서버 쪽만 증명하는 기본형. mTLS 는 그 선택 항목을 켠 것이다"},{"term":"인증서","note":"— 양쪽이 서로 내보이는 그 문서"},{"term":"CA","note":"— 그 인증서에 서명해 신뢰 사슬의 뿌리가 되는 기관"},{"term":"Zero Trust","note":"— 망 안이라고 믿지 않는다는 원칙. mTLS 가 그것을 실행하는 수단"}]}]},{"id":"web","name":"웹 개발","blurb":"브라우저와 서버 사이에서 벌어지는 일","terms":[{"id":"web--api-versioning","term":"API Versioning","reading":"API 버저닝","category":"웹 개발","summary":"API Versioning 은 **API 를 고치면서 옛 클라이언트를 살려 두는 장치**다.","aliases":["api versioning","api 버저닝"],"related":[{"term":"API","note":"— 버전을 나누는 대상. 남이 기대고 있는 그 규격이다"},{"term":"REST","note":"— 주소와 메서드로 규격을 정하는 방식. 주소에 버전을 싣는 관행이 여기서 나온다"},{"term":"HTTP","note":"— 버전을 헤더나 `Accept` 로 실어 보내는 통로"},{"term":"API Gateway","note":"— 들어온 요청의 버전을 보고 뒤쪽 서버로 갈라 보내는 자리"},{"term":"Package Manager","note":"— 라이브러리 버전을 범위로 적어 고르는, 같은 호환 문제의 패키지 쪽 답"}]},{"id":"web--accessibility","term":"Accessibility","reading":"웹 접근성","category":"웹 개발","summary":"Accessibility 는 **능력이 어떻든 쓸 수 있게** 만드는 웹 설계다.","aliases":["accessibility","웹 접근성"],"related":[{"term":"HTML","note":"— 알맞은 요소를 제 용도로 쓰는 것이 접근성의 첫 단계다"},{"term":"CSS","note":"— 명암비와 글자 크기 같은 조문이 실제로 걸리는 자리"},{"term":"Responsive Design","note":"— 작은 화면이라는 상황적 제약을 함께 다룬다"},{"term":"DOM","note":"— 보조기술이 읽어 가는 문서 구조 그 자체"}]},{"id":"web--backend","term":"Backend","reading":"백엔드","category":"웹 개발","summary":"Backend는 **화면 뒤 서버에서 데이터와 규칙을 다루는 쪽**이다.","aliases":["backend","백엔드"],"related":[{"term":"Frontend","note":"— 사용자가 직접 보는 쪽. 백엔드에 요청을 보낸다"},{"term":"API","note":"— 프론트엔드와 백엔드가 주고받는 창구"},{"term":"REST","note":"— 그 창구를 설계하는 흔한 규칙"},{"term":"DB","note":"— 백엔드가 데이터를 실제로 넣고 꺼내는 곳"},{"term":"Session","note":"— 백엔드가 요청한 사람이 누구인지 기억하는 방법"}]},{"id":"web--browser-rendering","term":"Browser Rendering","reading":"브라우저 렌더링","category":"웹 개발","summary":"브라우저 렌더링은 **글자로 온 문서를 화면 픽셀로 바꾸는 과정**이다.","aliases":["browser rendering","브라우저 렌더링"],"related":[{"term":"DOM","note":"— 파싱이 만들어 내는 트리. 이 과정의 첫 산물이다"},{"term":"HTML","note":"— 렌더링에 들어가는 원고"},{"term":"CSS","note":"— 렌더 트리의 나머지 절반. 다 받기 전에는 화면이 안 나온다"},{"term":"JavaScript","note":"— 단계 사이에 끼어들어 트리를 고치고 다시 그리게 만드는 쪽"},{"term":"Latency","note":"— 첫 화면이 뜨기까지 걸리는 시간을 재는 말"}]},{"id":"web--cors","term":"CORS","reading":"Cross-Origin Resource Sharing","category":"웹 개발","summary":"CORS는 **다른 출처의 응답을 읽어도 되는지 정하는 규칙**이다.","aliases":["cors","cross-origin resource sharing"],"related":[{"term":"HTTP","note":"— CORS 는 전부 HTTP 헤더로만 이뤄진다"},{"term":"Cookie","note":"— 함께 보낼 때 설정이 하나씩 더 필요해지는 대상"},{"term":"API","note":"— 다른 도메인의 API 를 부를 때 늘 마주치는 문제"},{"term":"Proxy","note":"— 같은 출처로 보이게 만들어 이 문제를 피하는 방법"}]},{"id":"web--csr","term":"CSR","reading":"Client Side Rendering","category":"웹 개발","summary":"CSR은 **브라우저가 자바스크립트로 화면을 그리는 방식**이다.","aliases":["csr","client side rendering"],"related":[{"term":"SSR","note":"— 반대로 서버가 화면을 다 그려서 보내는 방식"},{"term":"SPA","note":"— CSR로 화면 전체를 한 벌만 띄우고 부분만 갈아 끼우는 구조"},{"term":"Component","note":"— 브라우저가 조립하는 화면 조각의 단위"},{"term":"Frontend","note":"— CSR에서 일이 몰리는 쪽"}]},{"id":"web--css","term":"CSS","reading":"Cascading Style Sheets","category":"웹 개발","summary":"CSS는 **겹쳐 쌓인 규칙**으로 문서의 생김새를 정하는 스타일 언어다.","aliases":["css","cascading style sheets"],"related":[{"term":"HTML","note":"— CSS 가 생김새를 얹는 대상, 곧 뜻과 구조를 표시한 문서"},{"term":"DOM","note":"— 규칙이 실제로 적용되는 트리. 마디마다 이긴 값이 매겨진다"},{"term":"Component","note":"— 규칙이 겹치는 범위를 조각 안으로 좁히는 요즘 방식"},{"term":"Frontend","note":"— CSS 를 쓰는 일이 놓인 자리"}]},{"id":"web--code-splitting","term":"Code Splitting","reading":"코드 분할","category":"웹 개발","summary":"Code Splitting은 **자바스크립트를 나눠 두고 필요할 때 받게 하는 일**이다.","aliases":["code splitting","코드 분할"],"related":[{"term":"Build","note":"— 코드를 덩어리로 나누는 일이 실제로 일어나는 시점"},{"term":"CSR","note":"— 첫 화면까지 자바스크립트를 기다리는 쪽. 분할 효과가 가장 크다"},{"term":"SPA","note":"— 화면 전부를 한 벌로 받는 구조. 경로별로 쪼개는 대상이 된다"},{"term":"Component","note":"— 덩어리 경계로 흔히 쓰는 단위"}]},{"id":"web--core-web-vitals","term":"Core Web Vitals","reading":"코어 웹 바이탈","category":"웹 개발","summary":"Core Web Vitals 는 **웹 경험을 셋으로 나눠 재는 성능 지표**다.","aliases":["core web vitals","코어 웹 바이탈"],"related":[{"term":"Latency","note":"— LCP 와 INP 가 재는 기다림 자체를 가리키는 상위 개념"},{"term":"CDN","note":"— 파일을 사용자 가까이 둬서 LCP 를 줄이는 대표적 수단"},{"term":"HTTP Caching","note":"— 두 번째 방문에서 다시 받지 않게 해 로딩 지표를 낮추는 규약"},{"term":"DOM","note":"— CLS 가 재는 배치 밀림이 실제로 일어나는 대상"}]},{"id":"web--dom","term":"DOM","reading":"Document Object Model","category":"웹 개발","summary":"DOM은 문서를 프로그램이 고칠 수 있게 만든 **객체 트리**다.","aliases":["dom","document object model"],"related":[{"term":"HTML","note":"— 이 트리를 세우는 재료가 되는 원문"},{"term":"CSS","note":"— 트리의 마디마다 생김새를 매기는 규칙"},{"term":"Object","note":"— 트리의 마디 하나하나가 바로 이것"},{"term":"SPA","note":"— 페이지를 새로 받지 않고 이 트리만 고쳐 화면을 바꾸는 방식"}]},{"id":"web--frontend","term":"Frontend","reading":"프론트엔드","category":"웹 개발","summary":"Frontend 는 **사용자 기기에서 실행되는 화면 쪽 코드**다.","aliases":["frontend","프론트엔드"],"related":[{"term":"Backend","note":"— 데이터와 규칙을 맡는 반대쪽"},{"term":"API","note":"— 두 쪽이 데이터를 주고받는 창구"},{"term":"SPA","note":"— 페이지를 다시 받지 않고 화면만 바꾸는 방식"},{"term":"CDN","note":"— 화면 파일을 사용자 가까운 곳에 두는 층"}]},{"id":"web--full-stack","term":"Full Stack","reading":"풀스택","category":"웹 개발","summary":"Full Stack은 **화면부터 서버까지 전부 다루는 것**이다.","aliases":["full stack","풀스택"],"related":[{"term":"Frontend","note":"— 사용자가 직접 보는 층"},{"term":"Backend","note":"— 요청을 받아 처리하는 층"},{"term":"DB","note":"— 값을 담아두는 곳. 스택의 맨 아래"},{"term":"API","note":"— 화면과 서버가 주고받는 약속"},{"term":"DevOps","note":"— 만든 것을 띄우고 유지하는 일"}]},{"id":"web--graphql","term":"GraphQL","reading":"","category":"웹 개발","summary":"GraphQL은 **필요한 필드를 골라서 요청하는 API 방식**이다.","aliases":["graphql"],"related":[{"term":"REST","note":"— 주소마다 응답이 정해진 방식. GraphQL 과 대비된다"},{"term":"API","note":"— GraphQL 이 속한 큰 갈래"},{"term":"HTTP","note":"— GraphQL 요청도 대개 이 위로 오간다"},{"term":"gRPC","note":"— 성능을 앞세운 또 다른 통신 방식"},{"term":"API Gateway","note":"— 여러 API 앞에 두는 진입점. GraphQL 을 그 자리에 놓기도 한다"}]},{"id":"web--html","term":"HTML","reading":"HyperText Markup Language","category":"웹 개발","summary":"HTML은 웹 내용의 **뜻과 구조**를 표시하는 마크업 언어다.","aliases":["html","hypertext markup language"],"related":[{"term":"CSS","note":"— HTML 이 표시해 둔 것 위에 생김새를 얹는 언어"},{"term":"DOM","note":"— 브라우저가 HTML 원문을 읽어 세우는 객체 트리"},{"term":"Frontend","note":"— HTML·CSS·JavaScript 로 화면 쪽을 만드는 일 전체"},{"term":"URL","note":"— 하이퍼텍스트 링크가 가리키는 주소"}]},{"id":"web--http-caching","term":"HTTP Caching","reading":"HTTP 캐싱","category":"웹 개발","summary":"HTTP Caching 은 **응답을 얼마나 들고 있어도 되는지 헤더로 정하는 규약**이다.","aliases":["http caching","http 캐싱"],"related":[{"term":"Caching","note":"— 이 규약이 HTTP 위에서 조문으로 만든 개념 쪽"},{"term":"TTL","note":"— `max-age` 가 HTTP 에서 맡는 바로 그 역할"},{"term":"CDN","note":"— 이 헤더를 읽고 사본을 들고 있는 대표적인 공용 캐시"},{"term":"HTTP","note":"— 이 규칙들이 헤더로 실려 가는 규약"},{"term":"HTTP Status Code","note":"— 재확인이 `304` 로 끝난다는 것을 정하는 표"}]},{"id":"web--http-status-code","term":"HTTP Status Code","reading":"HTTP 상태 코드","category":"웹 개발","summary":"HTTP 상태 코드는 **서버가 요청 결과를 알리는 세 자리 숫자**다.","aliases":["http status code","http 상태 코드"],"related":[{"term":"HTTP","note":"— 이 숫자가 실려 오는 프로토콜"},{"term":"REST","note":"— 메서드와 이 숫자를 규칙대로 쓰는 API 설계 방식"},{"term":"Rate Limiting","note":"— 429 로 알리는 그 제한"},{"term":"Reverse Proxy","note":"— 502 처럼 게이트웨이 계열 오류가 나는 자리"}]},{"id":"web--hydration","term":"Hydration","reading":"하이드레이션","category":"웹 개발","summary":"Hydration은 **서버가 보낸 HTML에 동작을 붙여 살리는 일**이다.","aliases":["hydration","하이드레이션"],"related":[{"term":"SSR","note":"— 하이드레이션이 살려낼 HTML을 요청마다 만들어 보내는 쪽"},{"term":"SSG","note":"— 빌드 때 미리 만들어 둔 HTML도 같은 방식으로 살린다"},{"term":"CSR","note":"— 붙일 HTML 없이 브라우저가 처음부터 그리는 쪽"},{"term":"DOM","note":"— 하이드레이션이 손대는 대상. 이미 만들어진 요소에 동작을 건다"},{"term":"Component","note":"— 동작을 붙일 단위. 서버와 브라우저가 같은 것을 그려야 맞춰진다"}]},{"id":"web--idempotency-key","term":"Idempotency Key","reading":"멱등 키","category":"웹 개발","summary":"Idempotency Key 는 **같은 요청을 한 번만 처리하게 만드는 열쇠**다.","aliases":["idempotency key","멱등 키"],"related":[{"term":"HTTP","note":"— 어떤 메서드가 멱등인지 정해 둔 규칙. `POST` 가 빠진 이유가 여기 있다"},{"term":"HTTP Status Code","note":"— 열쇠가 겹쳤을 때 돌려주는 `409`·`422` 가 있는 표"},{"term":"Message Queue","note":"— 같은 메시지가 두 번 오는 자리. 처리한 id 를 적어 두고 걸러낸다"},{"term":"Transaction","note":"— 처리와 기록이 함께 되거나 함께 안 되게 묶어 주는 아래층 장치"}]},{"id":"web--javascript","term":"JavaScript","reading":"자바스크립트","category":"웹 개발","summary":"JavaScript는 **브라우저에서 페이지의 동작을 맡는 프로그래밍 언어**다.","aliases":["javascript","자바스크립트"],"related":[{"term":"HTML","note":"— 같은 페이지에서 뜻과 뼈대를 맡는 층"},{"term":"CSS","note":"— 같은 페이지에서 생김새를 맡는 층"},{"term":"DOM","note":"— 스크립트가 화면을 만질 때 붙잡는 손잡이"},{"term":"Compile vs Interpret","note":"— 이 언어를 인터프리터 쪽으로 부르는 까닭이 여기 있다"},{"term":"Service Worker","note":"— 브라우저가 준 실행 자리 가운데 화면 밖에서 도는 것"}]},{"id":"web--local-storage-session-storage","term":"Local Storage & Session Storage","reading":"브라우저 저장소","category":"웹 개발","summary":"Local Storage 와 Session Storage 는 **브라우저에 값을 남기는 두 저장소**다.","aliases":["local storage & session storage","브라우저 저장소","local storage","session storage"],"related":[{"term":"Cookie","note":"— 같은 브라우저 저장이지만 요청마다 서버로 딸려 가는 쪽"},{"term":"Session","note":"— 이름만 겹치는 서버 쪽 상태. sessionStorage 와 다른 것"},{"term":"Same-Origin Policy","note":"— 이 통을 출처마다 따로 갈라 두는 규칙"},{"term":"XSS","note":"— 이 통의 값을 스크립트로 읽어가는 공격"}]},{"id":"web--middleware","term":"Middleware","reading":"미들웨어","category":"웹 개발","summary":"Middleware는 **요청이 처리기에 닿기 전에 거쳐 가는 중간 함수**다.","aliases":["middleware","미들웨어"],"related":[{"term":"CORS","note":"— 미들웨어로 처리하는 대표적인 규칙"},{"term":"API Gateway","note":"— 같은 일을 서비스 바깥 경계에서 하는 자리"},{"term":"JWT","note":"— 인증 미들웨어가 확인하는 토큰의 한 형태"},{"term":"Logging","note":"— 미들웨어가 남기는 요청 기록"}]},{"id":"web--openapi","term":"OpenAPI","reading":"오픈API","category":"웹 개발","summary":"OpenAPI 는 **HTTP API 의 사용법을 기계도 읽게 적는** 표준 형식이다.","aliases":["openapi","오픈api"],"related":[{"term":"API","note":"— OpenAPI 가 적어 두는 대상 그 자체"},{"term":"REST","note":"— HTTP 메서드로 API 를 설계하는 방식. OpenAPI 가 주로 적는 모양이다"},{"term":"JSON","note":"— 명세 파일의 본래 형태. 문서 자체가 하나의 JSON 객체다"},{"term":"YAML","note":"— 같은 명세를 사람이 쓰기 좋게 적는 표기"},{"term":"SDK","note":"— 명세 파일에서 뽑아내는 결과물 중 하나"}]},{"id":"web--pwa","term":"PWA","reading":"Progressive Web App","category":"웹 개발","summary":"PWA는 **웹 기술로 만들어 기기에 설치되는 앱**이다.","aliases":["pwa","progressive web app"],"related":[{"term":"Service Worker","note":"— 오프라인을 맡는 다리. PWA 의 절반이 이것이다"},{"term":"HTTPS","note":"— 설치의 전제 조건. 개발용 주소 말고는 예외가 없다"},{"term":"Cache","note":"— 워커가 오프라인에 쓸 응답을 담아두는 곳"},{"term":"SPA","note":"— PWA 가 흔히 올라타는 화면 구성 방식. 서로 다른 층의 말이다"},{"term":"JavaScript","note":"— 서비스 워커를 비롯해 PWA 의 동작을 이 언어로 쓴다"}]},{"id":"web--pagination","term":"Pagination","reading":"페이지네이션","category":"웹 개발","summary":"Pagination 은 **목록을 여러 쪽으로 잘라 주는 방식**이다.","aliases":["pagination","페이지네이션"],"related":[{"term":"REST","note":"— 쪽 나누기를 쿼리 문자열과 응답 헤더로 주고받는 방식"},{"term":"GraphQL","note":"— 커서와 쪽 정보를 규격으로 못 박아 둔 쪽"},{"term":"Index","note":"— cursor 방식이 깊은 쪽에서도 빠른 이유. 정렬 기준에 걸려 있어야 한다"},{"term":"Rate Limiting","note":"— 한 번에 가져갈 양을 묶어 서버를 지키는 같은 목적의 다른 장치"}]},{"id":"web--rest","term":"REST","reading":"Representational State Transfer","category":"웹 개발","summary":"REST는 **HTTP 를 자원 중심으로 쓰기로 한 약속**이다.","aliases":["rest","representational state transfer"],"related":[{"term":"HTTP","note":"— REST 가 그대로 빌려 쓰는 바탕"},{"term":"HTTP Status Code","note":"— 결과를 알리는 데 쓰는 숫자"},{"term":"JSON","note":"— 본문을 싣는 데 가장 많이 쓰이는 형식"},{"term":"GraphQL","note":"— 주소 하나로 필요한 것만 골라 받는 다른 방식"}]},{"id":"web--responsive-design","term":"Responsive Design","reading":"반응형 디자인","category":"웹 개발","summary":"Responsive Design 은 **화면 크기에 따라 배치가 스스로 바뀌는** 웹 설계 방식이다.","aliases":["responsive design","반응형 디자인"],"related":[{"term":"CSS","note":"— 미디어 쿼리와 유연한 단위가 사는 곳"},{"term":"HTML","note":"— `viewport` 메타 태그를 놓는 자리"},{"term":"Accessibility","note":"— 작은 화면이라는 상황적 제약을 함께 다룬다"},{"term":"Frontend","note":"— 화면이 어느 폭에서도 서게 만드는 책임이 여기에 있다"}]},{"id":"web--soap","term":"SOAP","reading":"Simple Object Access Protocol","category":"웹 개발","summary":"SOAP은 **XML 봉투로 감싸 메시지를 주고받는 규격**이다.","aliases":["soap","simple object access protocol"],"related":[{"term":"REST","note":"— 같은 자리를 HTTP 로 푼 다음 세대. SOAP 을 밀어낸 방식"},{"term":"XML","note":"— 봉투와 본문을 적는 형식. SOAP 이 직렬화 형태로 못 박은 것"},{"term":"HTTP","note":"— 봉투를 실어 나르는 여러 전송 중 가장 흔한 하나"},{"term":"API","note":"— SOAP 봉투가 창구 역할을 맡던 자리"},{"term":"gRPC","note":"— 봉투 대신 이진 형식과 규격화된 계약으로 같은 문제를 푸는 요즘 방식"}]},{"id":"web--spa","term":"SPA","reading":"Single Page Application","category":"웹 개발","summary":"SPA는 **HTML 한 장으로 시작해 화면만 갈아 끼우는 웹 앱**이다.","aliases":["spa","single page application"],"related":[{"term":"CSR","note":"— SPA가 화면을 브라우저에서 그리는 방식"},{"term":"SSR","note":"— 서버가 미리 그려 보내는 쪽. 첫 화면과 검색 문제를 푸는 대안"},{"term":"Frontend","note":"— SPA가 놓이는 자리"},{"term":"REST","note":"— SPA가 데이터를 받아올 때 흔히 쓰는 API 형식"}]},{"id":"web--ssg","term":"SSG","reading":"Static Site Generation","category":"웹 개발","summary":"SSG는 **요청이 오기 전에 HTML을 미리 만들어 두는 방식**이다.","aliases":["ssg","static site generation"],"related":[{"term":"SSR","note":"— 같은 HTML을 요청이 올 때 만드는 쪽"},{"term":"CSR","note":"— 화면을 브라우저가 그리는 쪽. SSG로 만든 첫 화면과 섞어 쓴다"},{"term":"Hydration","note":"— 미리 만든 HTML에 동작을 붙이는 다음 단계"},{"term":"CDN","note":"— 미리 만든 파일을 여러 지역에 복사해 두는 곳"},{"term":"Build","note":"— SSG가 HTML을 만드는 시점"}]},{"id":"web--ssr","term":"SSR","reading":"Server Side Rendering","category":"웹 개발","summary":"SSR은 **서버가 완성된 HTML을 만들어 보내는 방식**이다.","aliases":["ssr","server side rendering"],"related":[{"term":"CSR","note":"— 같은 화면을 브라우저가 조립하는 반대쪽 방식"},{"term":"SPA","note":"— 페이지 이동을 브라우저 안에서 처리하는 구조. 주로 CSR과 함께 쓴다"},{"term":"Cache","note":"— 같은 HTML을 다시 조립하지 않으려고 함께 쓴다"},{"term":"Backend","note":"— HTML 조립이 일어나는 자리"}]},{"id":"web--same-origin-policy","term":"Same-Origin Policy","reading":"동일 출처 정책","category":"웹 개발","summary":"Same-Origin Policy는 **다른 출처의 응답을 못 읽게 막는 브라우저 규칙**이다.","aliases":["same-origin policy","동일 출처 정책"],"related":[{"term":"CORS","note":"— 이 정책이 막은 자리에 서버가 문을 내는 방법"},{"term":"URL","note":"— 출처를 이루는 스킴·호스트·포트가 적혀 있는 곳"},{"term":"HTTPS","note":"— 스킴이 달라지면 출처도 달라지므로 http 판과 남남이 된다"},{"term":"CSRF","note":"— 이 정책이 쓰기 요청을 안 막기 때문에 남는 공격"},{"term":"XSS","note":"— 담 안으로 코드를 밀어 넣어 이 정책을 없는 것으로 만드는 공격"}]},{"id":"web--service-worker","term":"Service Worker","reading":"서비스 워커","category":"웹 개발","summary":"Service Worker는 **웹앱과 네트워크 사이에서 요청을 가로채는 프록시**다.","aliases":["service worker","서비스 워커"],"related":[{"term":"Proxy","note":"— 서비스 워커가 브라우저 안에서 맡는 역할과 같은 것"},{"term":"Cache","note":"— 오프라인에 쓸 응답을 워커가 담아두는 곳"},{"term":"HTTPS","note":"— 서비스 워커를 등록하려면 먼저 갖춰야 하는 조건"},{"term":"Same-Origin Policy","note":"— 워커 파일을 같은 출처에만 둘 수 있게 하는 규칙"},{"term":"Thread","note":"— 워커가 화면과 따로 도는 실행 자리"}]},{"id":"web--webhook","term":"Webhook","reading":"웹훅","category":"웹 개발","summary":"Webhook은 **일이 생겼을 때 서버가 먼저 알려주는 방식**이다.","aliases":["webhook","웹훅"],"related":[{"term":"WebSocket","note":"— 연결을 열어둔 채 양쪽이 주고받는 방식"},{"term":"SSE","note":"— 서버가 한쪽으로만 계속 흘려보내는 방식"},{"term":"Event-Driven Architecture","note":"— 웹훅이 놓여 있는 큰 그림"},{"term":"CI_CD","note":"— 저장소 웹훅으로 시작되는 대표적인 흐름"}]},{"id":"web--grpc","term":"gRPC","reading":"","category":"웹 개발","summary":"gRPC는 **먼 서버의 함수를 내 함수처럼 부르게 해주는 방식**이다.","aliases":["grpc"],"related":[{"term":"REST","note":"— 바깥에 여는 API에서 여전히 기본이 되는 방식"},{"term":"HTTP","note":"— gRPC가 올라타는 HTTP/2의 앞 버전"},{"term":"GraphQL","note":"— 같은 자리를 놓고 겨루는 또 다른 방식"},{"term":"Monolith vs Microservices","note":"— gRPC가 주로 쓰이는 구조"}]}]},{"id":"db","name":"데이터베이스","blurb":"데이터를 어디에 어떻게 두나","terms":[{"id":"db--acid","term":"ACID","reading":"","category":"데이터베이스","summary":"ACID는 **트랜잭션이 보장하는 네 가지 성질**이다.","aliases":["acid"],"related":[{"term":"Transaction","note":"— 이 네 가지를 지켜주는 묶음 그 자체"},{"term":"Isolation Level","note":"— 네 글자 중 I 를 몇 단계로 지킬지 고르는 자리"},{"term":"CAP Theorem","note":"— 한 대를 넘어 여러 대로 흩어지면 이 보장이 어디까지 가능한가"},{"term":"NoSQL","note":"— 보장을 일부 내주고 확장을 택한 쪽"},{"term":"DB","note":"— 이 보장을 파는 쪽"}]},{"id":"db--b-tree","term":"B-Tree","reading":"B 트리","category":"데이터베이스","summary":"B-Tree 는 **정렬된 값을 여러 갈래로 갈라 담은 균형 트리**다.","aliases":["b-tree","b 트리"],"related":[{"term":"Index","note":"— B-Tree 가 인덱스의 기본 모양이다"},{"term":"Query Plan","note":"— 이 인덱스를 탈지 훑을지 고르는 자리"},{"term":"자료구조","note":"— 이 트리가 속한 갈래"},{"term":"Big O 표기법","note":"— 층 수로 정해지는 탐색 비용을 적는 방식"},{"term":"DB","note":"— 쪽 단위로 읽고 쓰는 저장 구조"}]},{"id":"db--cap-theorem","term":"CAP Theorem","reading":"CAP 정리","category":"데이터베이스","summary":"CAP Theorem은 **네트워크가 갈라지면 일관성과 가용성 중 하나를 내주게 된다는 정리**다.","aliases":["cap theorem","cap 정리"],"related":[{"term":"ACID","note":"— 한 대에서 지키는 보장. CAP 의 C 는 이 C 와 다른 말이다"},{"term":"NoSQL","note":"— 여러 대로 흩어지면서 가용성 쪽을 자주 택하는 계열"},{"term":"Sharding","note":"— 데이터를 여러 대에 나눠 두는 방식. 노드가 여럿이라야 분할이 문제가 된다"},{"term":"Availability Zone","note":"— 분할이 실제로 일어나는 물리적 경계"}]},{"id":"db--connection-pool","term":"Connection Pool","reading":"커넥션 풀","category":"데이터베이스","summary":"커넥션 풀은 **연결을 열어 두고 돌려쓰는 통**이다.","aliases":["connection pool","커넥션 풀"],"related":[{"term":"DB","note":"— 풀이 붙들고 있는 상대"},{"term":"Socket","note":"— 풀에 담기는 연결의 실체"},{"term":"ORM","note":"— 대개 자기 안에 이 풀을 끼고 도는 계층"},{"term":"Latency","note":"— 연결을 새로 맺지 않아 줄어드는 시간"}]},{"id":"db--db","term":"DB","reading":"Database, 데이터베이스","category":"데이터베이스","summary":"DB는 **데이터를 구조에 맞춰 맡아두고 지키는 시스템**이다.","aliases":["db","database, 데이터베이스"],"related":[{"term":"SQL","note":"— 관계형 DB에 무엇을 원하는지 적어 보내는 언어"},{"term":"ORM","note":"— DB의 행을 프로그램의 객체로 바꿔주는 계층"},{"term":"Index","note":"— 찾는 속도를 위해 따로 만들어두는 정렬 목록"},{"term":"Transaction","note":"— 여러 작업을 전부 되거나 전부 안 되게 묶는 단위"},{"term":"NoSQL","note":"— 표 모양을 미리 정하지 않는 쪽의 DB"}]},{"id":"db--data-lake","term":"Data Lake","reading":"데이터 레이크","category":"데이터베이스","summary":"데이터 레이크는 **정리하지 않은 원본을 그대로 쌓아 두는 저장소**다.","aliases":["data lake","데이터 레이크"],"related":[{"term":"Data Warehouse","note":"— 담을 때 먼저 정리하는 반대쪽 선택"},{"term":"ETL","note":"— 담기 전에 변환하는 방식. 레이크는 이 순서를 뒤집는다"},{"term":"S3","note":"— 레이크의 저장 층으로 흔히 쓰이는 클라우드 저장소"},{"term":"JSON","note":"— 레이크가 원본 그대로 받는 반구조화 형식의 예"},{"term":"구조화 데이터","note":"— 웨어하우스가 요구하고 레이크는 요구하지 않는 형태"}]},{"id":"db--data-warehouse","term":"Data Warehouse","reading":"데이터 웨어하우스","category":"데이터베이스","summary":"데이터 웨어하우스는 **여러 시스템의 데이터를 분석용으로 모아 정리해 둔 저장소**다.","aliases":["data warehouse","데이터 웨어하우스"],"related":[{"term":"ETL","note":"— 소스에서 웨어하우스로 옮기며 형식을 맞추는 과정"},{"term":"Data Lake","note":"— 정리를 미루고 원본부터 쌓는 반대쪽 선택"},{"term":"Snowflake","note":"— 이 개념을 클라우드 제품으로 만든 예"},{"term":"DB","note":"— 웨어하우스와 갈라지는 운영용 쪽의 큰 갈래"},{"term":"SQL","note":"— 웨어하우스에 묻는 언어"}]},{"id":"db--denormalization","term":"Denormalization","reading":"역정규화","category":"데이터베이스","summary":"Denormalization 은 **읽기를 위해 중복을 일부러 되살리는** 설계다.","aliases":["denormalization","역정규화"],"related":[{"term":"Normalization","note":"— 역정규화가 되돌리는 대상. 이걸 먼저 하고 나서 고른다"},{"term":"NoSQL","note":"— 접근 패턴에 맞춰 표 수를 줄이는 쪽이라 역정규화가 기본에 가깝다"},{"term":"Eventual Consistency","note":"— 베껴 둔 값이 원본을 잠시 못 따라가는 상태를 다루는 짝"},{"term":"Index","note":"— 표를 안 건드리고 읽기를 빠르게 하는 다른 방법"},{"term":"Cache","note":"— 읽기를 사려고 중복을 허용한다는 점에서 같은 종류의 거래"}]},{"id":"db--etl","term":"ETL","reading":"Extract Transform Load","category":"데이터베이스","summary":"ETL 은 **뽑고 바꾸고 담는 순서로 데이터를 옮기는 일**이다.","aliases":["etl","extract transform load"],"related":[{"term":"Data Warehouse","note":"— ETL 이 데이터를 담는 대표적인 목적지"},{"term":"Data Lake","note":"— 원본을 먼저 담는 곳. ELT 로 순서가 바뀔 때의 앞자리"},{"term":"Pipeline","note":"— ETL 이 그 위에서 도는 틀"},{"term":"SQL","note":"— ELT 에서 변환을 적는 언어"},{"term":"구조화 데이터","note":"— 바꾸기 단계가 맞춰 내는 모양"}]},{"id":"db--eventual-consistency","term":"Eventual Consistency","reading":"최종 일관성","category":"데이터베이스","summary":"Eventual Consistency 는 **쓴 직후 읽으면 옛 값이 올 수 있는** 규칙이다.","aliases":["eventual consistency","최종 일관성"],"related":[{"term":"Transaction","note":"— 한 곳에서 즉시 일관성을 지키는 반대편 장치"},{"term":"NoSQL","note":"— 최종 일관성을 기본 읽기 모델로 두는 저장소 계열"},{"term":"Denormalization","note":"— 베껴 둔 값이 원본을 잠시 못 따라가는 대표적인 자리"},{"term":"Cache","note":"— 원본보다 낡은 값을 잠깐 보여준다는 점에서 같은 종류의 타협"},{"term":"Latency","note":"— 최신 보장을 늦추는 대가로 줄이는 값"}]},{"id":"db--isolation-level","term":"Isolation Level","reading":"격리 수준","category":"데이터베이스","summary":"Isolation Level은 **동시에 도는 트랜잭션을 서로에게서 얼마나 가릴지 정하는 단계**다.","aliases":["isolation level","격리 수준"],"related":[{"term":"Transaction","note":"— 격리 수준은 이 묶음 하나하나에 걸리는 설정이다"},{"term":"ACID","note":"— 네 글자 중 I 를 몇 단계로 지킬지 고르는 자리"},{"term":"Concurrency","note":"— 이 수준이 다루려는 문제의 배경"},{"term":"DB","note":"— 기본 단계를 제품이 정해서 내놓는 쪽"}]},{"id":"db--join","term":"JOIN","reading":"조인","category":"데이터베이스","summary":"JOIN 은 **조건에 맞는 행끼리 짝지어** 여러 표를 한 결과로 내는 일이다.","aliases":["join","조인"],"related":[{"term":"Primary Key & Foreign Key","note":"— 조인이 따라가는 짝의 근거가 되는 값"},{"term":"Index","note":"— 조인 조건 컬럼에 없으면 상대 표를 통째로 훑게 된다"},{"term":"SQL","note":"— 조인을 적는 언어"},{"term":"DB","note":"— 표를 나눠 담아 조인이 필요해지는 곳"},{"term":"NoSQL","note":"— 나누지 않고 한 문서에 묶어 담아 조인을 피하는 다른 선택"}]},{"id":"db--key-value-store","term":"Key-Value Store","reading":"키-값 저장소","category":"데이터베이스","summary":"Key-Value Store는 **열쇠 하나로 값 하나를 꺼내는 저장소**다.","aliases":["key-value store","키-값 저장소"],"related":[{"term":"NoSQL","note":"— 표 구조를 내려놓은 갈래. 그 안의 한 종류다"},{"term":"Redis","note":"— 열쇠-값 저장소를 메모리에 두고 쓰는 대표 제품"},{"term":"Hash","note":"— 열쇠를 자리로 바꿔 한 번에 닿게 하는 방법"},{"term":"Query","note":"— 열쇠 대신 조건으로 묻는 쪽. 이 저장소가 내려놓은 것"},{"term":"Index","note":"— 값으로 찾아야 할 때 따로 세워야 하는 장치"}]},{"id":"db--migration","term":"Migration","reading":"스키마 마이그레이션","category":"데이터베이스","summary":"마이그레이션은 **스키마 변경을 코드로 적어 이력으로 쌓는** 일이다.","aliases":["migration","스키마 마이그레이션"],"related":[{"term":"DB","note":"— 마이그레이션이 실제로 고치는 대상"},{"term":"SQL","note":"— 마이그레이션 파일이 걸릴 때 번역되어 나가는 말"},{"term":"ORM","note":"— 모델과 스키마의 차이를 떠서 마이그레이션 파일을 뽑아 주는 계층"},{"term":"Git","note":"— 마이그레이션 파일이 다른 소스와 함께 쌓이는 곳"},{"term":"CI_CD","note":"— 배포할 때 마이그레이션을 언제 걸지 정하는 자리"}]},{"id":"db--n-1-problem","term":"N+1 Problem","reading":"N+1 문제","category":"데이터베이스","summary":"N+1 문제는 **목록 하나를 얻고 항목마다 또 묻는** 낭비다.","aliases":["n+1 problem","n+1 문제"],"related":[{"term":"ORM","note":"— 이 문제가 대개 생기는 자리. 질의를 감춰 주면서 질의 수도 함께 감춘다"},{"term":"GraphQL","note":"— 중첩 필드를 파고들 때 같은 꼴로 걸리는 다른 무대"},{"term":"Index","note":"— 질의 한 개를 빠르게 하는 장치. 질의 수는 줄이지 못한다"},{"term":"Latency","note":"— 왕복이 늘어날 때 실제로 커지는 값"},{"term":"Caching","note":"— 같은 질의가 되풀이될 때 왕복 자체를 없애는 다른 길"}]},{"id":"db--nosql","term":"NoSQL","reading":"","category":"데이터베이스","summary":"NoSQL은 **표 모양을 고집하지 않는 데이터베이스**다.","aliases":["nosql"],"related":[{"term":"SQL","note":"— 관계형 DB에 묻는 언어. NoSQL이 내려놓은 쪽"},{"term":"DB","note":"— NoSQL이 속한 큰 갈래"},{"term":"Redis","note":"— Key-Value 저장소의 대표"},{"term":"Vector DB","note":"— 값이 아니라 의미의 가까움으로 찾는 또 다른 갈래"},{"term":"Sharding","note":"— 여러 서버에 나눠 담아 늘리는 방법"}]},{"id":"db--normalization","term":"Normalization","reading":"정규화","category":"데이터베이스","summary":"Normalization 은 **같은 사실을 한 곳에만 두도록** 표를 쪼개는 일이다.","aliases":["normalization","정규화"],"related":[{"term":"Denormalization","note":"— 정규화한 뒤 읽기 성능을 위해 일부러 되돌리는 선택"},{"term":"DB","note":"— 정규화가 손보는 표와 관계가 사는 곳"},{"term":"SQL","note":"— 쪼갠 표를 조인으로 다시 붙여 읽는 언어"},{"term":"Transaction","note":"— 여러 표를 한꺼번에 고칠 때 중간 상태가 안 보이게 묶는 단위"},{"term":"Index","note":"— 쪼갠 표를 열쇠로 빨리 찾게 해 주는 장치"}]},{"id":"db--oltp-vs-olap","term":"OLTP vs OLAP","reading":"","category":"데이터베이스","summary":"OLTP 와 OLAP 는 **한 건을 다루는 쪽과 모아 보는 쪽**이다.","aliases":["oltp vs olap","oltp","olap"],"related":[{"term":"DB","note":"— 두 방식이 갈라지기 전의 같은 바탕"},{"term":"Transaction","note":"— OLTP 쪽이 붙들고 OLAP 쪽은 쓰지 않는 장치"},{"term":"Snowflake","note":"— OLAP 쪽을 맡는 대표적인 클라우드 데이터 웨어하우스"},{"term":"Index","note":"— 한 건을 빨리 찾는 장치. 집계를 겨눈 열 저장과는 노리는 데가 다르다"},{"term":"구조화 데이터","note":"— 두 쪽이 모두 다루는, 미리 정해진 틀에 담긴 데이터"}]},{"id":"db--orm","term":"ORM","reading":"Object-Relational Mapping","category":"데이터베이스","summary":"ORM은 **DB 테이블을 프로그램의 객체처럼 다루게 해주는 계층**이다.","aliases":["orm","object-relational mapping"],"related":[{"term":"SQL","note":"— ORM이 대신 써주는 것. 결국 DB로 가는 건 이것이다"},{"term":"DB","note":"— ORM이 객체로 감싸는 대상"},{"term":"Transaction","note":"— ORM 이 함께 감싸주는 또 하나의 DB 개념"},{"term":"Index","note":"— ORM이 만든 쿼리가 느릴 때 먼저 보는 곳"}]},{"id":"db--oracle-exadata","term":"Oracle Exadata","reading":"엑사데이타","category":"데이터베이스","summary":"Oracle Exadata는 **오라클 DB 만 돌리려고 만든 전용 장비**다.","aliases":["oracle exadata","엑사데이타"],"related":[{"term":"DB","note":"— Exadata 가 돌리려고 만들어진 대상"},{"term":"SQL","note":"— 저장 쪽에서 미리 거는 조건이 여기서 나온다"},{"term":"Index","note":"— 훑는 양을 줄이는 다른 방법. 잘 걸리면 전용 장비가 덜 필요하다"},{"term":"Bare Metal","note":"— 가상화 없이 물리 장비를 그대로 쓰는 방식"}]},{"id":"db--partitioning","term":"Partitioning","reading":"파티셔닝","category":"데이터베이스","summary":"Partitioning은 **한 테이블을 여러 조각으로 쪼개 두고 하나처럼 쓰는 것**이다.","aliases":["partitioning","파티셔닝"],"related":[{"term":"Sharding","note":"— 서버를 넘어 나누는 쪽. 파티셔닝은 한 데이터베이스 안에서 나눈다"},{"term":"Index","note":"— 파티셔닝이 인덱스의 위층을 대신해 주는 관계"},{"term":"DB","note":"— 한 테이블의 파티션이 모두 함께 있어야 하는 단위"},{"term":"SQL","note":"— 파티션 경계와 조회 조건을 적는 언어"}]},{"id":"db--primary-key-foreign-key","term":"Primary Key & Foreign Key","reading":"기본키와 외래키","category":"데이터베이스","summary":"기본키는 행의 신분증이고, 외래키는 그 신분증을 **가리키는 손가락**이다.","aliases":["primary key & foreign key","기본키와 외래키","primary key","foreign key"],"related":[{"term":"DB","note":"— 이 두 키가 붙는 표들이 사는 곳"},{"term":"SQL","note":"— 키를 선언하고 어기는 값을 거절하게 만드는 언어"},{"term":"Index","note":"— 기본키를 만들면 자동으로 함께 생기는 것"},{"term":"JOIN","note":"— 외래키가 가리키는 방향을 따라 표를 다시 붙이는 일"},{"term":"Transaction","note":"— 부모와 자식을 함께 고치는 일을 한 덩어리로 묶는 단위"}]},{"id":"db--query","term":"Query","reading":"쿼리","category":"데이터베이스","summary":"Query는 **저장된 데이터에서 원하는 것을 꺼내오라는 명령**이다.","aliases":["query","쿼리"],"related":[{"term":"SQL","note":"— 쿼리를 적는 가장 널리 쓰이는 말. 쿼리와 같은 말은 아니다"},{"term":"URL","note":"— 물음표 뒤가 쿼리 스트링으로 불리는 자리"},{"term":"Key-Value Store","note":"— 쿼리 대신 열쇠 하나로 꺼내는 쪽"},{"term":"Index","note":"— 같은 쿼리를 훨씬 덜 읽고 답하게 하는 장치"},{"term":"DB","note":"— 쿼리를 받아 답하는 상대"}]},{"id":"db--query-plan","term":"Query Plan","reading":"쿼리 실행 계획","category":"데이터베이스","summary":"Query Plan 은 **DB 가 이 질문을 어떻게 풀지 미리 고른 순서**다.","aliases":["query plan","쿼리 실행 계획"],"related":[{"term":"Index","note":"— 계획이 쓸지 말지 고르는 후보"},{"term":"B-Tree","note":"— 그 인덱스가 실제로 취하는 모양"},{"term":"SQL","note":"— 무엇을 원하는지만 적고 어떻게는 안 적는 언어"},{"term":"DB","note":"— 계획을 세우고 그대로 실행하는 쪽"}]},{"id":"db--redis","term":"Redis","reading":"","category":"데이터베이스","summary":"Redis는 **데이터를 디스크가 아니라 메모리에 두는 저장소**다.","aliases":["redis"],"related":[{"term":"Cache","note":"— Redis 가 가장 많이 놓이는 자리"},{"term":"Session","note":"— 여러 서버가 같이 봐야 하는 대표적인 값"},{"term":"TTL","note":"— 열쇠가 얼마나 살아 있을지 정하는 값"},{"term":"DB","note":"— 원본이 있는 곳. Redis 는 그 앞에 선다"},{"term":"NoSQL","note":"— 표와 질의문 없이 값을 다루는 계열"}]},{"id":"db--replication","term":"Replication","reading":"복제","category":"데이터베이스","summary":"Replication은 **같은 데이터를 여러 서버에 복사해 두는 것**이다.","aliases":["replication","복제"],"related":[{"term":"Sharding","note":"— 데이터를 나눠 담는 쪽. 복제는 같은 것을 여러 벌 두는 반대 방향이다"},{"term":"DB","note":"— 복제가 여러 대로 늘리는 대상"},{"term":"Load Balancing","note":"— 읽기 요청을 복제본 여러 대에 나눠 보내는 장치"},{"term":"Transaction","note":"— 동기 복제가 커밋 순간에 붙들어 두는 단위"}]},{"id":"db--sql","term":"SQL","reading":"Structured Query Language","category":"데이터베이스","summary":"SQL은 **표에 담긴 데이터를 다루는 질의 언어**다.","aliases":["sql","structured query language"],"related":[{"term":"DB","note":"— SQL로 말을 거는 대상"},{"term":"Index","note":"— 데이터베이스가 찾는 방법을 정할 때 쓰는 장치"},{"term":"SQL Injection","note":"— 사용자 입력이 질의의 일부가 될 때 생기는 공격"},{"term":"Transaction","note":"— 여러 문장을 한 덩어리로 묶어 함께 되돌리는 단위"},{"term":"NoSQL","note":"— 표와 SQL을 쓰지 않는 쪽"}]},{"id":"db--snowflake","term":"Snowflake","reading":"","category":"데이터베이스","summary":"Snowflake는 **저장과 계산을 떼어놓은 클라우드 데이터 웨어하우스**다.","aliases":["snowflake"],"related":[{"term":"DB","note":"— Snowflake가 속한 큰 갈래"},{"term":"SQL","note":"— Snowflake에 묻는 언어"},{"term":"S3","note":"— 저장소 층이 실제로 쓰는 클라우드 저장소의 예"},{"term":"Cloud","note":"— 저장과 계산을 떼어놓는 것이 가능해진 배경"},{"term":"Auto Scaling","note":"— 웨어하우스를 자동으로 늘렸다 줄이는 것과 같은 발상"}]},{"id":"db--stored-procedure","term":"Stored Procedure","reading":"저장 프로시저","category":"데이터베이스","summary":"Stored Procedure는 **SQL 여러 줄을 DB 안에 이름 붙여 저장한 것**이다.","aliases":["stored procedure","저장 프로시저"],"related":[{"term":"SQL","note":"— 프로시저 안에 담기는 문장 그 자체"},{"term":"DB","note":"— 프로시저 정의가 저장되는 곳"},{"term":"Transaction","note":"— 프로시저가 실행 중에 커밋·롤백할 수 있는 단위"},{"term":"ORM","note":"— 같은 SQL 을 앱 쪽에 두는 반대 방향의 선택"}]},{"id":"db--transaction","term":"Transaction","reading":"트랜잭션","category":"데이터베이스","summary":"Transaction은 **다 되거나 아예 안 되게 묶는 작업 단위**다.","aliases":["transaction","트랜잭션"],"related":[{"term":"SQL","note":"— 트랜잭션을 여닫는 명령이 속한 언어"},{"term":"DB","note":"— 트랜잭션이 지켜주는 대상"},{"term":"Concurrency","note":"— 여러 트랜잭션이 겹칠 때 생기는 문제의 배경"},{"term":"NoSQL","note":"— 트랜잭션 보장을 일부 내주고 확장을 택한 쪽"}]},{"id":"db--view-materialized-view","term":"View & Materialized View","reading":"뷰와 구체화 뷰","category":"데이터베이스","summary":"뷰는 **저장된 질문**이고, 구체화 뷰는 그 질문의 저장된 답이다.","aliases":["view & materialized view","뷰와 구체화 뷰","view","materialized view"],"related":[{"term":"SQL","note":"— 뷰의 정체인 질의를 적는 언어"},{"term":"JOIN","note":"— 뷰로 감싸 이름을 붙이게 되는 복잡한 조회의 대부분"},{"term":"Cache","note":"— 답을 저장하고 낡음을 감당하는, 구체화 뷰와 같은 거래"},{"term":"Index","note":"— SQL Server 에서 뷰를 구체화시키는 수단이고, 안전한 갱신의 조건"},{"term":"DB","note":"— 뷰와 구체화 뷰가 얹히는 원본 표들이 있는 곳"}]},{"id":"db--wal","term":"WAL","reading":"Write-Ahead Log","category":"데이터베이스","summary":"WAL 은 **고칠 내용을 먼저 적어두는 기록 방식**이다.","aliases":["wal","write-ahead log"],"related":[{"term":"Transaction","note":"— 커밋과 롤백이 이 기록 위에서 확정된다"},{"term":"DB","note":"— WAL 이 장애에서 지켜주는 저장소"},{"term":"Index","note":"— 표와 함께 나중에 따라 고쳐지는 데이터 파일 쪽"},{"term":"Logging","note":"— 사람이 읽는 기록과 복구용 기록은 목적이 다르다"}]},{"id":"db--term-357e8f82","term":"구조화 데이터","reading":"Structured Data","category":"데이터베이스","summary":"구조화 데이터는 **모양을 미리 정해두고 담은 데이터**다.","aliases":["구조화 데이터","structured data"],"related":[{"term":"DB","note":"— 구조화 데이터를 담아두고 관리하는 곳"},{"term":"SQL","note":"— 구조화 데이터에 조건을 걸어 묻는 언어"},{"term":"JSON","note":"— 이름표는 있고 형식은 느슨한 반구조화의 대표"},{"term":"NoSQL","note":"— 표 모양을 강제하지 않는 쪽을 택한 저장소"},{"term":"Index","note":"— 열이 정해져 있어서 붙일 수 있는 검색 보조 장치"}]},{"id":"db--term-c10fd790","term":"인덱스","reading":"Database Index","category":"데이터베이스","summary":"인덱스는 **찾을 값을 미리 정렬해 따로 만들어둔 목록**이다.","aliases":["인덱스","database index","index"],"related":[{"term":"DB","note":"— 인덱스가 놓이는 자리"},{"term":"SQL","note":"— 인덱스를 만들고 쓰게 되는 질의 언어"},{"term":"Big O 표기법","note":"— 훑기와 인덱스 탐색의 차이를 재는 방식"},{"term":"자료구조","note":"— 인덱스가 쓰는 트리도 여기 속한다"},{"term":"Cache","note":"— 같은 결과를 다시 안 만드는 다른 방향의 해법"}]}]},{"id":"arch","name":"아키텍처 패턴","blurb":"규모가 커질 때 쓰는 구조","terms":[{"id":"arch--api","term":"API","reading":"Application Programming Interface","category":"아키텍처 패턴","summary":"API는 **다른 프로그램의 기능을 빌려 쓰는 창구**다.","aliases":["api","application programming interface"],"related":[{"term":"REST","note":"— 주소를 자원 이름으로 쓰는 대표적인 API 설계 방식"},{"term":"HTTP","note":"— 웹 API의 요청과 응답을 실어 나르는 규약"},{"term":"JSON","note":"— API가 주고받는 값을 담는 형식"},{"term":"GraphQL","note":"— 필요한 필드만 골라 받는 다른 방식의 API"},{"term":"API Gateway","note":"— 여러 API 앞에 서서 인증과 제한을 대신 맡는 자리"}]},{"id":"arch--api-gateway","term":"API Gateway","reading":"API 게이트웨이","category":"아키텍처 패턴","summary":"API Gateway는 **여러 서버로 가는 요청을 한 문에서 받는 서버**다.","aliases":["api gateway","api 게이트웨이"],"related":[{"term":"Load Balancer","note":"— 같은 서버 여럿에 나누는 쪽. 게이트웨이는 다른 서비스로 보낸다"},{"term":"Reverse Proxy","note":"— 앞에서 대신 받는다는 점이 같다. 게이트웨이는 거기에 정책이 붙은 것"},{"term":"Rate Limiting","note":"— 게이트웨이가 주로 맡는 대표적인 일"},{"term":"Monolith vs Microservices","note":"— 게이트웨이가 필요해지는 구조"}]},{"id":"arch--api-2","term":"API 외부 공개","reading":"로컬 API 를 남이 쓰게 하기","category":"아키텍처 패턴","summary":"API 외부 공개는 **내 컴퓨터에만 있던 API 를 인터넷에서 부를 수 있게 하는 일**이다.","aliases":["api 외부 공개","로컬 api 를 남이 쓰게 하기"],"related":[{"term":"HTTPS","note":"— 공개한 API 가 오가는 내용을 가리는 층"},{"term":"API Gateway","note":"— 공개 지점 앞에서 인증과 호출 제한을 맡는다"},{"term":"DNS","note":"— IP 대신 도메인으로 찾아오게 해주는 것"},{"term":"Rate Limiting","note":"— 공개한 뒤 한 사람이 얼마나 부를지 정하는 장치"},{"term":"Load Balancer","note":"— 뒤에 서버를 여러 대 두고 나눠 받을 때"}]},{"id":"arch--aws-bedrock","term":"AWS Bedrock","reading":"","category":"아키텍처 패턴","summary":"Bedrock은 **여러 회사의 AI 모델을 한 API로 부르는 AWS 서비스**다.","aliases":["aws bedrock","bedrock"],"related":[{"term":"LLM","note":"— Bedrock이 불러주는 모델들이 여기에 해당한다"},{"term":"AWS","note":"— Bedrock이 올라가 있는 플랫폼"},{"term":"API","note":"— 모델을 부르는 창구의 형태"},{"term":"VPC","note":"— 통신을 인터넷 밖으로 내보내지 않게 가두는 망"}]},{"id":"arch--auto-scaling","term":"Auto Scaling","reading":"오토 스케일링","category":"아키텍처 패턴","summary":"Auto Scaling은 **부하에 맞춰 서버 대수를 자동으로 조절하는 기능**이다.","aliases":["auto scaling","오토 스케일링"],"related":[{"term":"Load Balancing","note":"— 늘어난 서버에 요청을 나눠주는 짝. 없으면 늘려도 안 쓰인다"},{"term":"EC2","note":"— 늘리고 줄이는 대상이 되는 서버 그 자체"},{"term":"Kubernetes","note":"— 같은 일을 컨테이너 단위로 한다"},{"term":"Latency","note":"— CPU 말고 응답 시간을 기준으로 삼을 때 보는 값"}]},{"id":"arch--caching","term":"Caching","reading":"캐싱","category":"아키텍처 패턴","summary":"Caching은 **한 번 가져온 것을 가까이 두고 다시 쓰는 일**이다.","aliases":["caching","캐싱"],"related":[{"term":"Redis","note":"— 분산 캐시로 가장 많이 쓰이는 저장소"},{"term":"CDN","note":"— 같은 원리를 파일과 위치에 적용한 것"},{"term":"TTL","note":"— 캐시가 값을 얼마나 들고 있을지 정하는 값"},{"term":"Latency","note":"— 캐싱으로 줄이려는 대상이 바로 이 값이다"}]},{"id":"arch--circuit-breaker","term":"Circuit Breaker","reading":"서킷 브레이커","category":"아키텍처 패턴","summary":"Circuit Breaker는 **고장 난 서비스 호출을 잠시 끊어버리는 장치**다.","aliases":["circuit breaker","서킷 브레이커"],"related":[{"term":"Rate Limiting","note":"— 들어오는 쪽을 막는다. 차단기는 나가는 쪽을 막는다"},{"term":"Latency","note":"— 응답이 늦어지는 정도. 차단기가 실패로 셀지 정하는 기준"},{"term":"Monolith vs Microservices","note":"— 서비스를 나누면서 이 장치가 필요해졌다"},{"term":"Fallback","note":"— 차단기가 열렸을 때 대신 돌려줄 것"}]},{"id":"arch--consistent-hashing","term":"Consistent Hashing","reading":"일관된 해싱","category":"아키텍처 패턴","summary":"Consistent Hashing은 **서버가 바뀌어도 대부분의 키가 제자리에 남는 분배 방식**이다.","aliases":["consistent hashing","일관된 해싱"],"related":[{"term":"Sharding","note":"— 데이터를 여러 노드에 나눠 담는 일. 그 배치 규칙으로 쓰인다"},{"term":"Hash","note":"— 키와 서버를 원 위의 점으로 바꾸는 데 쓰는 계산"},{"term":"Cache","note":"— 서버를 늘릴 때 적중률을 지키려고 이 방식을 쓴다"},{"term":"Load Balancing","note":"— 요청을 나누는 일. 여기서는 데이터를 나눈다"},{"term":"Redis","note":"— 여러 대로 나눠 쓸 때 키 배치에 쓰이는 저장소"}]},{"id":"arch--langgraph","term":"LangGraph","reading":"","category":"아키텍처 패턴","summary":"LangGraph는 **LLM 앱의 흐름을 그래프로 적어 실행하는 도구**다.","aliases":["langgraph"],"related":[{"term":"AI Agent","note":"— 되돌아가는 흐름이 필요한 대표적인 사용처"},{"term":"RAG","note":"— 검색 노드와 생성 노드를 잇는 형태로 자주 짠다"},{"term":"LLM","note":"— 노드 안에서 실제로 답을 만드는 쪽"},{"term":"Pipeline","note":"— 단계를 이어 붙인다는 점은 같고, 되돌아가는 길이 있다는 점이 다르다"}]},{"id":"arch--latency","term":"Latency","reading":"지연 시간","category":"아키텍처 패턴","summary":"Latency는 **요청을 보내고 응답이 올 때까지 걸리는 시간**이다.","aliases":["latency","지연 시간"],"related":[{"term":"CDN","note":"— 거리 때문에 생기는 지연을 줄이는 쪽"},{"term":"Caching","note":"— 같은 조회를 반복하며 쌓이는 지연을 없애는 쪽"},{"term":"Index","note":"— 데이터베이스 조회에서 늘어지는 시간을 줄이는 수단"},{"term":"Load Balancer","note":"— 지연이 아니라 처리량 쪽을 늘리는 장치"}]},{"id":"arch--load-balancing","term":"Load Balancing","reading":"로드 밸런싱","category":"아키텍처 패턴","summary":"Load Balancing은 **들어오는 요청을 여러 서버에 나눠 보내는 일**이다.","aliases":["load balancing","로드 밸런싱"],"related":[{"term":"Load Balancer","note":"— 그 일을 실제로 맡는 장치"},{"term":"Auto Scaling","note":"— 부하에 따라 뒤쪽 서버 대수를 자동으로 조절한다"},{"term":"Reverse Proxy","note":"— 앞에 서서 요청을 받는다는 점이 같다"},{"term":"Nginx","note":"— 밸런서로 자주 쓰이는 소프트웨어"},{"term":"Circuit Breaker","note":"— 나가는 호출을 끊는 쪽. 밸런서는 들어오는 쪽을 나눈다"}]},{"id":"arch--message-queue","term":"Message Queue","reading":"메시지 큐","category":"아키텍처 패턴","summary":"Message Queue는 **할 일을 줄에 넣어두고 나중에 처리하게 하는 장치**다.","aliases":["message queue","메시지 큐"],"related":[{"term":"Pub-Sub","note":"— 한 메시지를 여러 곳이 받는 방식. 큐는 보통 한 곳이 받는다"},{"term":"Redis","note":"— 가벼운 큐로도 자주 쓰이는 저장소"},{"term":"Circuit Breaker","note":"— 큐가 완충한다면 차단기는 끊어낸다"},{"term":"Queue","note":"— 같은 개념을 프로그램 안의 자료구조로 쓴 것"}]},{"id":"arch--pipeline","term":"Pipeline","reading":"파이프라인","category":"아키텍처 패턴","summary":"Pipeline은 **작업을 단계로 나눠 차례로 흘려보내는 구조**다.","aliases":["pipeline","파이프라인"],"related":[{"term":"CI_CD","note":"— 빌드와 테스트, 배포를 파이프라인으로 묶은 것"},{"term":"Message Queue","note":"— 단계 사이에 일을 쌓아두고 넘길 때 쓴다"},{"term":"Cron Job","note":"— 데이터 파이프라인을 정해진 시각에 시작시킨다"},{"term":"Orchestrator","note":"— 여러 단계의 순서와 재실행을 맡는 쪽"}]},{"id":"arch--pub-sub","term":"Pub/Sub","reading":"발행-구독","category":"아키텍처 패턴","summary":"Pub/Sub은 **한 번 발행한 소식을 관심 있는 쪽이 각자 받아가는 방식**이다.","aliases":["pub/sub","발행-구독","pub-sub","pub","sub"],"related":[{"term":"Message Queue","note":"— 한 메시지를 한 곳이 가져가는 방식"},{"term":"Event-Driven Architecture","note":"— 이 방식을 바탕으로 삼는 설계"},{"term":"Webhook","note":"— 소식을 HTTP로 밀어주는 더 단순한 방식"},{"term":"Monolith vs Microservices","note":"— 서비스가 늘어날수록 이 방식이 필요해진다"}]},{"id":"arch--rate-limiting","term":"Rate Limiting","reading":"요청량 제한","category":"아키텍처 패턴","summary":"Rate Limiting은 **정해진 시간 안에 부를 수 있는 횟수를 막는 것**이다.","aliases":["rate limiting","요청량 제한"],"related":[{"term":"API Gateway","note":"— 요청량 제한이 주로 놓이는 자리"},{"term":"Circuit Breaker","note":"— 나가는 호출을 막는 쪽. 제한은 들어오는 쪽을 막는다"},{"term":"Redis","note":"— 여러 서버가 횟수를 함께 세는 데 쓰인다"},{"term":"Firewall","note":"— 그 앞단에서 아예 연결을 끊는 쪽"}]},{"id":"arch--service-discovery","term":"Service Discovery","reading":"서비스 디스커버리","category":"아키텍처 패턴","summary":"Service Discovery는 **서비스가 지금 어디 있는지 찾아주는 장치**다.","aliases":["service discovery","서비스 디스커버리"],"related":[{"term":"Load Balancing","note":"— 찾아낸 주소가 여럿일 때 어디로 보낼지 고르는 쪽"},{"term":"API Gateway","note":"— 바깥 요청을 받아 안쪽 서비스를 찾아 넘기는 문"},{"term":"Monolith vs Microservices","note":"— 서비스를 잘게 나누면서 이 장치가 필요해졌다"},{"term":"Kubernetes","note":"— 컨테이너를 띄우며 등록과 해지를 대신해주는 쪽"}]},{"id":"arch--sharding","term":"Sharding","reading":"샤딩","category":"아키텍처 패턴","summary":"Sharding은 **하나의 데이터베이스를 여러 대로 쪼개 나눠 담는 것**이다.","aliases":["sharding","샤딩"],"related":[{"term":"Index","note":"— 샤딩 전에 먼저 시도해야 할 것"},{"term":"DB","note":"— 샤딩으로 나누는 대상"},{"term":"Hash","note":"— 데이터를 고르게 흩는 데 쓰이는 계산"},{"term":"NoSQL","note":"— 샤딩을 내장해 자동으로 처리해주는 경우가 많다"}]},{"id":"arch--trpc","term":"tRPC","reading":"","category":"아키텍처 패턴","summary":"tRPC는 **서버 함수의 타입을 클라이언트에 그대로 물려주는 도구**다.","aliases":["trpc"],"related":[{"term":"API","note":"— tRPC가 대신 서는 자리"},{"term":"GraphQL","note":"— 스키마를 따로 두고 타입을 맞추는 다른 방법"},{"term":"REST","note":"— 규약으로 주고받되 타입은 양쪽이 각자 적는 쪽"},{"term":"gRPC","note":"— 스키마 파일로 양쪽 코드를 만들어내는 RPC 방식"}]},{"id":"arch--vs","term":"모놀리스 vs 마이크로서비스","reading":"","category":"아키텍처 패턴","summary":"모놀리스와 마이크로서비스는 **기능을 한 덩어리로 둘지 쪼갤지**의 차이다.","aliases":["모놀리스 vs 마이크로서비스","monolith vs microservices","모놀리스","마이크로서비스"],"related":[{"term":"API Gateway","note":"— 나뉜 서비스들 앞에서 요청을 받아 나눠 보내는 자리"},{"term":"Circuit Breaker","note":"— 나눠도 장애가 번지지 않게 하려면 따로 붙여야 하는 장치"},{"term":"Docker","note":"— 서비스마다 다른 환경을 담아 옮기는 단위"},{"term":"Kubernetes","note":"— 서비스가 여러 개가 되면 배치와 확장을 맡는 자리"},{"term":"CI_CD","note":"— 서비스별로 따로 배포하려면 먼저 갖춰야 하는 것"}]},{"id":"arch--term-f4ea9317","term":"이벤트 기반 아키텍처","reading":"Event-Driven Architecture","category":"아키텍처 패턴","summary":"이벤트 기반 아키텍처는 **일어난 일을 알리기만 하고 넘어가는 구조**다.","aliases":["이벤트 기반 아키텍처","event-driven architecture"],"related":[{"term":"Message Queue","note":"— 사건을 받아 쌓아두는 자리. 이 구조의 가운데에 있다"},{"term":"Pub-Sub","note":"— 하나가 발행하고 여럿이 구독하는 기본 형태"},{"term":"Monolith vs Microservices","note":"— 서비스를 나누면서 이 구조가 필요해졌다"},{"term":"Webhook","note":"— 사건을 서비스 밖으로 알릴 때 쓰는 방식"},{"term":"Circuit Breaker","note":"— 직접 호출이 남은 구간에서 장애가 번지는 것을 막는다"}]}]},{"id":"sec","name":"보안 · 인증","blurb":"누구인지 확인하고 지키는 법","terms":[{"id":"sec--api-key","term":"API Key","reading":"API 키","category":"보안 · 인증","summary":"API Key는 **API를 부르는 쪽이 누구인지 알리는 문자열**이다.","aliases":["api key","api 키"],"related":[{"term":"Rate Limiting","note":"— Key 단위로 호출 횟수를 세서 거는 제한"},{"term":"JWT","note":"— 정보를 담아 스스로 검증되는 다른 방식의 인증 토큰"},{"term":"OAuth","note":"— 사용자를 대신해 제3자 앱에 권한을 주는 방식"},{"term":"API Gateway","note":"— Key 검사와 한도 확인을 한곳에 모아 두는 자리"},{"term":"HTTPS","note":"— Key가 오가는 통로를 가려주는 쪽"}]},{"id":"sec--api-token","term":"API Token","reading":"API 토큰","category":"보안 · 인증","summary":"API Token은 **비밀번호 대신 API 를 부를 때 쓰는 문자열**이다.","aliases":["api token","api 토큰"],"related":[{"term":"API Key","note":"— 거의 같은 역할. 권한 범위와 만료를 붙였는지가 갈림길이다"},{"term":"JWT","note":"— 토큰 안에 정보를 담아 서버가 조회 없이 검증하는 방식"},{"term":"OAuth","note":"— 사용자를 대신할 토큰을 안전하게 받아오는 절차"},{"term":"Refresh Token","note":"— 짧게 만료되는 토큰을 다시 발급받는 데 쓰는 짝"}]},{"id":"sec--audit-log","term":"Audit Log","reading":"감사 로그","category":"보안 · 인증","summary":"Audit Log는 **누가 무엇을 했는지 남기는 기록**이다.","aliases":["audit log","감사 로그"],"related":[{"term":"RBAC","note":"— 누가 무엇을 할 수 있는지 정하는 쪽. 감사 로그는 실제로 무엇을 했는지 남긴다"},{"term":"PII","note":"— 접근 기록을 반드시 남겨야 하는 정보"},{"term":"Logging","note":"— 일반 로그. 감사 로그는 그중 책임 추적을 목적으로 하는 갈래다"},{"term":"Guardrail","note":"— 위험한 동작을 막는 쪽. 막힌 시도도 감사 로그에 남는다"},{"term":"Escalation","note":"— 로그에서 이상을 찾은 다음 사람에게 넘기는 단계"}]},{"id":"sec--bastion-host","term":"Bastion Host","reading":"배스천 호스트","category":"보안 · 인증","summary":"Bastion Host는 **내부 서버로 들어가는 유일한 진입점 서버**다.","aliases":["bastion host","배스천 호스트"],"related":[{"term":"DMZ","note":"— 외부와 내부 사이에 두는 완충 구역. 배스천이 놓이는 자리"},{"term":"SSH","note":"— 배스천을 오가는 데 쓰는 접속 방식"},{"term":"Subnet","note":"— 내부 서버를 외부에서 안 보이게 가르는 단위"},{"term":"Audit Log","note":"— 배스천이 남기는 접속 기록"},{"term":"Zero Trust","note":"— 문 하나를 믿는 대신 매번 검증하자는 반대 방향의 접근"}]},{"id":"sec--ca","term":"CA","reading":"Certificate Authority, 인증 기관","category":"보안 · 인증","summary":"CA는 **인증서에 서명해 서버 신원을 보증하는 기관**이다.","aliases":["ca","certificate authority, 인증 기관"],"related":[{"term":"Certificate","note":"— CA 가 서명해 내주는 그 파일"},{"term":"CSR","note":"— 발급을 신청할 때 내는 요청서"},{"term":"SSL_TLS","note":"— 이 인증서를 주고받으며 연결을 맺는 규약"},{"term":"HTTPS","note":"— 검증이 통과해야 자물쇠가 뜨는 자리"}]},{"id":"sec--csrf","term":"CSRF","reading":"Cross-Site Request Forgery","category":"보안 · 인증","summary":"CSRF는 **로그인한 사용자의 브라우저로 몰래 요청을 보내는 공격**이다.","aliases":["csrf","cross-site request forgery"],"related":[{"term":"Cookie","note":"— 브라우저가 자동으로 붙여주는 성질이 이 공격의 출발점이다"},{"term":"Session","note":"— CSRF가 빌려 쓰는 로그인 상태"},{"term":"XSS","note":"— 스크립트를 심는 공격. 이게 뚫리면 CSRF 방어도 같이 무너진다"},{"term":"JWT","note":"— 쿠키 대신 헤더로 보내면 자동 첨부가 없어 표면이 줄어든다"}]},{"id":"sec--certificate","term":"Certificate","reading":"인증서","category":"보안 · 인증","summary":"인증서는 **이 서버가 그 도메인의 주인이 맞다고 제3자가 보증한 파일**이다.","aliases":["certificate","인증서"],"related":[{"term":"HTTPS","note":"— 인증서 확인이 끝나고 나서 시작되는 통신"},{"term":"SSL_TLS","note":"— 인증서를 확인하고 열쇠를 주고받는 규칙"},{"term":"CA","note":"— 인증서에 서명해주는 발급 기관"},{"term":"암호화","note":"— 인증서에 실린 공개키로 열쇠를 주고받는 방식"},{"term":"DNS","note":"— 인증서에 적힌 도메인을 IP 로 바꾸는 쪽"}]},{"id":"sec--cookie","term":"Cookie","reading":"쿠키","category":"보안 · 인증","summary":"쿠키는 **서버가 브라우저에 맡겨두고 매 요청마다 돌려받는 쪽지**다.","aliases":["cookie","쿠키"],"related":[{"term":"Session","note":"— 쿠키에 담긴 값으로 서버 쪽에서 찾아내는 상태"},{"term":"JWT","note":"— 서버에 상태를 두지 않는 방식. 쿠키에 담기도 한다"},{"term":"XSS","note":"— 스크립트로 쿠키를 훔쳐가는 공격. HttpOnly 가 막는다"},{"term":"CSRF","note":"— 쿠키가 자동으로 붙는 성질을 노린 공격. SameSite 가 막는다"},{"term":"HTTP","note":"— 요청 사이를 기억하지 않아서 쿠키가 생겼다"}]},{"id":"sec--dac","term":"DAC","reading":"Data Access Control","category":"보안 · 인증","summary":"DAC는 **데이터 접근을 가운데서 통제하고 기록하는 계층**이다.","aliases":["dac","data access control"],"related":[{"term":"RBAC","note":"— 누구에게 무엇을 허용할지 역할로 정하는 방식"},{"term":"Audit Log","note":"— DAC 가 남기는 기록 그 자체"},{"term":"IAM","note":"— 계정과 권한을 관리하는 상위 체계"},{"term":"Bastion Host","note":"— 접근 통로를 한 곳으로 모은다는 점에서 같은 발상"}]},{"id":"sec--dmz","term":"DMZ","reading":"Demilitarized Zone, 비무장 지대","category":"보안 · 인증","summary":"DMZ는 **외부에 열어야 할 서버만 따로 모아두는 중간 구역**이다.","aliases":["dmz","demilitarized zone, 비무장 지대"],"related":[{"term":"Firewall","note":"— DMZ를 만드는 도구. 두 겹으로 세워 구역을 가른다"},{"term":"Bastion Host","note":"— 관리자가 내부로 들어갈 때 거치는 진입점. DMZ에 놓인다"},{"term":"Subnet","note":"— 클라우드에서 DMZ와 내부망을 나눌 때 쓰는 단위"},{"term":"인바운드 아웃바운드","note":"— 방향마다 다른 규칙을 거는 그 방향의 이름"},{"term":"VPC","note":"— 클라우드에서 이 구조 전체를 담는 가상 네트워크"}]},{"id":"sec--encryption","term":"Encryption","reading":"암호화","category":"보안 · 인증","summary":"Encryption은 **키가 있어야 되돌릴 수 있게 바꿔두는 일**이다.","aliases":["encryption","암호화"],"related":[{"term":"Hash","note":"— 되돌릴 수 없는 쪽. 비밀번호와 무결성 확인에 쓴다"},{"term":"HTTPS","note":"— 오가는 길을 암호화로 감싼 통신"},{"term":"SSL_TLS","note":"— HTTPS 가 쓰는 암호화 프로토콜"},{"term":"PII","note":"— 암호화로 지켜야 할 대표적인 데이터"}]},{"id":"sec--iam","term":"IAM","reading":"Identity and Access Management","category":"보안 · 인증","summary":"IAM은 **누가 어떤 자원에 무엇을 할 수 있는지 정해두는 체계**다.","aliases":["iam","identity and access management"],"related":[{"term":"RBAC","note":"— 역할 단위로 권한을 묶는 방식. IAM 안에서도 쓰인다"},{"term":"MFA","note":"— 접근 조건에 하나 더 얹을 수 있는 인증 수단"},{"term":"API Key","note":"— 오래 사는 자격 증명. 역할이 주는 임시 자격과 대비된다"},{"term":"Audit Log","note":"— 누가 무엇에 접근했는지 남기는 기록"},{"term":"Zero Trust","note":"— 안쪽이라고 믿지 않고 매번 확인하는 사고방식"}]},{"id":"sec--ipsec-vpn","term":"IPSec VPN","reading":"Internet Protocol Security VPN","category":"보안 · 인증","summary":"IPSec VPN은 **인터넷 위에 암호화된 통로를 만드는 방식**이다.","aliases":["ipsec vpn","internet protocol security vpn"],"related":[{"term":"VPN","note":"— IPSec은 VPN을 만드는 방식 가운데 하나다"},{"term":"Tunnel","note":"— 원래 패킷을 다른 패킷 안에 감싸 보내는 그 기법"},{"term":"암호화","note":"— 터널 안의 내용을 읽지 못하게 만드는 부분"},{"term":"인증서","note":"— 연결 전에 서로가 맞는지 확인할 때 쓰는 수단"},{"term":"SSL_TLS","note":"— 응용 계층에서 같은 일을 하는 다른 방식"}]},{"id":"sec--jwt","term":"JWT","reading":"JSON Web Token","category":"보안 · 인증","summary":"JWT는 **내용과 서명을 함께 담아 위조를 막은 토큰**이다.","aliases":["jwt","json web token"],"related":[{"term":"Session","note":"— 서버가 기억하는 방식. JWT와 반대편"},{"term":"OAuth","note":"— 발급되는 토큰의 형식으로 JWT를 쓰는 경우가 많다"},{"term":"SSO","note":"— 여러 서비스가 같은 토큰을 신뢰하는 구조"},{"term":"Cookie","note":"— 토큰을 어디에 저장할지의 선택지 중 하나"}]},{"id":"sec--mfa","term":"MFA","reading":"Multi-Factor Authentication","category":"보안 · 인증","summary":"MFA는 **종류가 다른 증거를 둘 이상 요구하는 인증**이다.","aliases":["mfa","multi-factor authentication"],"related":[{"term":"Step-up Auth","note":"— 위험한 동작 앞에서만 한 번 더 요구하는 방식"},{"term":"IAM","note":"— 접근 조건에 MFA 통과 여부를 넣을 수 있다"},{"term":"SSO","note":"— 한 번의 인증으로 여러 서비스를 여는 방식. MFA와 같이 쓴다"},{"term":"Zero Trust","note":"— 안쪽이라고 믿지 않는 사고방식. MFA가 그 수단 중 하나다"}]},{"id":"sec--oauth-2-0","term":"OAuth 2.0","reading":"","category":"보안 · 인증","summary":"OAuth는 **비밀번호를 넘기지 않고 권한만 빌려주는 규약**이다.","aliases":["oauth 2.0","oauth"],"related":[{"term":"JWT","note":"— 발급되는 토큰의 형식으로 자주 쓰인다"},{"term":"SSO","note":"— 한 번 로그인으로 여러 서비스를 쓰는 구조"},{"term":"Refresh Token","note":"— 만료된 액세스 토큰을 다시 받는 장치"},{"term":"API Key","note":"— 권한 범위나 회수 개념이 없는 더 단순한 방식"}]},{"id":"sec--pii","term":"PII","reading":"Personally Identifiable Information","category":"보안 · 인증","summary":"PII는 **특정 개인을 알아낼 수 있는 정보**다.","aliases":["pii","personally identifiable information"],"related":[{"term":"암호화","note":"— 되돌릴 수 있게 가리는 방법. 원본이 다시 필요한 값에 쓴다"},{"term":"Hash","note":"— 되돌릴 수 없게 바꾸는 쪽. 익명화에 쓴다"},{"term":"RBAC","note":"— 역할에 따라 원본을 볼지 마스킹을 볼지 가르는 장치"},{"term":"Audit Log","note":"— 누가 언제 PII를 열어봤는지 남기는 기록"},{"term":"Guardrail","note":"— 챗봇 입출력에서 PII를 걸러내는 장치"}]},{"id":"sec--querypie","term":"QueryPie","reading":"","category":"보안 · 인증","summary":"QueryPie는 **데이터베이스 접근을 한곳에서 통제하는 플랫폼**이다.","aliases":["querypie"],"related":[{"term":"Audit Log","note":"— QueryPie가 쿼리마다 남기는 기록"},{"term":"RBAC","note":"— 사람이 아니라 역할에 권한을 붙이는 방식"},{"term":"PII","note":"— 마스킹의 대상이 되는 개인정보"},{"term":"Bastion Host","note":"— 서버 접속에서 같은 구조를 만드는 진입점"}]},{"id":"sec--rbac","term":"RBAC","reading":"Role-Based Access Control","category":"보안 · 인증","summary":"RBAC은 **권한을 사람이 아니라 역할에 붙이는 방식**이다.","aliases":["rbac","role-based access control"],"related":[{"term":"IAM","note":"— 사용자와 역할, 권한을 묶어 관리하는 상위 체계"},{"term":"DAC","note":"— 자원 주인이 직접 권한을 주는 방식. 역할을 거치지 않는다"},{"term":"JWT","note":"— 확인된 역할을 담아 요청마다 들고 다니는 토큰"},{"term":"Audit Log","note":"— 누가 어떤 권한으로 무엇을 했는지 남기는 기록"}]},{"id":"sec--refresh-token","term":"Refresh Token","reading":"리프레시 토큰","category":"보안 · 인증","summary":"Refresh Token은 **만료된 액세스 토큰을 다시 받아오는 열쇠**다.","aliases":["refresh token","리프레시 토큰"],"related":[{"term":"Token 인증","note":"— 로그인 상태를 토큰으로 들고 다니는 방식 전체"},{"term":"JWT","note":"— 두 토큰을 담는 데 흔히 쓰는 형식"},{"term":"OAuth","note":"— 이 두 토큰 구조를 표준으로 정해둔 규약"},{"term":"Session","note":"— 서버가 상태를 들고 있는 방식. 토큰 방식과 갈리는 지점"},{"term":"XSS","note":"— `localStorage` 에 둔 토큰을 그대로 읽어가는 공격"}]},{"id":"sec--saml","term":"SAML","reading":"Security Assertion Markup Language","category":"보안 · 인증","summary":"SAML은 **한 곳에서 확인한 신원을 여러 서비스가 믿게 하는 규약**이다.","aliases":["saml","security assertion markup language"],"related":[{"term":"SSO","note":"— SAML이 구현하려는 목표 그 자체"},{"term":"OAuth","note":"— 인증이 아니라 권한 위임을 다루는 이웃 규약"},{"term":"IAM","note":"— 누가 무엇을 할 수 있는지 관리하는 큰 틀"},{"term":"Certificate","note":"— 보증서 서명을 검증할 때 쓰는 IdP의 공개 인증서"},{"term":"Session","note":"— 검증이 끝난 뒤 SP가 만들어 유지하는 것"}]},{"id":"sec--sql-injection","term":"SQL Injection","reading":"SQL 삽입","category":"보안 · 인증","summary":"SQL Injection은 **입력값이 데이터가 아니라 명령으로 실행되는 공격**이다.","aliases":["sql injection","sql 삽입"],"related":[{"term":"XSS","note":"— 같은 뿌리의 문제. 이쪽은 브라우저에서 실행된다"},{"term":"Index","note":"— 질의문을 다루는 다른 주제"},{"term":"Audit Log","note":"— 뚫렸을 때 무엇이 나갔는지 아는 수단"},{"term":"암호화","note":"— 뚫려도 내용을 못 읽게 하는 다음 겹"}]},{"id":"sec--ssh","term":"SSH","reading":"Secure Shell","category":"보안 · 인증","summary":"SSH는 **멀리 있는 컴퓨터에 암호화된 통로로 접속하는 규약**이다.","aliases":["ssh","secure shell"],"related":[{"term":"TCP","note":"— SSH 연결이 올라타는 아래층"},{"term":"암호화","note":"— SSH 통로 안을 가려주는 원리"},{"term":"Port Forwarding","note":"— SSH 통로 안으로 다른 포트를 끌어오는 기능"},{"term":"Bastion Host","note":"— 내부망에 들어갈 때 SSH로 먼저 거치는 서버"},{"term":"VPN","note":"— 통로를 만드는 다른 방법. 적용 범위가 더 넓다"}]},{"id":"sec--ssl-tls","term":"SSL/TLS","reading":"","category":"보안 · 인증","summary":"TLS는 **오가는 데이터를 가리고 상대가 맞는지 확인하는 규약**이다.","aliases":["ssl/tls","ssl_tls","ssl","tls"],"related":[{"term":"HTTPS","note":"— HTTP 를 TLS 위에 올린 것"},{"term":"인증서","note":"— 서버가 그 도메인의 주인임을 보이는 문서"},{"term":"CA","note":"— 그 인증서에 서명해주는 기관"},{"term":"암호화","note":"— TLS 가 내용을 가릴 때 쓰는 계산"},{"term":"TCP","note":"— TLS 가 그 위에 얹히는 아래층 규약"}]},{"id":"sec--sso","term":"SSO","reading":"Single Sign-On","category":"보안 · 인증","summary":"SSO는 **한 번 로그인하면 여러 서비스를 그대로 쓰는 방식**이다.","aliases":["sso","single sign-on"],"related":[{"term":"OAuth","note":"— 권한을 빌려주는 규약. SSO의 재료로 쓰인다"},{"term":"JWT","note":"— 증표를 담는 형식으로 자주 쓰인다"},{"term":"SAML","note":"— 기업 환경에서 오래 쓰인 증표 교환 방식"},{"term":"Zero Trust","note":"— 한 번 통과했다고 계속 믿지 않는 반대 방향의 원칙"}]},{"id":"sec--step-up-auth","term":"Step-up Auth","reading":"추가 인증","category":"보안 · 인증","summary":"Step-up Auth는 **민감한 작업 앞에서 한 번 더 본인을 확인하는 절차**다.","aliases":["step-up auth","추가 인증"],"related":[{"term":"Token 인증","note":"— 지금 인증 수준이 얼마인지를 담아 나르는 수단"},{"term":"MFA","note":"— 로그인 시점에 수단을 둘 이상 요구하는 쪽"},{"term":"Session","note":"— 승격된 상태를 어디에 들고 있을지의 문제"},{"term":"Audit Log","note":"— 추가 인증 시도를 남겨두는 기록"}]},{"id":"sec--token","term":"Token 인증","reading":"Token Authentication","category":"보안 · 인증","summary":"Token 인증은 **로그인 때 받은 출입증으로 신원을 증명하는 방식**이다.","aliases":["token 인증","token authentication"],"related":[{"term":"JWT","note":"— 토큰 인증에서 가장 많이 쓰는 토큰 형식"},{"term":"Session","note":"— 서버가 기억하는 쪽. 즉시 끊기가 쉽다"},{"term":"Refresh Token","note":"— 짧은 Access Token을 다시 받아오는 긴 수명의 토큰"},{"term":"OAuth","note":"— 다른 서비스의 계정으로 토큰을 받아오는 절차"},{"term":"HTTPS","note":"— 토큰이 중간에서 읽히지 않게 감싸는 것"}]},{"id":"sec--xss","term":"XSS","reading":"Cross-Site Scripting","category":"보안 · 인증","summary":"XSS는 **남의 브라우저에서 내 스크립트를 실행시키는 공격**이다.","aliases":["xss","cross-site scripting"],"related":[{"term":"SQL Injection","note":"— 같은 뿌리의 문제. 이쪽은 DB에서 실행된다"},{"term":"Cookie","note":"— 탈취 대상이자 방어 설정을 거는 곳"},{"term":"CORS","note":"— 다른 출처의 요청을 다루는 별도의 규칙"},{"term":"CSRF","note":"— 같은 브라우저를 노리지만 방향이 반대인 공격"}]},{"id":"sec--zero-trust","term":"Zero Trust","reading":"제로 트러스트","category":"보안 · 인증","summary":"Zero Trust는 **어디서 왔든 매번 다시 확인하는 보안 원칙**이다.","aliases":["zero trust","제로 트러스트"],"related":[{"term":"SSO","note":"— 신원 확인을 한 곳에 모으는 장치. 제로 트러스트의 재료"},{"term":"VPN","note":"— 위치로 신뢰를 주던 옛 방식의 대표"},{"term":"Audit Log","note":"— 확인했다는 사실을 남기는 수단"},{"term":"Step-up Auth","note":"— 위험해 보일 때만 추가 인증을 요구하는 방법"}]},{"id":"sec--term-101f686a","term":"방화벽 규칙","reading":"Firewall Rules","category":"보안 · 인증","summary":"방화벽 규칙은 **어떤 통신을 통과시키고 무엇을 막을지 적어둔 목록**이다.","aliases":["방화벽 규칙","firewall rules"],"related":[{"term":"Firewall","note":"— 이 규칙들을 들고 실제로 판정하는 장치"},{"term":"인바운드 아웃바운드","note":"— 규칙에 적는 두 방향"},{"term":"Port","note":"— 규칙이 가리키는 문의 번호"},{"term":"Zero Trust","note":"— 기본을 차단으로 두는 생각을 전체로 넓힌 것"},{"term":"Bastion Host","note":"— 관리자 접속을 한 곳에 모아 규칙을 단순하게 만드는 방법"}]},{"id":"sec--term-37ee660f","term":"세션","reading":"Session","category":"보안 · 인증","summary":"세션은 **서버가 접속한 사람을 기억해두는 방식**이다.","aliases":["세션","session"],"related":[{"term":"Cookie","note":"— 세션 번호를 브라우저와 서버 사이에 실어 나르는 수단"},{"term":"JWT","note":"— 서버에 저장하지 않고 토큰 안에 정보를 담는 다른 방식"},{"term":"Redis","note":"— 서버 여러 대가 같은 세션을 보게 할 때 쓰는 저장소"},{"term":"CSRF","note":"— 로그인된 세션을 본인 모르게 쓰게 만드는 공격"},{"term":"Token 인증","note":"— 번호 대신 토큰으로 신분을 확인하는 쪽"}]},{"id":"sec--term-7dd2a53a","term":"암호화","reading":"Encryption","category":"보안 · 인증","summary":"암호화는 **열쇠를 가진 사람만 읽을 수 있게 바꾸는 일**이다.","aliases":["암호화","encryption"],"related":[{"term":"Hash","note":"— 되돌릴 길이 없는 쪽. 비밀번호는 이쪽으로 간다"},{"term":"SSL_TLS","note":"— 오가는 통신을 암호화하는 규약"},{"term":"인증서","note":"— 상대의 공개키가 진짜인지 보증하는 문서"},{"term":"HTTPS","note":"— 웹에서 이 암호화가 적용된 결과"}]},{"id":"sec--term-b117da1b","term":"인바운드 / 아웃바운드 트래픽","reading":"Inbound / Outbound","category":"보안 · 인증","summary":"인바운드와 아웃바운드는 **트래픽이 서버로 들어오는지 나가는지의 방향**이다.","aliases":["인바운드 / 아웃바운드 트래픽","inbound / outbound","인바운드 아웃바운드","인바운드","아웃바운드 트래픽","inbound","outbound"],"related":[{"term":"Firewall","note":"— 인바운드와 아웃바운드 규칙이 걸리는 장치"},{"term":"방화벽 규칙","note":"— 방향, 상대, 포트, 허용 여부로 이루어진 한 줄"},{"term":"Port","note":"— 규칙이 가리키는 번호"},{"term":"Subnet","note":"— 규칙에서 상대를 IP 범위로 지정할 때 쓰는 단위"},{"term":"Bastion Host","note":"— SSH 인바운드를 한 곳으로 모아 좁히는 방법"}]},{"id":"sec--term-23d55d60","term":"인증서","reading":"SSL/TLS Certificate","category":"보안 · 인증","summary":"인증서는 **이 사이트가 맞다고 제3자가 보증한 문서**다.","aliases":["인증서","ssl/tls certificate","tls certificate"],"related":[{"term":"HTTPS","note":"— 인증서가 붙어야 성립하는 프로토콜"},{"term":"SSL_TLS","note":"— 인증서를 주고받고 열쇠를 정하는 절차"},{"term":"CA","note":"— 인증서에 서명해주는 발급 기관"},{"term":"암호화","note":"— 인증서가 확인을 마친 뒤 실제로 내용을 가리는 일"},{"term":"Domain","note":"— 인증서에 적힌 이름과 맞춰봐야 하는 대상"}]}]},{"id":"cloud","name":"클라우드","blurb":"남의 컴퓨터를 빌려 쓰는 법","terms":[{"id":"cloud--aws","term":"AWS","reading":"Amazon Web Services","category":"클라우드","summary":"AWS는 **서버와 저장소를 빌려 쓰는 클라우드 묶음**이다.","aliases":["aws","amazon web services"],"related":[{"term":"Cloud","note":"— AWS가 속한 큰 개념. 빌려 쓰는 방식 전체를 가리킨다"},{"term":"EC2","note":"— AWS가 빌려주는 가상 서버"},{"term":"S3","note":"— 파일을 담아두는 저장소"},{"term":"Lambda","note":"— 서버를 띄우지 않고 함수만 돌리는 쪽"},{"term":"Azure","note":"— Microsoft가 같은 자리에서 내놓는 것"}]},{"id":"cloud--availability-zone","term":"Availability Zone","reading":"가용 영역","category":"클라우드","summary":"가용 영역은 **한 리전 안에서 전원과 망이 따로 도는 데이터센터 묶음**이다.","aliases":["availability zone","가용 영역"],"related":[{"term":"Region","note":"— 가용 영역을 여러 개 묶는 더 큰 단위"},{"term":"Load Balancer","note":"— 죽은 영역을 빼고 남은 곳으로 요청을 보내는 쪽"},{"term":"VPC","note":"— 여러 가용 영역에 걸쳐 놓는 사설 망"},{"term":"Auto Scaling","note":"— 잃은 만큼 살아 있는 영역에 새로 띄워주는 것"}]},{"id":"cloud--azure","term":"Azure","reading":"Microsoft Azure","category":"클라우드","summary":"Azure는 **Microsoft가 빌려주는 클라우드 플랫폼**이다.","aliases":["azure","microsoft azure"],"related":[{"term":"AWS","note":"— 같은 자리에서 겨루는 Amazon 쪽 플랫폼"},{"term":"Cloud","note":"— Azure가 속한 큰 개념"},{"term":"Kubernetes","note":"— AKS 가 관리형으로 내주는 기반 기술"},{"term":"Serverless","note":"— Azure Functions 가 속한 방식"}]},{"id":"cloud--cloud","term":"Cloud","reading":"클라우드","category":"클라우드","summary":"Cloud는 **컴퓨터 자원을 필요한 만큼 빌려 쓰는 방식**이다.","aliases":["cloud","클라우드"],"related":[{"term":"IaaS_PaaS_SaaS","note":"— 어디까지 맡길지를 나눈 세 가지 층"},{"term":"AWS","note":"— 대표적인 클라우드 제공자"},{"term":"Serverless","note":"— 서버 자체를 의식하지 않는 더 위쪽 방식"},{"term":"EC2","note":"— 빌려 쓰는 가상 서버"},{"term":"S3","note":"— 빌려 쓰는 저장소"}]},{"id":"cloud--ec2","term":"EC2","reading":"Elastic Compute Cloud","category":"클라우드","summary":"EC2는 **AWS 에서 시간 단위로 빌려 쓰는 가상 서버**다.","aliases":["ec2","elastic compute cloud"],"related":[{"term":"AWS","note":"— EC2 를 제공하는 쪽"},{"term":"VM","note":"— EC2 인스턴스가 실제로는 이것이다"},{"term":"VPC","note":"— 인스턴스를 놓을 네트워크 공간"},{"term":"Subnet","note":"— 그 VPC 안에서 인스턴스가 실제로 자리 잡는 구획"},{"term":"Auto Scaling","note":"— 인스턴스 대수를 자동으로 조절하려면 따로 붙인다"}]},{"id":"cloud--iaas-paas-saas","term":"IaaS / PaaS / SaaS","reading":"","category":"클라우드","summary":"IaaS, PaaS, SaaS는 **클라우드가 어디까지 맡느냐**로 나뉜 세 단계다.","aliases":["iaas / paas / saas","iaas_paas_saas","iaas","paas","saas"],"related":[{"term":"Cloud","note":"— 이 세 가지를 묶어 부르는 상위 개념"},{"term":"On-Premises","note":"— 아무것도 맡기지 않고 전부 직접 하는 쪽"},{"term":"VM","note":"— IaaS에서 빌리는 서버의 실체"},{"term":"Serverless","note":"— 실행 환경조차 의식하지 않는, PaaS보다 더 넘긴 형태"},{"term":"Container","note":"— 애플리케이션을 통째로 묶어 어느 층에서든 같게 돌리는 방법"}]},{"id":"cloud--lambda","term":"Lambda","reading":"AWS Lambda","category":"클라우드","summary":"Lambda는 **함수만 올려두고 부를 때만 실행하는 서비스**다.","aliases":["lambda","aws lambda"],"related":[{"term":"Serverless","note":"— Lambda가 속한 큰 갈래"},{"term":"API Gateway","note":"— HTTP 요청을 Lambda로 넘겨주는 앞단"},{"term":"S3","note":"— 파일이 올라온 사건으로 Lambda를 깨우는 곳"},{"term":"EC2","note":"— 켜두고 쓰는 쪽. 비용 계산이 반대로 간다"},{"term":"Container","note":"— Lambda가 함수를 담아 띄우는 단위"}]},{"id":"cloud--region","term":"Region","reading":"리전","category":"클라우드","summary":"Region은 **클라우드 업체가 한 지역에 세운 독립된 데이터센터 묶음**이다.","aliases":["region","리전"],"related":[{"term":"Availability Zone","note":"— 리전 안에서 다시 나뉘는 단위. 견디는 사고의 크기가 다르다"},{"term":"DNS","note":"— 요청을 어느 리전으로 보낼지 정해주는 자리"},{"term":"Latency","note":"— 리전을 어디에 둘지 정할 때 재는 값"},{"term":"CDN","note":"— 리전보다 촘촘한 지점에 복사본을 두어 거리를 더 줄이는 쪽"},{"term":"VPC","note":"— 리전 안에 만드는 가상 네트워크. 리전을 넘어가지 않는다"}]},{"id":"cloud--s3","term":"S3","reading":"Simple Storage Service","category":"클라우드","summary":"S3는 **AWS가 파일을 맡아 보관해주는 저장소**다.","aliases":["s3","simple storage service"],"related":[{"term":"AWS","note":"— S3를 제공하는 쪽"},{"term":"CDN","note":"— S3 앞에 두어 파일을 가까운 곳에서 주게 한다"},{"term":"Lambda","note":"— 파일이 올라온 것을 신호로 받아 뒤처리를 돌린다"},{"term":"EC2","note":"— 파일을 들고 있지 않게 되는 쪽. 서버는 주소만 안다"},{"term":"IAM","note":"— 어떤 계정이 버킷에 무엇을 할 수 있는지 정한다"}]},{"id":"cloud--serverless","term":"Serverless","reading":"서버리스","category":"클라우드","summary":"Serverless는 **서버를 직접 띄우지 않고 함수만 올려 실행하는 방식**이다.","aliases":["serverless","서버리스"],"related":[{"term":"Lambda","note":"— 서버리스 함수의 대표적인 구현"},{"term":"Container","note":"— 서버리스 실행 환경의 바탕이 되는 기술"},{"term":"IaaS_PaaS_SaaS","note":"— 클라우드 서비스 구분에서 서버리스의 자리"},{"term":"Latency","note":"— 첫 호출이 느려지는 현상을 재는 잣대"}]},{"id":"cloud--subnet","term":"Subnet","reading":"서브넷","category":"클라우드","summary":"Subnet은 **큰 네트워크를 쪼개놓은 작은 구획**이다.","aliases":["subnet","서브넷"],"related":[{"term":"VPC","note":"— 서브넷이 속하는 상위 네트워크"},{"term":"Availability Zone","note":"— 서브넷 하나가 묶이는 물리적 단위"},{"term":"IP Address","note":"— 서브넷이 나누는 대상"},{"term":"NAT","note":"— 비공개 구획이 바깥으로 나갈 때 거치는 장치"},{"term":"방화벽 규칙","note":"— 구획 안팎의 실제 허용을 정하는 자리"}]},{"id":"cloud--tenant","term":"Tenant","reading":"테넌트","category":"클라우드","summary":"테넌트는 **같은 시스템을 나눠 쓰면서 서로 격리된 고객 단위**다.","aliases":["tenant","테넌트"],"related":[{"term":"Multi-tenancy","note":"— 테넌트를 여럿 받는 구조 자체를 가리키는 말"},{"term":"IaaS_PaaS_SaaS","note":"— 테넌트 개념이 실제로 쓰이는 서비스 모델"},{"term":"RBAC","note":"— 테넌트 안에서 누가 무엇을 볼지 다시 나누는 장치"},{"term":"VPC","note":"— 자원까지 갈라놓고 싶을 때 쓰는 네트워크 단위"},{"term":"DB","note":"— 격리 방식을 고르는 자리"}]},{"id":"cloud--vpc","term":"VPC","reading":"Virtual Private Cloud","category":"클라우드","summary":"VPC는 **클라우드 안에 내 것만 있는 사설 네트워크**다.","aliases":["vpc","virtual private cloud"],"related":[{"term":"Subnet","note":"— VPC를 다시 나눈 구간"},{"term":"방화벽 규칙","note":"— 무엇을 열고 막을지 적는 규칙"},{"term":"Zero Trust","note":"— 경계 안쪽도 믿지 않는 반대 방향의 원칙"},{"term":"VPN","note":"— 사내망과 VPC를 잇는 방법 중 하나"}]}]},{"id":"infra","name":"인프라 · 운영","blurb":"띄우고, 굴리고, 지켜본다","terms":[{"id":"infra--apache","term":"Apache","reading":"아파치 웹 서버","category":"인프라 · 운영","summary":"Apache는 **HTTP 요청을 받아 웹 페이지를 돌려주는 오픈소스 서버**다.","aliases":["apache","아파치 웹 서버"],"related":[{"term":"Nginx","note":"— 같은 자리를 맡는 다른 웹 서버. 비교 대상으로 자주 붙는다"},{"term":"HTTP","note":"— Apache가 주고받는 규약"},{"term":"Reverse Proxy","note":"— 웹 서버 앞에 서서 요청을 뒤로 넘기는 자리"},{"term":"Linux","note":"— Apache를 서비스로 올려두는 바탕"}]},{"id":"infra--bare-metal","term":"Bare Metal","reading":"베어 메탈","category":"인프라 · 운영","summary":"Bare Metal은 **가상화 없이 물리 서버를 통째로 쓰는 방식**이다.","aliases":["bare metal","베어 메탈"],"related":[{"term":"VM","note":"— 하드웨어 위에 가상 서버를 여러 대 올리는 쪽. 베어 메탈이 뺀 계층이 여기다"},{"term":"Container","note":"— 운영체제는 하나로 두고 프로세스만 나눈다. 중간 무게다"},{"term":"Hypervisor","note":"— 가상 서버를 만들고 관리하는 소프트웨어"},{"term":"On-Premises","note":"— 장비를 직접 두고 쓰는 것. 베어 메탈은 그 위에서 어떻게 쓸지의 문제다"}]},{"id":"infra--ci-cd","term":"CI/CD","reading":"지속적 통합과 배포","category":"인프라 · 운영","summary":"CI/CD는 **코드를 올리면 검사와 배포가 자동으로 도는 파이프라인**이다.","aliases":["ci/cd","지속적 통합과 배포","ci_cd","ci","cd"],"related":[{"term":"Docker","note":"— 파이프라인이 만들어내는 산출물이자 실행 환경"},{"term":"Kubernetes","note":"— 만들어진 이미지를 받아 배포하는 다음 단계"},{"term":"Git","note":"— 파이프라인을 촉발하는 지점"},{"term":"Build","note":"— 파이프라인의 첫 단계"}]},{"id":"infra--cron-job","term":"Cron Job","reading":"크론 잡","category":"인프라 · 운영","summary":"Cron Job은 **정해진 시각마다 명령을 자동 실행하는 예약 작업**이다.","aliases":["cron job","크론 잡"],"related":[{"term":"Logging","note":"— cron이 남긴 실행 결과를 확인하는 자리"},{"term":"Cache","note":"— 캐시를 주기적으로 갱신할 때 흔히 cron을 쓴다"},{"term":"Kubernetes","note":"— 여러 대에 흩어진 예약 작업을 한곳에서 관리하는 쪽"},{"term":"CI_CD","note":"— 정해진 시각마다 빌드를 돌릴 때도 같은 방식이 쓰인다"}]},{"id":"infra--devops","term":"DevOps","reading":"","category":"인프라 · 운영","summary":"DevOps는 **개발과 운영을 한 팀이 함께 맡는 방식**이다.","aliases":["devops"],"related":[{"term":"CI_CD","note":"— DevOps에서 자동화가 실제로 돌아가는 줄기"},{"term":"Docker","note":"— 개발과 운영 환경을 같게 만드는 데 쓴다"},{"term":"Kubernetes","note":"— 컨테이너를 배포하고 굴리는 자리"},{"term":"Git","note":"— 파이프라인의 방아쇠인 커밋이 여기서 일어난다"},{"term":"Container","note":"— 환경을 통째로 묶어 옮기는 단위"}]},{"id":"infra--elastic-search","term":"Elastic Search","reading":"엘라스틱서치","category":"인프라 · 운영","summary":"Elastic Search 는 **글을 단어로 쪼개 미리 색인해두는 검색 엔진**이다.","aliases":["elastic search","엘라스틱서치"],"related":[{"term":"Index","note":"— 미리 만들어두는 단어 목록. 속도의 이유"},{"term":"NoSQL","note":"— 문서를 그대로 담아 두고 뒤진다는 점이 닮았다"},{"term":"Semantic Search","note":"— 단어가 아니라 뜻이 가까운지로 찾는 쪽"},{"term":"Logging","note":"— 쌓인 로그를 뒤질 때 자주 함께 쓰인다"}]},{"id":"infra--hypervisor","term":"Hypervisor","reading":"하이퍼바이저","category":"인프라 · 운영","summary":"Hypervisor는 **한 대의 컴퓨터를 여러 대처럼 나눠 쓰게 하는 소프트웨어**다.","aliases":["hypervisor","하이퍼바이저"],"related":[{"term":"VM","note":"— 하이퍼바이저가 만들고 관리하는 대상"},{"term":"Container","note":"— 하이퍼바이저 없이 OS 커널을 나눠 쓰는 다른 방식"},{"term":"VPS","note":"— 하이퍼바이저로 나눈 한 칸을 빌려주는 상품"},{"term":"Bare Metal","note":"— 나누지 않고 하드웨어를 통째로 쓰는 쪽"}]},{"id":"infra--kubernetes","term":"Kubernetes","reading":"쿠버네티스","category":"인프라 · 운영","summary":"Kubernetes는 **컨테이너를 어디에 몇 개 띄울지 알아서 관리하는 시스템**이다.","aliases":["kubernetes","쿠버네티스"],"related":[{"term":"Container","note":"— 쿠버네티스가 관리하는 대상"},{"term":"Docker","note":"— 그 컨테이너 이미지를 만드는 도구"},{"term":"Load Balancer","note":"— 파드로 요청을 나누는 데 쓰인다"},{"term":"CI_CD","note":"— 새 이미지를 만들어 클러스터에 넘기는 앞 단계"}]},{"id":"infra--logging","term":"Logging","reading":"로그, 로깅","category":"인프라 · 운영","summary":"Logging은 **프로그램이 한 일을 나중에 볼 수 있게 남기는 일**이다.","aliases":["logging","로그, 로깅"],"related":[{"term":"Audit Log","note":"— 누가 무엇을 했는지에 초점을 맞춘 기록"},{"term":"Elastic Search","note":"— 모아둔 로그를 검색하는 데 흔히 쓰는 저장소"},{"term":"JSON","note":"— 구조화 로그를 남길 때 쓰는 형식"},{"term":"Latency","note":"— 단계마다 남긴 시간을 모아 보는 값"}]},{"id":"infra--on-premises","term":"On-Premises","reading":"온프레미스","category":"인프라 · 운영","summary":"On-Premises는 **서버를 직접 사서 자기 공간에 두고 운영하는 방식**이다.","aliases":["on-premises","온프레미스"],"related":[{"term":"Cloud","note":"— 남의 인프라를 빌려 쓰는 반대쪽 방식"},{"term":"Bare Metal","note":"— 가상화 없이 물리 장비를 그대로 쓰는 형태"},{"term":"Auto Scaling","note":"— 필요할 때 즉시 늘리는 클라우드 쪽 기능. 온프레미스에는 없다"},{"term":"VPN","note":"— 밖에서 자체 시설 안으로 들어올 때 쓰는 통로"},{"term":"IaaS_PaaS_SaaS","note":"— 어디까지 남에게 맡기느냐로 나눈 구분"}]},{"id":"infra--ttl","term":"TTL","reading":"Time To Live","category":"인프라 · 운영","summary":"TTL은 **데이터가 유효한 시간을 미리 정해둔 값**이다.","aliases":["ttl","time to live"],"related":[{"term":"Cache","note":"— TTL이 가장 자주 붙는 곳"},{"term":"DNS","note":"— 레코드마다 TTL을 두어 얼마나 오래 캐시할지 정한다"},{"term":"CDN","note":"— 거점이 복사본을 들고 있는 기간을 TTL로 정한다"},{"term":"Redis","note":"— 키마다 TTL을 걸어 자동 만료시키는 저장소"},{"term":"Session","note":"— TTL로 유효 기간을 관리하는 대표적인 데이터"}]},{"id":"infra--vm","term":"VM","reading":"Virtual Machine, 가상 머신","category":"인프라 · 운영","summary":"VM은 **소프트웨어로 만들어진 컴퓨터 한 대**다.","aliases":["vm","virtual machine, 가상 머신"],"related":[{"term":"Hypervisor","note":"— VM 을 만들고 자원을 떼어 주는 층"},{"term":"Container","note":"— 운영체제를 얹지 않고 커널을 나눠 쓰는 가벼운 쪽"},{"term":"Bare Metal","note":"— 나누지 않고 물리 서버를 통째로 쓰는 쪽"},{"term":"VPS","note":"— VM 한 칸을 빌려주는 상품"},{"term":"On-Premises","note":"— 남의 데이터 센터가 아니라 우리 건물에 이걸 두는 방식"}]},{"id":"infra--vps","term":"VPS","reading":"Virtual Private Server","category":"인프라 · 운영","summary":"VPS는 **물리 서버 한 대를 쪼개 나눠 쓰는 가상 서버**다.","aliases":["vps","virtual private server"],"related":[{"term":"VM","note":"— VPS를 만들어내는 기반 기술"},{"term":"Hypervisor","note":"— 물리 서버를 나눠 각 VPS에 몫을 주는 층"},{"term":"SSH","note":"— VPS에 들어가 관리할 때 쓰는 접속 방법"},{"term":"Multi-tenancy","note":"— 한 기계를 여러 고객이 나눠 쓰는 구조"},{"term":"Bare Metal","note":"— 나누지 않고 기계를 통째로 쓰는 쪽"}]}]},{"id":"tool","name":"개발 도구","blurb":"매일 손에 잡는 것들","terms":[{"id":"tool--breakpoint","term":"Breakpoint","reading":"중단점","category":"개발 도구","summary":"Breakpoint는 **실행이 이 줄에 닿으면 멈추라고 남기는 표시**다.","aliases":["breakpoint","중단점"],"related":[{"term":"Debugger","note":"— 이 표시를 읽고 실제로 멈춰 세우는 도구"},{"term":"IDE","note":"— 여백을 눌러 표시를 찍고 값을 보여주는 화면"},{"term":"Loop","note":"— 안에 중단점을 찍으면 수천 번 멈추는 그 구조"},{"term":"Logging","note":"— 세우면 안 되는 자리에서 추적점이 대신 하는 일"},{"term":"Variable","note":"— 멈춘 자리에서 값을 확인하는 대상"}]},{"id":"tool--cli","term":"CLI","reading":"Command Line Interface","category":"개발 도구","summary":"CLI는 **글자로 명령을 적어 컴퓨터를 시키는 방식**이다.","aliases":["cli","command line interface"],"related":[{"term":"Terminal","note":"— 글자를 띄우고 입력을 받는 창"},{"term":"SSH","note":"— 원격 서버에 CLI 로 붙는 통로"},{"term":"Linux","note":"— CLI 로 다루는 일이 가장 많은 운영체제"},{"term":"Git","note":"— CLI 로 쓰는 대표적인 도구"},{"term":"Docker","note":"— 컨테이너를 명령 한 줄로 띄우고 내린다"}]},{"id":"tool--cherry-pick","term":"Cherry-pick","reading":"체리픽","category":"개발 도구","summary":"Cherry-pick은 **커밋 하나만 골라 지금 가지에 옮겨 얹는 일**이다.","aliases":["cherry-pick","체리픽"],"related":[{"term":"Git","note":"— 이 명령이 속한 도구. 커밋과 가지가 있어야 성립한다"},{"term":"Git Stash","note":"— 작업 트리를 깨끗하게 만들어 체리픽을 시작할 수 있게 해준다"},{"term":"Trunk Based Development","note":"— 줄기에서 고친 것을 릴리스 가지로 내려보낼 때 이 명령을 쓴다"},{"term":"CI_CD","note":"— 옮겨 붙인 커밋도 그 가지에서 빌드와 테스트를 다시 통과해야 한다"}]},{"id":"tool--container","term":"Container","reading":"컨테이너","category":"개발 도구","summary":"Container는 **하나의 프로세스를 격리해서 돌리는 방식**이다.","aliases":["container","컨테이너"],"related":[{"term":"Docker","note":"— 컨테이너를 만들고 돌리는 대표적인 도구"},{"term":"Kubernetes","note":"— 컨테이너가 많아졌을 때 배치와 복구를 맡는다"},{"term":"VM","note":"— 운영체제를 통째로 띄우는 더 강한 격리"},{"term":"Hypervisor","note":"— 가상 머신을 만드는 계층"}]},{"id":"tool--debugger","term":"Debugger","reading":"디버거","category":"개발 도구","summary":"Debugger는 **실행을 멈춰 세우고 그 속을 들여다보는 도구**다.","aliases":["debugger","디버거"],"related":[{"term":"Breakpoint","note":"— 디버거에게 어디서 멈출지 알려주는 표시"},{"term":"Logging","note":"— 멈추지 않고 지나가며 기록만 남기는 반대쪽 방법"},{"term":"IDE","note":"— 디버깅 클라이언트를 화면에 붙여주는 편집기"},{"term":"Stack","note":"— 멈춘 자리에서 들여다보는 호출 스택이 쌓이는 그 구조"},{"term":"Process","note":"— 디버거가 붙는 대상. 붙은 쪽은 그 권한으로 코드를 돌릴 수 있다"}]},{"id":"tool--dependency","term":"Dependency","reading":"의존성","category":"개발 도구","summary":"의존성은 **내 코드가 돌아가려면 있어야 하는 남의 코드**다.","aliases":["dependency","의존성"],"related":[{"term":"Package Manager","note":"— 적어 둔 의존성을 실제로 받아다 놓는 도구"},{"term":"Lock File","note":"— 범위로 적힌 의존성이 실제로 어느 버전으로 깔렸는지 적어 두는 파일"},{"term":"Package","note":"— 의존성으로 걸리는 단위 하나"},{"term":"Build","note":"— 받아 온 의존성을 내 코드와 함께 묶는 다음 단계"}]},{"id":"tool--docker","term":"Docker","reading":"도커","category":"개발 도구","summary":"Docker는 **프로그램과 실행 환경을 한 덩어리로 묶는 도구**다.","aliases":["docker","도커"],"related":[{"term":"Container","note":"— Docker가 만들어 실행하는 대상"},{"term":"Kubernetes","note":"— 컨테이너가 많아졌을 때 관리를 맡는 도구"},{"term":"VM","note":"— 운영체제를 통째로 띄우는 더 무거운 격리 방식"},{"term":"CI_CD","note":"— 컨테이너를 실행 환경으로 삼는 대표적인 자리"}]},{"id":"tool--docker-compose","term":"Docker Compose","reading":"도커 컴포즈","category":"개발 도구","summary":"Docker Compose는 **여러 컨테이너를 한 파일로 정의해 함께 띄우는 도구**다.","aliases":["docker compose","도커 컴포즈"],"related":[{"term":"Docker","note":"— 컴포즈가 지휘하는 컨테이너를 실제로 만드는 도구"},{"term":"Container","note":"— 컴포즈가 한 파일로 여러 개 묶는 대상"},{"term":"Kubernetes","note":"— 호스트 한 대를 넘어설 때 넘어가는 쪽"},{"term":"YAML","note":"— `compose.yaml` 을 적는 형식"},{"term":"Environment Variable","note":"— 같은 파일을 환경마다 다르게 쓰게 하는 변수"}]},{"id":"tool--docker-image","term":"Docker Image","reading":"도커 이미지","category":"개발 도구","summary":"Docker Image는 **실행에 필요한 것을 다 담은 읽기 전용 꾸러미**다.","aliases":["docker image","도커 이미지"],"related":[{"term":"Container","note":"— 이미지를 실행해서 돌고 있는 상태"},{"term":"Dockerfile","note":"— 이 이미지를 무엇으로 어떻게 만들지 적은 파일"},{"term":"Docker","note":"— 이미지를 만들고 받고 실행하는 도구"},{"term":"Docker Volume","note":"— 이미지에 담을 수 없는 데이터를 밖에 두는 자리"},{"term":"Kubernetes","note":"— 어느 이미지를 몇 개 띄울지 정하는 층"}]},{"id":"tool--docker-volume","term":"Docker Volume","reading":"도커 볼륨","category":"개발 도구","summary":"Docker Volume은 **컨테이너가 지워져도 남는 데이터 저장 칸**이다.","aliases":["docker volume","도커 볼륨"],"related":[{"term":"Container","note":"— 지워지면 안에 쓴 파일이 같이 사라지는 그 대상"},{"term":"Docker Image","note":"— 읽기 전용이라 데이터를 담아둘 수 없는 쪽"},{"term":"Docker","note":"— 볼륨을 만들고 컨테이너에 붙여주는 도구"},{"term":"DB","note":"— 볼륨이 가장 먼저 필요해지는 자리"},{"term":"File System","note":"— 볼륨이 실제로 놓이는 호스트 쪽 저장 구조"}]},{"id":"tool--dockerfile","term":"Dockerfile","reading":"도커파일","category":"개발 도구","summary":"Dockerfile은 **이미지를 만드는 순서를 적은 텍스트 파일**이다.","aliases":["dockerfile","도커파일"],"related":[{"term":"Docker Image","note":"— Dockerfile 을 빌드해서 나오는 결과물"},{"term":"Docker","note":"— Dockerfile 을 읽어 이미지를 만드는 도구"},{"term":"Container","note":"— 그 이미지를 실제로 실행한 상태"},{"term":"Cache","note":"— 바뀌지 않은 층을 다시 만들지 않게 하는 그 원리"},{"term":"CI_CD","note":"— Dockerfile 빌드가 커밋마다 돌아가는 자리"}]},{"id":"tool--feature-flag","term":"Feature Flag","reading":"기능 플래그","category":"개발 도구","summary":"Feature Flag는 **다시 배포하지 않고 기능을 켜고 끄는 스위치**다.","aliases":["feature flag","기능 플래그"],"related":[{"term":"Trunk Based Development","note":"— 덜 끝난 코드를 줄기에 합치게 해 주는 짝. 규범 문서가 플래그를 그 장치로 든다"},{"term":"A B Testing","note":"— 플래그로 갈래를 나눠 두 안을 비교하는 대표적 활용"},{"term":"CI_CD","note":"— 플래그 조합마다 갈라 돌려야 하는 자동 검사 쪽"},{"term":"Environment Variable","note":"— 설정을 코드 밖으로 빼는 더 원시적인 방식. 바꾸려면 다시 띄워야 한다"}]},{"id":"tool--git","term":"Git","reading":"형상 관리 시스템","category":"개발 도구","summary":"Git은 **코드가 바뀐 이력을 시점마다 기록해두는 도구**다.","aliases":["git","형상 관리 시스템"],"related":[{"term":"CLI","note":"— git 명령을 실제로 입력하는 자리"},{"term":"Terminal","note":"— 그 명령을 치는 창"},{"term":"CI_CD","note":"— push를 방아쇠로 빌드와 배포가 이어진다"},{"term":"DevOps","note":"— 커밋에서 배포까지를 한 줄기로 잇는 방식. 그 출발점이 Git이다"}]},{"id":"tool--git-branch","term":"Git Branch","reading":"브랜치","category":"개발 도구","summary":"Git Branch 는 **커밋 하나를 가리키는 이름표**다.","aliases":["git branch","브랜치"],"related":[{"term":"Git","note":"— 브랜치라는 장치를 담고 있는 이력 관리 도구"},{"term":"Git Commit","note":"— 브랜치라는 이름표가 실제로 가리키는 대상"},{"term":"Merge vs Rebase","note":"— 갈라 놓은 가지를 다시 합치는 두 가지 방법"},{"term":"Hash","note":"— 이름표 안에 적히는 그 40자 값을 만드는 방식"},{"term":"CLI","note":"— `git branch` 와 `git switch` 를 실제로 치는 자리"}]},{"id":"tool--git-commit","term":"Git Commit","reading":"커밋","category":"개발 도구","summary":"Git Commit 은 **그 순간의 프로젝트 전체를 남긴 기록 하나**다.","aliases":["git commit","커밋"],"related":[{"term":"Git","note":"— 커밋을 쌓아 이력으로 만드는 도구"},{"term":"Git Branch","note":"— 커밋 하나를 가리키는 이름표. 커밋이 쌓이면 따라 옮겨 간다"},{"term":"Merge vs Rebase","note":"— 쌓인 커밋을 다른 가지에 합치거나 다시 얹는 두 방법"},{"term":"Hash","note":"— 커밋에 40자 이름을 붙일 때 쓰는 방식"},{"term":"CLI","note":"— `git add` 와 `git commit` 을 실제로 치는 자리"}]},{"id":"tool--git-stash","term":"Git Stash","reading":"깃 스태시","category":"개발 도구","summary":"Git Stash는 **커밋하지 않은 변경을 잠깐 치워 두는 서랍**이다.","aliases":["git stash","깃 스태시"],"related":[{"term":"Git","note":"— 서랍이 딸려 있는 도구. 커밋과 가지가 있는 그 저장소 안에 있다"},{"term":"Cherry-pick","note":"— 작업 트리가 깨끗해야 시작되는 명령. 그 조건을 만들어 주는 것이 이것이다"},{"term":"Trunk Based Development","note":"— 가지를 자주 옮겨 다니게 만드는 방식. 서랍이 자주 필요해진다"},{"term":"CLI","note":"— `git stash` 를 실제로 치는 자리"}]},{"id":"tool--git-tag","term":"Git Tag","reading":"깃 태그","category":"개발 도구","summary":"Git Tag 는 **특정 커밋에 붙여 두는 움직이지 않는 이름표**다.","aliases":["git tag","깃 태그"],"related":[{"term":"Git","note":"— 태그를 담아 두는 버전 관리 도구"},{"term":"Git Branch","note":"— 커밋할 때마다 앞으로 옮겨지는 이름표. 태그는 그 반대다"},{"term":"Semantic Versioning","note":"— 태그에 적을 이름을 정하는 규칙"},{"term":"Build","note":"— 태그가 가리키는 그 상태로 결과물을 만든다"},{"term":"CI_CD","note":"— 어느 판을 내보낼지 태그 이름으로 골라 가는 자동화"}]},{"id":"tool--ide","term":"IDE","reading":"Integrated Development Environment","category":"개발 도구","summary":"IDE는 **개발에 쓰는 도구를 한 화면에 모아둔 프로그램**이다.","aliases":["ide","integrated development environment"],"related":[{"term":"CLI","note":"— IDE 밖에서 같은 일을 명령으로 하는 방법"},{"term":"Git","note":"— IDE 창 안에 붙어 있는 버전 관리 도구"},{"term":"Build","note":"— IDE 버튼 하나에 묶여 있는 과정"},{"term":"Terminal","note":"— IDE가 창 안에 넣어둔 명령 입력창"}]},{"id":"tool--linter-formatter","term":"Linter & Formatter","reading":"린터와 포매터","category":"개발 도구","summary":"린터는 **버그**를 찾고, 포매터는 모양을 맞추는 도구다.","aliases":["linter & formatter","린터와 포매터","linter","formatter"],"related":[{"term":"IDE","note":"— 저장할 때마다 이 둘을 돌려 주는 자리"},{"term":"CI_CD","note":"— 사람 눈 대신 기계가 이 검사를 강제하는 자리"},{"term":"Git","note":"— 모양을 안 맞춰 두면 diff 가 공백 변경으로 덮이는 자리"},{"term":"Package Manager","note":"— 린터와 포매터를 개발용 의존성으로 받아 두는 도구"}]},{"id":"tool--lock-file","term":"Lock File","reading":"잠금 파일","category":"개발 도구","summary":"잠금 파일은 **실제로 깔린 버전을 그대로 적어 둔 파일**이다.","aliases":["lock file","잠금 파일"],"related":[{"term":"Dependency","note":"— 잠금 파일이 버전을 못 박아 두는 대상"},{"term":"Package Manager","note":"— 이 파일을 만들고 읽는 도구"},{"term":"Git","note":"— 잠금 파일을 팀과 나눠 갖는 자리. 커밋해야 뜻이 생긴다"},{"term":"CI_CD","note":"— 잠금 파일 그대로 깔아야 하는 대표적인 자리"}]},{"id":"tool--merge-conflict","term":"Merge Conflict","reading":"병합 충돌","category":"개발 도구","summary":"병합 충돌은 **git 이 한쪽을 못 골라 사람에게 넘긴 상태**다.","aliases":["merge conflict","병합 충돌"],"related":[{"term":"Git","note":"— 충돌을 잡아내고 표시를 남기는 도구 그 자체"},{"term":"Pull Request","note":"— 충돌이 가장 자주 눈에 띄는 자리"},{"term":"CLI","note":"— 웹에서 못 고치는 충돌은 결국 여기서 고친다"},{"term":"CI_CD","note":"— 합친 결과가 실제로 도는지 확인하는 다음 단계"}]},{"id":"tool--merge-vs-rebase","term":"Merge vs Rebase","reading":"병합과 리베이스","category":"개발 도구","summary":"merge 와 rebase 는 가지를 합칠 때 **이력을 남길지 다시 쓸지**가 갈리는 두 방법이다.","aliases":["merge vs rebase","병합과 리베이스","merge","rebase"],"related":[{"term":"Git Branch","note":"— 이력을 갈라 놓는 쪽. merge 와 rebase 는 그것을 다시 합치는 쪽이다"},{"term":"Git Commit","note":"— merge 가 그대로 두고 rebase 가 새로 만드는 그 단위"},{"term":"Git","note":"— 이 두 명령이 들어 있는 도구"},{"term":"Hash","note":"— rebase 뒤에 값이 전부 달라지는 그 이름"}]},{"id":"tool--monorepo","term":"Monorepo","reading":"모노레포","category":"개발 도구","summary":"Monorepo 는 **여러 프로젝트를 저장소 하나에 함께 두는 방식**이다.","aliases":["monorepo","모노레포"],"related":[{"term":"Git","note":"— 모노레포도 결국 Git 저장소 하나다"},{"term":"Package Manager","note":"— 한 저장소 안의 패키지들을 서로 이어 붙이는 쪽"},{"term":"Package","note":"— 모노레포가 한 저장소에 여러 개 담는 그 단위"},{"term":"Monolith vs Microservices","note":"— 배포를 하나로 묶는 이야기. 저장소를 하나로 묶는 것과 다르다"},{"term":"CI_CD","note":"— 어느 폴더가 바뀌었을 때 무엇을 검사할지 정해야 하는 자리"}]},{"id":"tool--package-manager","term":"Package Manager","reading":"패키지 매니저","category":"개발 도구","summary":"패키지 매니저는 **남이 만든 코드를 받아다 놓아 주는** 도구다.","aliases":["package manager","패키지 매니저"],"related":[{"term":"Package","note":"— 패키지 매니저가 받아다 놓는 그 단위"},{"term":"Build","note":"— 받아 온 의존성을 묶어 실행할 것으로 만드는 다음 단계"},{"term":"SDK","note":"— 패키지 매니저로 받아 쓰는 대표적인 묶음"},{"term":"CLI","note":"— npm 이나 go 처럼 이 도구를 부리는 방식"}]},{"id":"tool--pull-request","term":"Pull Request","reading":"풀 리퀘스트","category":"개발 도구","summary":"풀 리퀘스트는 **변경을 합쳐 달라고 내는 제안**이다.","aliases":["pull request","풀 리퀘스트"],"related":[{"term":"Git","note":"— PR 이 얹혀 있는 아래층. 가지와 병합은 여기가 한다"},{"term":"Merge Conflict","note":"— 합치려는 순간 이 화면에 붙는 문제"},{"term":"CI_CD","note":"— PR 이 열릴 때마다 빌드와 시험을 자동으로 돌리는 짝"},{"term":"CLI","note":"— 웹에서 못 고치는 충돌을 여기서 고쳐 다시 올린다"}]},{"id":"tool--sdk","term":"SDK","reading":"Software Development Kit","category":"개발 도구","summary":"SDK는 **한 플랫폼에서 개발하는 데 필요한 것을 묶어 놓은 꾸러미**다.","aliases":["sdk","software development kit"],"related":[{"term":"IDE","note":"— SDK 를 얹어 작성과 디버깅을 한자리에서 하는 도구"},{"term":"Framework vs Library","note":"— SDK 와 자주 뒤섞이는 두 이름"},{"term":"Package","note":"— SDK 를 받아 설치할 때의 단위"},{"term":"Compile","note":"— SDK 에 딸려 오는 컴파일러가 하는 일"}]},{"id":"tool--semantic-versioning","term":"Semantic Versioning","reading":"유의적 버전","category":"개발 도구","summary":"Semantic Versioning 은 **세 자리 숫자로 호환을 약속하는 규칙**이다.","aliases":["semantic versioning","유의적 버전"],"related":[{"term":"Git Tag","note":"— 이 번호를 커밋에 이름표로 박아 두는 자리"},{"term":"Package Manager","note":"— 이 번호를 읽고 어떤 판을 받을지 정한다"},{"term":"Package","note":"— 이 번호가 붙는 단위"},{"term":"API","note":"— 깨졌는지 가리는 기준. 이 규칙은 공개 API 선언을 먼저 요구한다"}]},{"id":"tool--shell","term":"Shell","reading":"셸","category":"개발 도구","summary":"Shell은 **내가 친 명령을 알아듣고 실행하는 프로그램**이다.","aliases":["shell","셸"],"related":[{"term":"Terminal","note":"— 셸에 글자를 넘기고 결과를 그려주는 창"},{"term":"CLI","note":"— 셸에 명령을 적어 넣는 그 방식 자체"},{"term":"Environment Variable","note":"— 셸이 들고 있다가 띄우는 프로그램에 넘기는 값"},{"term":"Process","note":"— 셸이 명령마다 띄우는 실행 단위"},{"term":"Linux","note":"— 셸이 기본 조작 수단인 운영체제"}]},{"id":"tool--terminal","term":"Terminal","reading":"터미널","category":"개발 도구","summary":"Terminal은 **명령어를 치고 결과를 보는 창**이다.","aliases":["terminal","터미널"],"related":[{"term":"CLI","note":"— 글자로 명령을 주고받는 방식 그 자체"},{"term":"Environment Variable","note":"— PATH 처럼 Shell 설정 파일에 적어두는 값"},{"term":"SSH","note":"— 원격 서버의 Shell 을 내 터미널에 붙이는 방법"},{"term":"Git","note":"— 터미널에서 가장 많이 치게 되는 명령"}]},{"id":"tool--trunk-based-development","term":"Trunk Based Development","reading":"트렁크 기반 개발","category":"개발 도구","summary":"Trunk Based Development는 **모두가 한 줄기에 매일 합치는 방식**이다.","aliases":["trunk based development","트렁크 기반 개발"],"related":[{"term":"CI_CD","note":"— 규범 문서가 트렁크 기반 개발을 이것의 핵심 조건으로 든다"},{"term":"Git","note":"— 줄기와 가지를 실제로 만들고 합치는 도구"},{"term":"Cherry-pick","note":"— 줄기에서 고친 수정을 릴리스 가지로 내려보낼 때 쓰는 짝"},{"term":"Build","note":"— 가지를 줄기로 넣기 전에 통과해야 하는 자동 검사"},{"term":"DevOps","note":"— 커밋에서 배포까지를 한 줄기로 잇는 방식. 그 앞단의 분기 규칙이 이것이다"}]},{"id":"tool--term-e82c0160","term":"환경 변수","reading":"Environment Variable","category":"개발 도구","summary":"환경 변수는 **코드 밖에서 넣어주는 설정값**이다.","aliases":["환경 변수","environment variable"],"related":[{"term":"Docker","note":"— 컨테이너에 설정을 넘기는 방식이 환경 변수로 정리되어 있다"},{"term":"API Key","note":"— 코드에 두면 안 되는 대표적인 값"},{"term":"CI_CD","note":"— 배포 과정에서 환경별 값을 주입하는 자리"},{"term":"Git","note":"— `.env` 를 버전 관리에서 빼는 일이 여기서 벌어진다"}]}]},{"id":"ai","name":"AI · LLM","blurb":"요즘 제품에 들어가는 말들","terms":[{"id":"ai--ai-agent","term":"AI Agent","reading":"AI 에이전트","category":"AI · LLM","summary":"AI Agent는 **목표를 받아 스스로 도구를 써가며 일하는 AI**다.","aliases":["ai agent","ai 에이전트"],"related":[{"term":"LLM","note":"— 에이전트가 판단할 때 쓰는 자리"},{"term":"ReAct","note":"— 생각과 행동을 번갈아 하는 대표적인 동작 방식"},{"term":"MCP","note":"— 에이전트에 도구를 붙이는 규약"},{"term":"RAG","note":"— 에이전트가 외부 지식을 끌어오는 방법"},{"term":"Orchestrator","note":"— 에이전트 여럿을 묶어 순서를 정하는 쪽"}]},{"id":"ai--agent","term":"Agent","reading":"AI 에이전트","category":"AI · LLM","summary":"Agent는 **목표를 받아 스스로 도구를 쓰며 일을 끝내는 AI**다.","aliases":["agent","ai 에이전트"],"related":[{"term":"LLM","note":"— Agent가 다음 행동을 정할 때 쓰는 모델"},{"term":"ReAct","note":"— 생각과 행동을 번갈아 하는 대표적인 진행 방식"},{"term":"Prompt Engineering","note":"— 어떤 도구를 어떻게 쓸지 알려주는 지시문을 짜는 일"},{"term":"MCP","note":"— 도구를 Agent에 붙이는 규격"},{"term":"Fallback","note":"— 도구가 실패했을 때 대신 할 일"}]},{"id":"ai--cnn","term":"CNN","reading":"Convolutional Neural Network","category":"AI · LLM","summary":"CNN은 **이미지에서 무늬를 찾아내도록 만든 신경망**이다.","aliases":["cnn","convolutional neural network"],"related":[{"term":"Transformer","note":"— 이웃 대신 전체의 관계를 보는 다른 신경망 구조"},{"term":"Fine-tuning","note":"— 이미 학습된 CNN을 내 데이터에 맞게 다시 다듬는 일"},{"term":"Embedding","note":"— CNN이 뽑아낸 특징도 결국 숫자 벡터로 남는다"},{"term":"LLM","note":"— 언어를 다루는 쪽. CNN이 이미지에서 하는 일에 대응한다"}]},{"id":"ai--chunking","term":"Chunking","reading":"청킹, 문서 분할","category":"AI · LLM","summary":"Chunking은 **긴 문서를 검색할 크기로 잘라두는 일**이다.","aliases":["chunking","청킹, 문서 분할"],"related":[{"term":"Embedding","note":"— 잘라낸 조각을 벡터로 바꾸는 단계"},{"term":"RAG","note":"— 청킹이 쓰이는 자리"},{"term":"Vector DB","note":"— 조각과 벡터가 저장되는 곳"},{"term":"Semantic Search","note":"— 저장된 조각을 뜻으로 찾아내는 일"}]},{"id":"ai--context-window","term":"Context Window","reading":"컨텍스트 윈도우","category":"AI · LLM","summary":"Context Window는 **모델이 한 번에 볼 수 있는 글의 길이**다.","aliases":["context window","컨텍스트 윈도우"],"related":[{"term":"Token","note":"— 창 크기를 세는 단위"},{"term":"LLM","note":"— 이 한도를 갖는 주체"},{"term":"RAG","note":"— 창에 넣을 조각을 골라 오는 방법"},{"term":"Chunking","note":"— 긴 문서를 창에 들어갈 크기로 자르는 일"}]},{"id":"ai--cosine-similarity","term":"Cosine Similarity","reading":"코사인 유사도","category":"AI · LLM","summary":"Cosine Similarity는 **두 벡터가 같은 쪽을 보는지 재는 값**이다.","aliases":["cosine similarity","코사인 유사도"],"related":[{"term":"Embedding","note":"— 각도를 재려면 먼저 글을 벡터로 바꿔야 한다"},{"term":"Vector DB","note":"— 많은 벡터와의 각도를 빠르게 재주는 저장소"},{"term":"Semantic Search","note":"— 이 값을 써서 뜻으로 찾는 검색"},{"term":"RAG","note":"— 모델에 넘길 조각을 이 값으로 고른다"},{"term":"Reranking","note":"— 각도로 추린 뒤 다시 순서를 매기는 단계"}]},{"id":"ai--embedding","term":"Embedding","reading":"임베딩","category":"AI · LLM","summary":"Embedding은 **글이나 이미지를 뜻이 담긴 숫자 목록으로 바꾸는 것**이다.","aliases":["embedding","임베딩"],"related":[{"term":"Vector DB","note":"— 만들어진 벡터를 저장하고 가까운 것을 찾아주는 곳"},{"term":"RAG","note":"— 임베딩 검색을 답변 생성에 붙인 구조"},{"term":"Cosine Similarity","note":"— 두 벡터가 얼마나 가까운지 재는 방법"},{"term":"Semantic Search","note":"— 임베딩으로 하는 뜻 기반 검색"}]},{"id":"ai--escalation","term":"Escalation","reading":"에스컬레이션","category":"AI · LLM","summary":"Escalation은 **AI가 못 푸는 대화를 사람에게 넘기는 절차**다.","aliases":["escalation","에스컬레이션"],"related":[{"term":"AI Agent","note":"— 에스컬레이션을 판단하고 실행하는 주체"},{"term":"Fallback","note":"— 넘기기 전에 먼저 시도하는 대체 응답"},{"term":"Guardrail","note":"— 넘겨야 할 상황을 걸러내는 안전장치"},{"term":"Routing","note":"— 넘긴 건을 어느 담당자에게 보낼지 정하는 일"}]},{"id":"ai--fallback","term":"Fallback","reading":"폴백","category":"AI · LLM","summary":"Fallback은 **첫 시도가 실패했을 때 대신 쓰는 두 번째 방법**이다.","aliases":["fallback","폴백"],"related":[{"term":"Escalation","note":"— 폴백이 다 끝난 뒤에 사람에게 넘기는 단계"},{"term":"Circuit Breaker","note":"— 죽은 곳을 아예 부르지 않게 막는 장치. 폴백과 짝으로 쓴다"},{"term":"Routing","note":"— 첫 번째로 어디에 물어볼지 고르는 쪽"},{"term":"RAG","note":"— 폴백 순서에 자주 들어가는 문서 검색 방식"}]},{"id":"ai--few-shot-zero-shot-learning","term":"Few-shot & Zero-shot Learning","reading":"","category":"AI · LLM","summary":"Zero-shot과 Few-shot은 **프롬프트에 예시를 몇 개 넣느냐**로 갈리는 지시 방식이다.","aliases":["few-shot & zero-shot learning","few-shot & zero-shot","few-shot","zero-shot learning"],"related":[{"term":"Prompt","note":"— 예시가 실제로 들어가 앉는 자리"},{"term":"LLM","note":"— 예시를 읽고 형식을 맞추는 쪽"},{"term":"Fine-tuning","note":"— 예시를 모델에 새겨 넣는 다른 길"},{"term":"Context Window","note":"— 예시를 몇 개까지 붙일 수 있는지를 정하는 한계"},{"term":"RAG","note":"— 예시 대신 문서를 붙여 넣는 방법. 같이 쓰기도 한다"}]},{"id":"ai--fine-tuning","term":"Fine-tuning","reading":"파인튜닝, 미세 조정","category":"AI · LLM","summary":"Fine-tuning은 **이미 학습된 모델에 예시를 더 먹여 다시 학습시키는 일**이다.","aliases":["fine-tuning","파인튜닝, 미세 조정"],"related":[{"term":"LLM","note":"— 파인튜닝의 대상이 되는 모델"},{"term":"RAG","note":"— 학습 대신 문서를 찾아 넣어주는 다른 접근"},{"term":"Prompt","note":"— 학습 없이 지시문만으로 조정하는 방법"},{"term":"Token","note":"— 학습 비용과 요청 비용을 세는 단위"},{"term":"Few-shot & Zero-shot","note":"— 예시를 요청 안에 몇 개만 넣어보는 중간 방법"}]},{"id":"ai--guardrail","term":"Guardrail","reading":"가드레일","category":"AI · LLM","summary":"Guardrail은 **AI가 하면 안 되는 일을 막는 검사 장치**다.","aliases":["guardrail","가드레일"],"related":[{"term":"PII","note":"— Guardrail이 입력과 출력 양쪽에서 찾아내는 정보"},{"term":"AI Agent","note":"— Guardrail이 감싸는 대상"},{"term":"Audit Log","note":"— 막힌 시도를 남겨두는 곳"},{"term":"RBAC","note":"— 행동 검사에서 권한을 볼 때 쓰는 기준"},{"term":"Escalation","note":"— 막은 다음 사람에게 넘겨야 할 때의 절차"}]},{"id":"ai--hallucination","term":"Hallucination","reading":"환각","category":"AI · LLM","summary":"Hallucination은 **모델이 사실이 아닌 것을 사실처럼 말하는 현상**이다.","aliases":["hallucination","환각"],"related":[{"term":"LLM","note":"— 환각이 나오는 구조 자체"},{"term":"RAG","note":"— 지어낼 필요를 줄이는 대표적인 대응"},{"term":"Prompt Engineering","note":"— 출처를 강제하는 지시를 짜는 일"},{"term":"Fine-tuning","note":"— 특정 분야에서 환각을 줄이는 다른 방법"}]},{"id":"ai--intent","term":"Intent 분류","reading":"Intent Classification","category":"AI · LLM","summary":"Intent 분류는 **사용자 말에서 무엇을 원하는지 골라내는 일**이다.","aliases":["intent 분류","intent classification"],"related":[{"term":"Routing","note":"— 분류 결과에 따라 어디로 보낼지 정하는 다음 단계"},{"term":"Orchestrator","note":"— 나뉜 갈래들을 묶어 전체 흐름을 이끄는 쪽"},{"term":"LLM","note":"— 맥락까지 보는 분류에 쓰이는 모델"},{"term":"AI Agent","note":"— 정해진 갈래를 실제로 처리하는 쪽"},{"term":"Few-shot & Zero-shot","note":"— 예시 몇 개로 분류 정확도를 올리는 방법"}]},{"id":"ai--llm","term":"LLM","reading":"Large Language Model","category":"AI · LLM","summary":"LLM은 **다음에 올 단어를 확률로 고르는 모델**이다.","aliases":["llm","large language model"],"related":[{"term":"Token","note":"— 모델이 다루는 최소 단위이자 비용의 단위"},{"term":"Hallucination","note":"— 근거 없이 그럴듯한 말을 만드는 현상"},{"term":"RAG","note":"— 답의 근거를 밖에서 찾아 넣어주는 방법"},{"term":"Transformer","note":"— 지금 LLM 대부분이 쓰는 구조"}]},{"id":"ai--orchestrator","term":"Orchestrator","reading":"오케스트레이터","category":"AI · LLM","summary":"Orchestrator 는 **요청을 보고 어느 Agent 에게 맡길지 정하는 층**이다.","aliases":["orchestrator","오케스트레이터"],"related":[{"term":"AI Agent","note":"— Orchestrator 가 골라서 부르는 실행 단위"},{"term":"Intent 분류","note":"— 질문을 갈래로 나눈 결과"},{"term":"Fallback","note":"— 맡은 Agent 가 실패했을 때 넘어갈 곳"},{"term":"LLM","note":"— 갈래를 정하고 답을 합치는 데 쓰이는 모델"},{"term":"RAG","note":"— 문서 검색을 맡은 Agent 가 쓰는 방식"}]},{"id":"ai--prompt","term":"Prompt","reading":"프롬프트","category":"AI · LLM","summary":"Prompt는 **LLM 에게 무엇을 어떻게 해달라고 적어 보내는 글**이다.","aliases":["prompt","프롬프트"],"related":[{"term":"Prompt Engineering","note":"— 프롬프트를 다듬는 일을 따로 부르는 이름"},{"term":"Few-shot & Zero-shot","note":"— 예시를 몇 개 넣느냐로 갈리는 두 방식"},{"term":"Context Window","note":"— 프롬프트가 들어갈 수 있는 크기의 한계"},{"term":"Fine-tuning","note":"— 프롬프트가 아니라 모델 자체를 고치는 쪽"},{"term":"Hallucination","note":"— 프롬프트로 줄이려는 대표적인 문제"}]},{"id":"ai--prompt-engineering","term":"Prompt Engineering","reading":"프롬프트 엔지니어링","category":"AI · LLM","summary":"Prompt Engineering은 **원하는 답이 나오도록 질문을 설계하는 기술**이다.","aliases":["prompt engineering","프롬프트 엔지니어링"],"related":[{"term":"LLM","note":"— 프롬프트를 받아 답을 만드는 모델"},{"term":"Few-shot & Zero-shot","note":"— 예시를 몇 개 주느냐로 갈리는 두 가지 방식"},{"term":"RAG","note":"— 모델이 모르는 사실을 프롬프트에 실어 넣는 방법"},{"term":"Token","note":"— 프롬프트를 길게 쓸수록 늘어나는 단위"}]},{"id":"ai--rag","term":"RAG","reading":"Retrieval-Augmented Generation","category":"AI · LLM","summary":"RAG는 **답하기 전에 관련 문서를 찾아 같이 넣어주는 방식**이다.","aliases":["rag","retrieval-augmented generation"],"related":[{"term":"Embedding","note":"— 문서와 질문을 벡터로 바꾸는 단계"},{"term":"Vector DB","note":"— 그 벡터를 저장하고 가까운 것을 찾아주는 곳"},{"term":"Hallucination","note":"— RAG가 줄이려는 대상"},{"term":"Chunking","note":"— 문서를 어떻게 자를지 정하는 일"}]},{"id":"ai--react","term":"ReAct","reading":"Reasoning + Acting","category":"AI · LLM","summary":"ReAct는 **생각과 행동을 번갈아 하는 AI 에이전트 방식**이다.","aliases":["react","reasoning + acting"],"related":[{"term":"AI Agent","note":"— ReAct는 에이전트를 굴리는 대표적인 방식이다"},{"term":"Prompt Engineering","note":"— 생각과 행동을 나눠 적게 하는 것이 이 방식의 프롬프트다"},{"term":"Hallucination","note":"— 도구로 확인하게 해서 줄이려는 대상"},{"term":"LangGraph","note":"— 이 반복을 흐름으로 짜서 돌리는 도구"},{"term":"RAG","note":"— 찾아온 자료로 답하게 한다는 점이 겹친다"}]},{"id":"ai--reranking","term":"Reranking","reading":"재순위화","category":"AI · LLM","summary":"Reranking은 **먼저 뽑아온 검색 결과의 순위를 다시 매기는 단계**다.","aliases":["reranking","재순위화"],"related":[{"term":"RAG","note":"— 리랭킹이 끼어드는 전체 흐름"},{"term":"Embedding","note":"— 1차 검색이 쓰는 벡터를 만드는 일"},{"term":"Vector DB","note":"— 그 벡터를 담아두고 빠르게 훑는 곳"},{"term":"Semantic Search","note":"— 리랭킹이 순서를 고쳐주는 1차 검색 방식"},{"term":"Cosine Similarity","note":"— 1차에서 벡터끼리 거리를 재는 방법"}]},{"id":"ai--routing","term":"Routing","reading":"라우팅","category":"AI · LLM","summary":"Routing은 **요청을 어느 처리자에게 넘길지 정하는 일**이다.","aliases":["routing","라우팅"],"related":[{"term":"Intent 분류","note":"— 라우팅이 판단 근거로 쓰는 앞 단계"},{"term":"Orchestrator","note":"— 여럿을 부르고 결과를 합치는 쪽. 라우터 다음 단계"},{"term":"AI Agent","note":"— 라우터가 골라서 넘기는 대상"},{"term":"Fallback","note":"— 어느 쪽도 확실하지 않을 때 가는 자리"}]},{"id":"ai--semantic-search","term":"Semantic Search","reading":"의미 검색","category":"AI · LLM","summary":"Semantic Search는 **낱말이 달라도 뜻이 비슷하면 찾아주는 검색**이다.","aliases":["semantic search","의미 검색"],"related":[{"term":"Embedding","note":"— 문장을 숫자 배열로 바꾸는 그 변환"},{"term":"Vector DB","note":"— 바꿔 놓은 배열을 담고 거리로 찾아주는 저장소"},{"term":"Cosine Similarity","note":"— 두 배열이 얼마나 가까운지 재는 방법"},{"term":"RAG","note":"— 이 검색을 앞에 두고 답을 만드는 구조"},{"term":"Reranking","note":"— 골라온 결과의 순서를 한 번 더 손보는 단계"}]},{"id":"ai--text-to-sql","term":"Text-to-SQL","reading":"","category":"AI · LLM","summary":"Text-to-SQL은 **말로 물으면 SQL을 만들어주는 기술**이다.","aliases":["text-to-sql"],"related":[{"term":"SQL","note":"— 최종적으로 만들어져 DB로 가는 것"},{"term":"LLM","note":"— 질문과 스키마를 보고 쿼리를 만드는 모델"},{"term":"Hallucination","note":"— 없는 표 이름을 지어내는 현상"},{"term":"QueryPie","note":"— 만들어진 쿼리를 실행 전에 거르는 보안 게이트"}]},{"id":"ai--token","term":"Token","reading":"토큰","category":"AI · LLM","summary":"Token은 **모델이 글을 다루는 최소 조각**이다.","aliases":["token","토큰"],"related":[{"term":"LLM","note":"— 토큰을 예측하는 것이 이 모델이 하는 일의 전부다"},{"term":"Context Window","note":"— 토큰으로 세는 한 번에 볼 수 있는 양"},{"term":"Embedding","note":"— 토큰을 벡터로 바꾸는 다음 단계"},{"term":"Prompt Engineering","note":"— 같은 지시를 적은 토큰으로 쓰는 일이 여기 포함된다"}]},{"id":"ai--transformer","term":"Transformer","reading":"트랜스포머","category":"AI · LLM","summary":"Transformer는 **문장을 한꺼번에 펼쳐 놓고 서로의 관계를 재는 구조**다.","aliases":["transformer","트랜스포머"],"related":[{"term":"LLM","note":"— 이 구조 위에 세워진 모델들"},{"term":"Token","note":"— Transformer 가 다루는 조각의 단위"},{"term":"Embedding","note":"— 그 조각을 숫자 배열로 바꾼 것"},{"term":"Context Window","note":"— 한 번에 펼쳐 놓을 수 있는 조각 수의 한계"},{"term":"Fine-tuning","note":"— 학습된 Transformer 를 특정 용도로 다시 손보는 일"}]},{"id":"ai--vector-db","term":"Vector DB","reading":"벡터 데이터베이스","category":"AI · LLM","summary":"Vector DB는 **벡터를 저장하고 가까운 것을 빠르게 찾아주는 저장소**다.","aliases":["vector db","벡터 데이터베이스"],"related":[{"term":"Embedding","note":"— 여기에 저장될 벡터를 만드는 단계"},{"term":"RAG","note":"— 벡터 DB를 답변 생성에 붙인 구조"},{"term":"Index","note":"— 빠른 검색을 위해 미리 만들어두는 구조"},{"term":"Semantic Search","note":"— 벡터 DB로 하는 뜻 기반 검색"}]}]},{"id":"pm","name":"제품 관리","blurb":"무엇을 왜 만드는지 정하는 말","terms":[{"id":"pm--a-b-testing","term":"A/B Testing","reading":"A/B 테스트","category":"제품 관리","summary":"A/B Testing은 **두 버전을 동시에 내보내 어느 쪽이 나은지 재는 실험**이다.","aliases":["a/b testing","a/b 테스트","a b testing"],"related":[{"term":"KPI","note":"— 실험에서 무엇을 이겼다고 볼지 정하는 지표"},{"term":"Funnel","note":"— 어느 단계의 전환율을 실험 대상으로 삼을지 알려준다"},{"term":"MVP","note":"— 실험할 것을 최소한으로 만들어 먼저 내보내는 방식"},{"term":"Persona","note":"— 누구를 놓고 가설을 세울지 정해준다"}]},{"id":"pm--agile","term":"Agile","reading":"애자일","category":"제품 관리","summary":"Agile은 **짧게 만들어 보여주고 고쳐 나가는 개발 방식**이다.","aliases":["agile","애자일"],"related":[{"term":"Scrum","note":"— 애자일을 2주 주기로 실천하는 대표적인 틀"},{"term":"Sprint","note":"— 그 한 바퀴에 해당하는 기간"},{"term":"Backlog","note":"— 다음 바퀴에 무엇을 넣을지 고르는 목록"},{"term":"MVP","note":"— 첫 바퀴에 어디까지만 만들지 정하는 기준"},{"term":"User Story","note":"— 한 바퀴에 담을 일을 적는 형식"}]},{"id":"pm--backlog","term":"Backlog","reading":"백로그","category":"제품 관리","summary":"Backlog는 **아직 안 한 일을 우선순위대로 세워둔 목록**이다.","aliases":["backlog","백로그"],"related":[{"term":"User Story","note":"— 백로그에 들어가는 항목을 적는 형식"},{"term":"Sprint","note":"— 백로그 위쪽을 꺼내 진행하는 한 주기"},{"term":"Agile","note":"— 백로그를 계속 다시 세우는 것을 전제로 하는 방식"},{"term":"Product Roadmap","note":"— 백로그보다 위에서 방향을 잡는 계획"},{"term":"MVP","note":"— 첫 출시에 넣을 항목을 고르는 기준"}]},{"id":"pm--cac-ltv","term":"CAC / LTV","reading":"고객 획득 비용과 생애 가치","category":"제품 관리","summary":"CAC 와 LTV 는 **고객 한 명에 드는 돈과 그 고객이 주는 돈**이다.","aliases":["cac / ltv","고객 획득 비용과 생애 가치","cac ltv","cac","ltv"],"related":[{"term":"North Star Metric","note":"— 이 숫자들 위에 놓는 하나의 대표 지표"},{"term":"Retention","note":"— 유지 기간을 늘려 LTV 를 키우는 쪽"},{"term":"Funnel","note":"— 전환율이 오르면 같은 비용으로 CAC 가 내려간다"},{"term":"OKR","note":"— 이 숫자들을 목표로 잡아 관리할 때 쓰는 틀"}]},{"id":"pm--crm","term":"CRM","reading":"Customer Relationship Management","category":"제품 관리","summary":"CRM은 **고객과 주고받은 일을 한곳에 모아두는 시스템**이다.","aliases":["crm","customer relationship management"],"related":[{"term":"Funnel","note":"— 고객이 단계를 밟아 내려가는 흐름. 파이프라인이 이걸 그린 것"},{"term":"KPI","note":"— 전환율이나 성사율처럼 CRM 기록에서 뽑아내는 숫자"},{"term":"CAC LTV","note":"— 한 고객을 데려오는 비용과 그 고객이 남기는 값. CRM 데이터로 계산한다"},{"term":"PII","note":"— CRM에 쌓이는 개인정보. 다루는 방식이 따로 정해져 있다"}]},{"id":"pm--funnel","term":"Funnel","reading":"퍼널","category":"제품 관리","summary":"Funnel은 **사용자가 목표까지 가며 줄어드는 단계별 흐름**이다.","aliases":["funnel","퍼널"],"related":[{"term":"Retention","note":"— 퍼널의 아래쪽에서 다시 돌아오는지를 보는 지표"},{"term":"A B Testing","note":"— 병목으로 지목된 칸을 고칠 때 쓰는 방법"},{"term":"KPI","note":"— 각 칸의 통과율을 지표로 삼은 것"},{"term":"North Star Metric","note":"— 여러 칸의 개선이 결국 움직여야 할 하나의 숫자"}]},{"id":"pm--gtm","term":"GTM","reading":"Go-to-Market","category":"제품 관리","summary":"GTM은 **만든 것을 누구에게 어떻게 팔지 정하는 계획**이다.","aliases":["gtm","go-to-market"],"related":[{"term":"PMF","note":"— 팔릴 물건인지부터 확인하는 단계. GTM은 그다음이다"},{"term":"Persona","note":"— GTM이 좁힌 대상을 사람 모양으로 적어둔 것"},{"term":"Funnel","note":"— 정한 채널에서 고객이 실제로 어디서 빠지는지 보는 틀"},{"term":"MVP","note":"— 작게 내놓고 반응을 보는 방식. GTM의 첫 실행이 되기도 한다"},{"term":"CAC LTV","note":"— 고른 채널이 남는 장사인지 판정하는 숫자"}]},{"id":"pm--kpi","term":"KPI","reading":"Key Performance Indicator","category":"제품 관리","summary":"KPI는 **목표에 얼마나 다가갔는지 재는 숫자**다.","aliases":["kpi","key performance indicator"],"related":[{"term":"OKR","note":"— 목표를 세우는 틀. KPI는 그 목표를 재는 눈금이다"},{"term":"North Star Metric","note":"— 여러 KPI 위에 하나만 세우는 대표 지표"},{"term":"Retention","note":"— 사용자가 남는지를 보는 대표적인 제품 KPI"},{"term":"Funnel","note":"— 단계마다 KPI를 두어 어디서 새는지 찾는 방법"}]},{"id":"pm--mvp","term":"MVP","reading":"Minimum Viable Product","category":"제품 관리","summary":"MVP는 **가설을 확인할 만큼만 만들어 내놓는 제품**이다.","aliases":["mvp","minimum viable product"],"related":[{"term":"Agile","note":"— 짧게 만들고 반응을 보는 이 방식을 담은 개발 방법론"},{"term":"Sprint","note":"— MVP를 한 조각씩 만들어 내는 짧은 작업 주기"},{"term":"User Story","note":"— 무엇이 최소인지 가릴 때 기능을 적는 단위"},{"term":"Product Roadmap","note":"— MVP로 확인한 다음에 무엇을 붙일지 그리는 계획"}]},{"id":"pm--north-star-metric","term":"North Star Metric","reading":"북극성 지표","category":"제품 관리","summary":"North Star Metric은 **제품의 가치를 대표하는 지표 하나**다.","aliases":["north star metric","북극성 지표"],"related":[{"term":"KPI","note":"— 여러 지표 중 맨 위에 두는 하나가 북극성 지표다"},{"term":"OKR","note":"— 목표를 세울 때 이 지표가 그 자리에 들어간다"},{"term":"PMF","note":"— 이 지표가 일정 수준을 넘으면 시장에 맞았다는 신호로 읽는다"},{"term":"Retention","note":"— 북극성 지표를 떠받치는 대표적인 입력 지표"},{"term":"Funnel","note":"— 지표를 올리려면 어느 단계에서 새는지 봐야 한다"}]},{"id":"pm--okr","term":"OKR","reading":"Objectives and Key Results","category":"제품 관리","summary":"OKR은 **목표 하나에 달성 여부를 잴 숫자를 붙이는 틀**이다.","aliases":["okr","objectives and key results"],"related":[{"term":"KPI","note":"— 지키려고 보는 숫자. OKR 은 밀어붙이려고 보는 숫자다"},{"term":"North Star Metric","note":"— 회사가 오래 보는 숫자 하나. OKR 은 분기마다 바뀐다"},{"term":"Product Roadmap","note":"— OKR 이 정한 방향을 일정으로 옮긴 것"},{"term":"Sprint","note":"— 분기 단위 OKR 을 주 단위 일감으로 쪼개는 자리"}]},{"id":"pm--pmf","term":"PMF","reading":"Product Market Fit","category":"제품 관리","summary":"PMF는 **제품이 시장의 필요와 맞아떨어진 상태**다.","aliases":["pmf","product market fit"],"related":[{"term":"MVP","note":"— PMF를 찾기 위해 최소한으로 만들어 보는 것"},{"term":"Retention","note":"— PMF를 재는 가장 직접적인 지표"},{"term":"North Star Metric","note":"— PMF 이후 성장을 이끌 하나의 숫자"},{"term":"Funnel","note":"— 가입에서 사용까지 어디서 새는지 보는 틀"},{"term":"KPI","note":"— PMF 지표를 조직의 목표로 옮긴 것"}]},{"id":"pm--persona","term":"Persona","reading":"페르소나","category":"제품 관리","summary":"Persona는 **조사한 사용자들을 한 사람으로 좁혀 적어둔 것**이다.","aliases":["persona","페르소나"],"related":[{"term":"User Story","note":"— 페르소나를 주어로 놓고 쓰는 작업 단위"},{"term":"MVP","note":"— 이 사람의 고충 하나만 먼저 풀어보는 방식"},{"term":"A B Testing","note":"— 페르소나에서 세운 가설을 숫자로 확인하는 쪽"},{"term":"PMF","note":"— 정한 사람들이 실제로 이걸 필요로 하는지를 묻는 단계"}]},{"id":"pm--product-roadmap","term":"Product Roadmap","reading":"제품 로드맵","category":"제품 관리","summary":"Product Roadmap 은 **무엇을 왜 먼저 하는지 적어 공유하는 문서**다.","aliases":["product roadmap","제품 로드맵"],"related":[{"term":"MVP","note":"— 로드맵의 첫 구간에 놓이는 최소 형태"},{"term":"OKR","note":"— 로드맵이 겨누는 목표를 숫자로 적은 것"},{"term":"Backlog","note":"— 로드맵 아래에 놓이는 상세 항목 목록"},{"term":"Sprint","note":"— 로드맵을 실제로 실행하는 단위"},{"term":"Agile","note":"— 로드맵을 자주 고쳐가며 실행하는 방식"}]},{"id":"pm--retention","term":"Retention","reading":"리텐션, 유지율","category":"제품 관리","summary":"Retention은 **가입한 사람 중 다시 돌아온 비율**이다.","aliases":["retention","리텐션, 유지율"],"related":[{"term":"PMF","note":"— 곡선이 평평해지는 것을 그 신호로 본다"},{"term":"Funnel","note":"— 가입까지 오는 과정. 리텐션은 그 뒤를 본다"},{"term":"CAC LTV","note":"— 데려오는 비용과 남아서 만드는 값. 리텐션이 뒷값을 정한다"},{"term":"North Star Metric","note":"— 리텐션과 이어지는 지표를 회사의 기준으로 삼는다"},{"term":"KPI","note":"— 리텐션을 그중 하나로 두는 경우가 많다"}]},{"id":"pm--scrum","term":"Scrum","reading":"스크럼","category":"제품 관리","summary":"Scrum은 **짧은 주기를 반복해 제품을 만드는 방식**이다.","aliases":["scrum","스크럼"],"related":[{"term":"Agile","note":"— 스크럼이 따르는 생각. 스크럼은 그 실행 방식 중 하나다"},{"term":"Sprint","note":"— 범위를 고정하고 돌리는 한 주기"},{"term":"Backlog","note":"— 만들 것을 우선순위 순으로 쌓아둔 목록"},{"term":"User Story","note":"— 백로그 항목을 사용자 관점으로 쓰는 형식"}]},{"id":"pm--sprint","term":"Sprint","reading":"스프린트","category":"제품 관리","summary":"Sprint는 **정해둔 기간 안에 쓸 수 있는 결과를 내는 작업 주기**다.","aliases":["sprint","스프린트"],"related":[{"term":"Scrum","note":"— 스프린트를 축으로 삼는 진행 방식"},{"term":"Backlog","note":"— 스프린트에 담을 것을 꺼내오는 목록"},{"term":"Agile","note":"— 짧게 만들고 반응을 보는 큰 흐름"},{"term":"User Story","note":"— 스프린트에 담기는 일감의 단위"}]},{"id":"pm--user-story","term":"User Story","reading":"사용자 스토리","category":"제품 관리","summary":"User Story는 **누가 무엇을 왜 원하는지 짧게 적은 요구사항**이다.","aliases":["user story","사용자 스토리"],"related":[{"term":"Agile","note":"— 스토리라는 형식이 나온 배경"},{"term":"Sprint","note":"— 스토리 하나가 들어가야 할 기간 단위"},{"term":"Backlog","note":"— 아직 손대지 않은 스토리가 쌓이는 곳"},{"term":"MVP","note":"— 먼저 만들 스토리만 골라낸 묶음"},{"term":"Persona","note":"— 스토리 첫 줄의 역할을 구체적으로 정해둔 것"}]},{"id":"pm--wireframe","term":"Wireframe","reading":"와이어프레임","category":"제품 관리","summary":"Wireframe은 **색과 꾸밈을 뺀 화면 설계도**다.","aliases":["wireframe","와이어프레임"],"related":[{"term":"User Story","note":"— 스토리에 적힌 것이 화면 어디에 놓이는지 맞춰보는 자리"},{"term":"MVP","note":"— 먼저 만들 화면만 골라낼 때 함께 본다"},{"term":"Persona","note":"— 이 화면을 볼 사람이 누구인지 정해둔 것"},{"term":"Agile","note":"— 짧게 그리고 자주 고치는 방식이 나온 배경"}]}]}];
